quests[26594] = { id = 26594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu MacKinley", description = "Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich alles zurückzahlen wollte! Ich schwöre es!!\n\nIch war nur ein bisschen betrunken und habe mich verlaufen... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!", sourceObjective = "Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley.", progress = "Da seid Ihr ja, {name}. Habt Ihr Zitterhands Bezahlung?", completion = "Heh heh, gut gemacht! Wie stark hat Zitterhand denn gezittert, als Ihr ihm die Eingeweide gezeigt habt?\n\nHah! Man kann ihn so leicht lesen, wenn man mit ihm Karten spielt, da muss man einfach gewinnen!\n\nMeinen Dank für Eure Hilfe, {name}. Jetzt sollt Ihr bezahlt werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[26595] = { id = 26595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rien ne va plus - Nichts geht mehr", description = "Es gibt drei Phasen bei der Schuldeneintreibung: höflich fragen, energisch fragen und etwas, das ich als \"Phase Drei\" bezeichne.\n\nLeider bin ich alter Hund zu Phase Drei nicht mehr in der Lage. Deshalb muss ich so viele Kumpane, Handlanger, Angeber, Schläger und edle Abenteurer wie Euch einstellen!\n\nJans Fitzpünktchen, Ephram Mondsturz and Maury Wilkins verstecken sich an der östlichen Küste. Ihr solltet alle drei problemlos bei einem Ausflug abklappern können... Bringt mir ihren wertvollsten Besitz.", sourceObjective = "Besorgt Maurys Klumpfuß, Fitzpünktchens Drehmomentschlüssel mit Ratsche und Ephrams juwelenbesetzten Spiegel.", progress = "{name}, habt Ihr die Schuldner gefunden?", completion = "Großartig! Die werden gutes Geld bringen, vor allem das, was sich in Maurys Fuß befindet! Vielen Dank, {name}!\n\nIch hoffe, die drei haben ihre Lektion gelernt. Man soll nie etwas verwetten, was man nicht aufgeben kann.\n\nVielleicht ist es für sie zu spät, aber... sie sollten gut darüber nachdenken, mit wem sie spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26596] = { id = 26596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf von Kalimdor", description = "Ich wurde von den guten Leuten von Theramore geschickt, um loyale Mitglieder der Allianz zu finden, die Lady Jaina mit einigen Problemen in den Düstermarschen aushelfen kann.\n\nIhr wart doch nicht wirklich hier, um für die Goblins zu arbeiten, oder?\n\nDer Weg in die Düstermarschen führt durch Ratschet. Sprecht dort mit Gazlowe. Er wird euch von dort aus die richtige Richtung zeigen.\n\nIgitt... ich glaube, ich bin auf einen Fisch getreten! Und er hat gezappelt!", sourceObjective = "Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.", completion = "Ja? Was braucht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[26597] = { id = 26597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlingendornfieber", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... \n\n...um genau zu sein, SchlingendornKAPfieber...\n\n...tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", sourceObjective = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizrackett.", progress = "... Mutter?\n\n... so kalt... \n\n... ich fahre hinab in den Wirbelnden Nether... h-h-h-halt mich fest, Mutter...", completion = "... fühle die Kraft zurückkehren... \n\nWo bin ich? Beutebucht? Ach du meine Güte! Ich hatte einen seltsamen Traum... \n\n... die Schwäche hat mich nicht vollständig verlassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26598] = { id = 26598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz von Mokk", progress = "Hexendoktor Unbagwa weiß, was Mokk der Wilde mag. Ja, ja!\n\nIch sprechen mit Geistern und mach er kommen, tue ich.\n\nAber andere Gorillabiester mögen Geistersprechen auch. Du beschützt Hexendoktor Unbagwa und ich mach ihn kommen zu dir.\n\nHexendoktor Unbagwa will zuerst etwas. Du bringst Gorillafangzahn und ich lasse Geister reden!", completion = "Hexendoktor Unbagwa mag Gorillafangzähne! Für dich ich reden mit Geister. Lasse Mokk den Wilden kommen.\n\nDu beschützt Hexendoktor Unbagwa vor anderen Gorillabiestern, sonst kein Mokk für dich!" }
quests[26599] = { id = 26599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truhe des Kapitäns", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratschet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Beutebucht gesteckt. Ich werde nicht ruhen, bis ihre Leichen auf dem Meeresboden verstreut liegen!\n\n Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Ich habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", sourceObjective = "Erhaltet Smotts' Truhe von Gorlash am Schlingendornkap.", progress = "Ahoi, {name}! Habt Ihr Gorlash finden können? Die Truhe war mein Lieblingsstück und sie hatte ein Geheimfach, mit meinen größten Schätzen.", completion = "Ihr habt sie gefunden! Das ist ein wunderbarer Tag für den alten Hecklebury! Dass ich meine Truhe wiederbekommen habe, beruhigt mich ein wenig.\n\nAber meine Rache ist noch nicht vollständig...", sourceObjectiveStatus = "unverified-source-field" }
quests[26600] = { id = 26600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein riesiges Bankett", description = "Der nächste Riese auf meiner Liste nennt sich Negolash. Ich sehe noch vor mir, wie er aus der Gischt sprang und den armen Poopdeck-Paul aus dem Krähennest riss.\n\nVerschlang ihn in einem Bissen... Auf dem Weg nach unten brach er noch meinen Kreuzmast in zwei Teile.\n\nKeines meiner Besatzungsmitglieder hat einen so schrecklichen Tod verdient. Also werden wir Negolashs Appetit gegen ihn verwenden. Kelsey Yance verkauft Euch bestimmt etwas Fleisch, und Klein Whiskeys Schnaps reicht aus, um einen... nun, einen Meeresriesen umzuhauen. Ihr werdet beide in der Stadt finden.", sourceObjective = "Kauft eine Kiste mit Fleisch der Güteklasse E von Kelsey Yance und eine Kiste mit Pupellyverbos Portwein von Klein Whiskey.", progress = "Wir werden viel Essen brauchen, {name}. Unser Ziel ist Quantität, nicht Qualität.", completion = "Das war doch nicht teuer, oder? Hier, nehmt ein paar Münzen als Entschädigung.\n\nUnd jetzt legen wir mit meiner Rache los, einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[26601] = { id = 26601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mok'rash der Spalter", description = "Mok'rash der Spalter ist der letzte Riese. Und der größte, wenn ich mich recht entsinne. Größer als eine Welle im Orkan, mit einem Bart wie ein Tangwald und einem Hammer mächtig wie eine Eiche.\n\nEr verhöhnt mich von der Janeirospitze, der Insel kurz vor diesem Pier. Nur wegen ihm sitze ich immer noch hier fest und friste mein Dasein als Landratte.\n\nWenn Ihr schwimmen könnt, dann macht Euch auf den Weg zur Janeirospitze und tötet Mok'rash.\n\nSeid vorsichtig, {name}. Mok'rash wird sich nicht so leicht geschlagen geben wie seine Brüder.", sourceObjective = "Tötet Mok'rash den Spalter auf der Janeirospitze.", completion = "Mo'krash... Negolash... Gorlash... sie sind alle tot.\n\nJetzt habe ich wohl keine Entschuldigung mehr. Ich kann auf die weiten Meere zurückkehren und wieder plündern und stehlen! Und das alles dank Euch.\n\nJetzt brauche ich nur noch ein Schiff....", sourceObjectiveStatus = "unverified-source-field" }
quests[26602] = { id = 26602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesenportionen erwünscht", description = "Nehmt das Essen und legt es in unser altes Rettungsboot südöstlich von hier an der Küste. Wenn Negolash das ganze Essen riecht, wird er angerannt kommen!\n\nUnd dann erwartet ihn bereits <ein beherzter/eine beherzte:c> {class}, <der/die:c> seinen Kadaver zurück in die salzige Tiefe schleudern wird.", sourceObjective = "Legt die Riesenkiste Riesenessen in Captain Smotts'Rettungsboot. Beschwört Negolash damit und tötet ihn.", completion = "Ich kann mein Glück kaum fassen, {name}! Mein Glück hat sich zum Besseren gewendet, seit ich Euch getroffen habe, so viel ist sicher!\n\nSollte ich ein neues Schiff bekommen und solltet Ihr je auf See gehen wollen, dann werdet Ihr mein Ehrengast sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26603] = { id = 26603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flaschenpost", description = "In der Flasche findet Ihr eine Notiz, auf der Folgendes, in recht guter Handschrift, steht:\n\n<An alle, die mir helfen können:>\n\n<Bitte, ich benötige dringend Hilfe. Eine große Bestie hält mich auf einer Insel in den Südlichen Meeren gefangen.>\n\n<Die Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die Küstenlinie im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.>\n\n<Ich flehe Euch an, mein möglicher Retter, bitte helft mir.>", sourceObjective = "Sucht den Schreiber der Nachricht auf der Insel Jaguero am Schlingendornkap.", completion = "Seid Ihr gekommen, mich zu befreien?", sourceObjectiveStatus = "unverified-source-field" }
quests[26604] = { id = 26604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schutz ihrer königlichen Hoheit, Prinzessin Poobah", description = "Diese teuflischen Dschungelkatzen umkreisen mich bereits seit einiger Zeit. Ich beobachte sie so gut ich kann, aber sie scheinen... im Gras zu verschwinden.\n\nHört, wie sie knurren und zischen!\n\nVersteht mich nicht falsch... Ihr sollt mich immer noch retten, aber beseitigt zuerst diese Katzen. Ich muss nicht gerettet werden, wenn ich danach als Abendessen ende.", sourceObjective = "Tötet 5 Jagueropirscher.", completion = "Da seid Ihr ja endlich. Ich hatte schon befürchtet, ich würde gefressen werden, bevor Ihr von der Jagd zurückkehrt.\n\nEine Prinzessin im Magen einer Katze... wäre das nicht eine vornehme Beute?", sourceObjectiveStatus = "unverified-source-field" }
quests[26605] = { id = 26605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bahaarte Diebe", description = "Ich verstehe ja, dass Ihr mich retten wollt, aber der richtige Zeitpunkt ist noch nicht gekommen.. Zuerst benötige ich etwas von meinem Besitz.\n\nDie Gorillas und Affen auf der anderen Seite der Insel haben das meiste davon gestohlen. Ich brauche meine Tiara, mein Szepter, meine Pantoffeln und mein Tagebuch, dann bin ich bereit zur Abreise.\n\nWas? Seht mich nicht an, als wäre ich irgendeine Verrückte. Ihr versteht nicht, was es bedeutet, Prinzessin zu sein.", sourceObjective = "Sucht nach Poobahs Tiara, Poobahs Szepter, Poobahs Pantoffeln und Poobahs Tagebuch bei den Affen auf der Insel Jaguero.", progress = "Ich zittere bei dem Gedanken an das, was Mukla mit mir vorhat.", completion = "<Poobah betrachtet ihren Besitz.>\n\nEs scheint alles da zu sein. Also gut, dann bin ich bereit, gerettet zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26606] = { id = 26606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muklas Ende", description = "{name}, ich setze all mein Vertrauen in Euch. Befreit mich. Der große Himmelsmähnenkönig Mukla hält mich gefangen. Er herrscht über die wilden Tiere auf der Insel. Mit Hilfe dieser Fessel halten sie mich hier gegen meinen Willen fest. Wenn es Euch gelingen sollte, ihn zu töten und den Schlüssel zu dieser Kette zu finden, würde ich tief in Eurer Schuld stehen.\n\nIch höre ihn oft an der Südostseite der Insel, aber seid bitte vorsichtig. Nehmt ihn nicht auf die leichte Schulter.", sourceObjective = "Tötet König Mukla, findet den Fesselschlüssel.", progress = "Ich danke meinen Ahnen, dass jemand gekommen ist, um mir zu helfen. Habt Ihr den Schlüssel, mit dem ich befreit werden kann?", completion = "{name}, Ihr habt mich vor großer Ehrlosigkeit bewahrt. Wenn es in meiner Macht stünde, würde ich Euch einen Platz in meinem Stamm anbieten. Doch leider kann ich Euch erst einmal nur diese Kleinigkeit für Eure Tapferkeit und Euren Anstand anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26607] = { id = 26607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben zuerst Blut vergossen", description = "Nehmt dieses Bündel mit Keeshans Habseligkeiten und kehrt in den Keller des Gasthauses in Seenhain zurück. Die Kompanie Bravo ist bereits dort und redet mit Keeshan. Erinnert ihn daran, wer als erstes Blut vergossen hat, {name}. Seenhain braucht Keeshan. Die Allianz braucht Keeshan.\n\nWegtreten, Soldat!", sourceObjective = "Bringt Keeshans Habseligkeiten zu John J. Keeshan im Gasthaus von Seenhain im Rotkammgebirge.", progress = "Ihr schon wieder?", completion = "<Keeshan nimmt Euch das Bündel ab und öffnet es.>\n\nMein Bogen... und mein Messer! Wo habt Ihr...\n\nJades Amulett... Meine geliebte Jade.\n\n<Keeshan nimmt sein rotes Stirnband.>\n\nLasst uns Orcs töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26608] = { id = 26608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgebrochene Verhandlungen", description = "Geht nun, geht zurück zu Eurer Flotte. Sagt ihnen, was für ein Ungeheuer die Herrschaft über das Drachenmal für sich beansprucht.\n\nUnser \"Kriegshäuptling\" ist ein Verräter an seinem Blut. Seit seiner Rückkehr von der Scherbenwelt stinkt er nach Dämon und führt die Überreste unseres Klans ins Verderben.\n\nHelft dem Drachenmal, sich von Mor'ghor zu befreien, dann werden die unter uns, die reinen Blutes sind, für immer Eure Verbündeten sein. Das kann ich versprechen.", sourceObjective = "Kehrt zu Admiral Steinfaust vor der Küste der Drachenmalfestung im Schattenhochland zurück.", completion = "Die Höllenorcs aus der Scherbenwelt erheben Anspruch auf das Drachenmal? Obszön!\n\nWenn Höllschrei wüsste, was hier vorgeht, würde er ihre Stadt dem Erdboden gleichmachen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26609] = { id = 26609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blutsegelbukaniere", description = "Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, {race}, und <ein/eine:c> {class} noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.\n\nWir haben Beutebucht zu unserem gemütlichen zweiten Zuhause auf dem Festland gemacht, aber Gerüchten zufolge, hecken die Blutsegelbukaniere wieder etwas aus. Meine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.\n\nBegebt Euch zur Bucht im Norden von Beutebucht an der Ungezähmten Küste und schaut, was Ihr so findet.", sourceObjective = "Erster Maat Krazz will, dass Ihr die Bucht nördlich von Beutebucht überprüft.", completion = "Oben auf dem Fass findet Ihr eine Karte mit einigen hastig geschriebenen Worten und einigen Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26610] = { id = 26610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsegelverrat", description = "Auf der Karte hat jemand ein rotes \"X\" in Beutebucht eingezeichnet, genau dort, wo Ihr gerade steht.\n\nDaneben hat jemand gekritzelt:\n\n\"Errichtet Euren Kommandoposten hier und wartet ab. Der Flottenmeister wird sich bei Euch melden, wenn die Zeit reif für Taten ist.\"\n\n\"Ich übertrage Leutnant Bruce hier das Kommando. Dieses Mal wird alles anders sein. Dieses Mal werden wir Beutebucht endgültig erobern.\"\n\nDie Karte wird von einem Dolch gehalten, der mitten in Beutebucht steckt.", sourceObjective = "Meldet Eure Entdeckung dem Ersten Maat Krazz in Beutebucht.", completion = "Sicher erinnere ich mich an Euch, {class}. Wie ich sehe, seid Ihr vom Spähen zurück...", sourceObjectiveStatus = "unverified-source-field" }
quests[26611] = { id = 26611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Baron muss davon erfahren", description = "Beim Klabautermann! Also planen die Blutsegelbukaniere irgendeinen Angriff auf Beutebucht? Diese Schurken haben vielleicht Nerven. Die Schwarzmeerräuber werden Beutebucht niemals preisgeben!\n\nDas ist größer, als ich vermutet hatte. Meldet Baron Revilgaz sofort Eure Entdeckung! Ihr findet ihn hier in Beutebucht.", sourceObjective = "Berichtet Baron Revilgaz von den geplanten Blutsegelangriffen.", completion = "Blutsegel Bukaniere greifen Beutebucht an? Das ist nicht das erste Mal, dass dieses Gesindel so etwas versucht. Beutebucht ist uneinnehmbar!\n\nHört sich so an, als ob sie eine Taktik versuchen wollen. Ich würde es Firallon zutrauen, etwas Verrücktes zu versuchen. Nun gut, lasst uns herausfinden, was sie jetzt wieder im Schilde führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26612] = { id = 26612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzelheiten des Angriffs", description = "Ich brauche Details, {name}. Wir sind den Blutsegeln hauptsächlich wegen unseres Bollwerks hier in Beutebucht überlegen, aber Informationen spielen ebenfalls eine wichtige Rolle.\n\nDie Blutsegelbukaniere haben nur ein paar kleine Lager im Süden errichtet, die sie als \"Südkommando\" bezeichnen. Nun, dieses so genannte Südkommando werdet Ihr überfallen. Findet ihre Pläne und tötet ihre Männer. Kehrt mit allen Informationen, die Ihr findet, zu mir zurück.", sourceObjective = "Tötet 8 Seebären der Blutsegelbukaniere und 8 Hochmagi der Blutsegelbukaniere und erbeutet die Blutsegelkarten und Blutsegelbefehle.", progress = "Ahoi, {name}. Was habt Ihr im Lager der Blutsegel im Süden herausgefunden?", completion = "Perfekt, {name}. Jetzt, da wir ihren Plan kennen, ist es nur noch eine Frage der Zeit.\n\nUnd wenn ich bedenke, dass diese Narren genau vorm Kap vor Anker gegangen sind ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26613] = { id = 26613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schnupftabak", description = "Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.\n\nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben, nich?\n\nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.\n\nIch wette, <ein furchtloser/eine furchtlose:c> {class} wie Ihr könnte sie überreden, die Ware zu teilen, nich?", sourceObjective = "Deeg in Beutebucht möchte, dass Ihr ihm 15 winzige Haufen Schnupftabak bringt.", progress = "Glück mit den Waren, Kumpel?", completion = "Klasse gemacht, {name}! Und gerade noch rechtzeitig, bevor ich wieder Anker lichten muss! Kann Euch gar nicht genug danken, alter Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[26614] = { id = 26614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge offen halten", description = "Haltet ein! Wer da?\n\nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezialglasauge verzaubert, mit dem ich wieder was sehen kann.\n\nGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Beutebucht gefunden.\n\nKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?", sourceObjective = "Besorgt Torkels Auge von den Blutsegelbukanieren.", progress = "Ahoi, Kumpel! Kann zwar nich' sehen, aber kann Euch schon über'n halben Hafen hinwech riechen.\n\nKönnte mein Auge wirklich gut gebrauchen. D'r Käpt'n wird mich wohl kielholen, wenn er rausfindet, dass mein Glubscher in die Hände der dreckigen Blutsegelbukaniere gefallen is'.\n\nWozu is'n Ausguck gut, wenn er nix sieht? Das Krähennest war mein Zuhause... ohne meine Augen kann ich von Glück sagen, wenn ich die Bilge schrubbn darf.", completion = "Da brat mir doch einer 'nen Storch! Ihr habt mein wunderbares Auge gefunden! Lass uns mal gucken, ob's noch passt.\n\n{name} ho! Kinners, ich kann sehen!!", sourceObjectiveStatus = "unverified-source-field" }
quests[26616] = { id = 26616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nie vorbei", description = "Diese Schwarzfelsorcs werden eine Armee brauchen, wenn sie gegen die Kompanie Bravo und Euch etwas ausrichten wollen, {name}. Trefft Euch mit uns an den Docks, die auf den Immerruhsee hinausgehen, wenn Ihr bereit seid. Wir segeln auf meinem Flussboot zum Immerruhlager auf der anderen Seite des Sees.\n\nBis später, {name}.", sourceObjective = "Fahrt auf Keeshans Flussboot zum Immerruhlager im Rotkammgebirge.", completion = "Zeit, ein paar Orcs zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26617] = { id = 26617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Seebär", description = "Diese alte, verwitterte Münze wurde bei der Leiche des Piraten \"Guter Junge\" Bruce gefunden. Auf der Vorderseite ist das Abbild eines großen, unbekannten Piratenschiffs eingestanzt; auf der Rückseite der Begriff \"Mannschaft der Trümmerflut\".\n\nJemand, der schon lange im Pirateriegeschäft ist, konnte wissen, um was es sich bei dieser Münze handelt und was sie bedeutet.", sourceObjective = "Bringt die verwitterte Münze zu Flottenmeister Seehorn in Beutebucht.", progress = "Was habt Ihr denn da, {race}? Lasst mal sehen.", completion = "Diese Münze! Wo habt Ihr die her?\n\nBruce... ja, verstehe. Er gehörte früher den Schwarzmeerräubern an. War einer von uns, bevor Graumähne die Häfen von Gilneas schließen ließ und seine Besatzung gefangen nahm.\n\nIch weiß, dass sich die Leute durch das, was in Gilneas geschah, veränderten, aber ich hätte nie gedacht, dass sie ihre Loyalitäten wechseln würden. Vor allem nicht Bruce.\n\nKönnte ich die Münze vielleicht behalten? Ich gebe Euch ihren Gegenwert in Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[26618] = { id = 26618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wölfe sind uns auf den Fersen", description = "Die Stadtbewohner werden in erster Linie von den Terrorwölfen bedroht. Sie lauern in den Wäldern um uns herum, die meisten findet man jedoch am Nordufer des Flusses.\n\nSie sind anders als die räudigen Hunde, die Ihr aus Elwynn, oder wo immer Ihr auch herkommt, gewöhnt seid. Sie sind mannsgroß und zweimal so teuflisch.\n\nWenn Ihr den Einwohnern von Dunkelhain wirklich helfen wollt, dann jagt die Wölfe, damit wir auf unseren Straßen endlich wieder sicher sind.", sourceObjective = "Tötet 12 Terrorwölfe.", progress = "Jagt Ihr immer noch Wölfe...?", completion = "Denkt nicht, dass sei zu leicht gewesen. Tiefer in den Wäldern lauern weit größere Gefahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26619] = { id = 26619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wollt also eine Revolution", description = "Wenn es stimmt, was Ihr sagt, {name}, dann haben wir Freunde innerhalb des Drachenmalklans. Wir könnten einen Aufstand in ihren eigenen Reihen unterstützen. Das würde viel Blutvergießen auf beiden Seiten verhindern.\n\nIch kann dabei helfen, aber den gefährlichsten Teil muss ich Euch überlassen.\n\nMeine Krieger der Axtbeißer werden mit ihrer Offensive an den Küstenstreifen beginnen. Nutzt diese Ablenkung und schleicht Euch hinter die feindlichen Linien. Sprecht dort mit Zaela, Eurem Kontakt zu den Rebellen.\n\nWir werden den Drachenmalklan bewaffnen und seine teuflischen Herrscher stürzen!", sourceObjective = "Schleicht Euch hinter die Frontlinie am Hafen des Drachenmals und sprecht mit Zaela.", completion = "{name}, was machen Eure Leute? Greift Ihr das Drachenmal an oder seid Ihr hier, um uns von Mor'ghors Verderbnis zu befreien?\n\n\n\nAh, jetzt verstehe ich. Mir gefällt, wie Ihr denkt. Kriegshäuptling Mor'ghor wird völlig überrascht werden.\n\nLasst uns beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26620] = { id = 26620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewürzte Wolfkebabs", description = "Gewürzter Wolfkebab ist eine Spezialität des Hauses! Natürlich kann ich Euch einige machen. Doch zuerst brauche ich die Zutaten.\n\nBringt mir fünf Wolfskronfleischsteaks. Die Terrorwölfe nahe dem Fluss nördlich der Stadt, lassen sich gut jagen, aber ich würde an Eurer Stelle nicht zu tief in die Wälder vordringen.", sourceObjective = "Sammelt 5 Wolfskronfleischsteaks von Terrorwölfen.", progress = "Habt Ihr schon fünf Wolfskronfleischsteaks gefunden?", completion = "Hmmm-hmmm! Das Kronfleisch ist der beste Teil. Allerdings ist es nicht sehr effizient, damit zu kochen.\n\nHier, nehmt dieses Rezept. Es unterscheidet sich ein wenig von dem anderen, aber Flankenfleisch ist viel leichter zu bekommen, wenn Ihr dringend eine Mahlzeit benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26621] = { id = 26621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstand", description = "Die Waffen, die wir von der Horde bekommen haben, sind mehr als ausreichend. Wir vier sollten uns aufteilen und so viele Arbeiter und Händler des Drachenmals bewaffnen wie möglich.\n\nUnterschätzt uns nicht, {name}. Selbst unsere Kaufleute sind im Kampf gnadenlos.\n\nLasst uns so viel Schaden wie möglich anrichten. Bewaffnet eine Truppe des Drachenmalklans und mäht die Teufelsvollstrecker und Hexenmeister nieder, die mein Volk schon so lange einschüchtern. Danach treffen wir uns hier, um unseren letzten Schlag einzuleiten!", sourceObjective = "Bewaffnet 3 Arbeiter oder Händler des Drachenmals und tötet 10 Vollstrecker des Drachenmals und 4 Hexenmeister des Drachenmals.", progress = "Die Revolution hat endlich begonnen!\n\nDas Drachenmal schüttelt endlich die Fesseln ab, mit denen die Unwürdigen uns gebunden hatten.", completion = "Wir haben viele gute Orcs verloren, doch den Kampf werden wir für uns entscheiden, {name}.\n\nMor'ghors Regime bricht zusammen. Nur die Bestie selbst steht noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26622] = { id = 26622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Mor'ghor", description = "Die Zeit ist gekommen. Heute stirbt Mor'ghor.\n\nEine Warnung, {class}. Dämonenblut fließt durch seine verfluchten Adern. Er bedient sich unnatürlicher Kräfte. Er wird sterben, das ist sicher. Doch es wird kein leichter Kampf. Ihr wisst ja noch, dass sich Mor'ghor an der Spitze des Lagers aufhält. Dort werde ich Euch treffen. Erledigt ihn!\n\nVergesst nicht, 3 Anhänger des Drachenmals zu rekrutieren, solltet Ihr zu wenig Kämpfer haben - Ihr werdet unsere Hilfe brauchen.", sourceObjective = "Tötet Kriegshäuptling Mor'ghor im Hafen des Drachenmals. Ihr könnt immer noch Händler und Arbeiter des Drachenmals rekrutieren. Sie werden Euch helfen.", completion = "Gut gemacht, {name}! Während meiner Abwesenheit habt Ihr die Horde mit Stolz erfüllt.\n\nDer Drachenmalklan ist zu uns gestoßen. Zaela führt ihn an. Es wurde Blut vergossen, doch nur wenige sind gefallen. Das Drachenmal steht nun loyal hinter uns.\n\nUnsere Horde wird stärker!", sourceObjectiveStatus = "unverified-source-field" }
quests[26623] = { id = 26623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwärzliche Krebsküchlein", description = "Ich verrate Euch ein kleines Geheimnis - Schwärzliche Krebsküchlein werden in Wirklichkeit aus Spinnenfleisch gemacht! Ist ein bisschen eklig, aber die Küchlein haben einen würzigen Beigeschmack und eignen sich gut als Zwischenmahlzeit!\n\nAber wenn Ihr immer noch welche probieren möchtet, muss ich leider gestehen, dass ich kein Fleisch mehr habe. Ich brauche ein paar Fleischklumpen, dann kann ich die Küchlein backen.\n\nJagt am besten Giftweberspinnen. Sie nisten im Norden zwischen dem Vorgebirge und dem Fluss.", sourceObjective = "Erbeutet 6 schwärzliche Klumpen von Giftweberspinnen.", progress = "Seid gegrüßt, {name}. Habt Ihr die Fleischklumpen für mich?", completion = "Ah ja, da habt Ihr ja ein paar nette Klumpen eingesammelt! So, jetzt muss ich die nur noch mit meiner hochgeheimen Gewürzmischung würzen - wehe, Ihr schaut! - und sie dann noch ein bisschen in der Pfanne braten...\n\nDie schwärzlichen Krebsküchlein sind meine Spezialität, deswegen verrate ich das Rezept nicht. Aber hier habt Ihr das Rezept für ein Gericht, das fast genauso gut schmeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26624] = { id = 26624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Tuchfühlung mit den Blutsegeln", description = "Diese Pläne sind... interessant. Firallon, so dumm kannst du doch nicht sein!\n\nSeht, alle seine Schiffe sollen sich auf das Feuern ihrer Kanonen konzentrieren. Nur ein paar Männer kommen durch die Tunnel rein. Mit drei Schiffen und einem Dutzend Kämpfer wird er Beutebucht nie einnehmen. Und das weiß er auch.\n\nNein, sie haben etwas anderes vor... und Ihr werdet herausfinden, was. Sprecht mit Yancey Grillsen, dem Rekrutierer der Blutsegel.\n\nRichtig, {name}. Hofft, dass sie Euch nicht wiedererkennen.", sourceObjective = "Meldet Euch bei Yancey Grillsen am Wasserfall nördlich von Beutebucht.", completion = "Jaaa, is' die richtige Entscheidung, Bursche.", sourceObjectiveStatus = "unverified-source-field" }
quests[26625] = { id = 26625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggzor der Erdinator", description = "Ihr müsst das sofort beenden!\n\nKehrt zur Front im Nordwesten zurück und tötet ihren Schlachtenführer, Troggzor den Erdinator. Bringt mir zum Beweis seinen Knüppel.", sourceObjective = "Erbeutet den Knüppel des Erdinators.", progress = "Ist er tot? Habt Ihr den Knüppel?", completion = "<Der General nickt ernst.>\n\nEndlich können wir vorrücken und den Steinvater befreien.", sourceObjectiveStatus = "unverified-source-field" }
quests[26627] = { id = 26627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler", description = "Ich habe gehört, dass etwas im Bettlerschlupfwinkel vor sich geht. Man sieht Lichter im Turm östlich der Stadt.\n\nNur wenige haben den Mut, sich so nahe am Gebirgspass der Totenwinde aufzuhalten. Ihr seid <der/die> erste, <der/die> sich hier meldet, seit ich davon erfahren habe. Seht es Euch an und stellt sicher, dass das, was dort haust, menschlich ist.", sourceObjective = "Findet den Bewohner des Turms im Bettlerschlupfwinkel.", completion = "Ah, willkommen, Fremder! Ich würde Euch gerne etwas anbieten, aber hier gibt es nicht viel...\n\nDürfte ich Euch bitten, ein paar Botengänge für einen alten Einsiedler zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26628] = { id = 26628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod von unten", description = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.\n\nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.\n\nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Beutebucht zurückzufinden.\n\nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.\n\nSeid Ihr bereit, {name}?", sourceObjective = "Beschützt Wank O'Breen während des Angriffs.", completion = "Wir haben den Angriff überlebt!\n\nOhne Euch hätten wir es nicht geschafft, {name}.\n\nSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.\n\nAuch wenn Ihr nur ein schwacher {race} seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[26629] = { id = 26629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feststellung Eurer Loyalität", description = "Da is' nur eine Sache...\n\nYancey hört einiges. Ein paar Kumpel von mir hatten schon ziemlich tief ins Glas geschaut, als sie mir erzählten, dass sich <ein/eine:c> {class} durch das Südkommando gekloppt un' nach Karten und Befehlen gesucht hat. <Er/Sie> hat sogar ein paar anständige Piraten über die Klinge springen lassen.\n\nWie ich schon sagte, denen kam der Grog aus den Augen raus, aber... ein Bukanier muss seinen Ohren trauen. Deshalb hat mich Firallon selbst gefragt, ob ich Euch nich' ne kleine Aufgabe stellen könnte...\n\nBringt mir den Kopf von Flottenmeister Seehorn.", sourceObjective = "Besorgt den Kopf von Flottenmeister Seehorn in Beutebucht.", progress = "Spezialbefehl von Firallon. Sagt, der Tauren sei zu gefährlich.", completion = "Na da haut's mich doch aus dem Krähennest! So was sieht man wirklich selten.\n\n<Yancey schüttelt Eure Hand.>\n\nWillkommen an Bord, {name}. Beutezüge und Plünderungen erwarten Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26630] = { id = 26630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieht doch wie ein Taurenpirat aus", description = "Firallon will MEINEN Kopf? Das ist wirklich interessant. Aber wir finden schon einen Ausweg.\n\nDieser Yancey weiß wahrscheinlich nicht so genau, wie ich aussehe. Den meisten Nicht-Tauren fällt es schwer, uns Tauren auseinanderzuhalten. Den meisten Nicht-Tauren fällt es sogar schwer, uns von einem gewissen... vierbeinigen Nutztier zu unterscheiden.\n\nRikqiz, der Lederverarbeiter, hält eine solche Kreatur hier in Beutebucht, und Narkk versorgt mich mit Piratenhüten. Besorgt Ersatz für meinen Kopf und meinen Hut und kehrt mit beidem hierher zurück.", sourceObjective = "Besorgt einen Kuhkopf und einen übergroßen Piratenhut. Bringt beides zu Flottenmeister Seehorn.", progress = "Ihr solltet wissen, dass das den meisten Tauren peinlich wäre. Ich finde es... amüsant.", completion = "Damit sollten wir den minderbemittelten Blutsegelbukanier täuschen.\n\nDas hat Spaß gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26631] = { id = 26631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer erster Tag als Pirat", description = "Ihr habt zwar den Flottenmeister erledigt, aber Regeln sind Regeln und Befehle Befehle. Und meine Befehle besagen, dass alle neuen Piraten als Deckhelfer anfangen. Das sind die Regeln.\n\nIhr werdet für Käpt'n Kielhol, den Kommandanten der Springflut, arbeiten. Es is' das westlichste Schiff der Flotte, die südlich der Kapspitze liegt.\n\nSucht ihn in seiner Kapitänskajüte auf un' bringt ihm Eure Papiere.", sourceObjective = "Bringt Käpt'n Kielhol Eure Papiere.", progress = "Habt Ihr Eure Papiere, Deckhelfer? Will Euch ja nich' den ganzen Weg zurück zu Yancey schicken.", completion = "Ja... ja... Verstehe... scheint alles in Ordnung zu sein.\n\nHabt den großen Seehorn weggeputzt, ja? Spielt auf MEINEM Schiff keine Rolle. Das einzige, was Ihr hier wegputzen werdet, sind die Flecken auf dem Deck. Nehmt Euch einen Mopp.", sourceObjectiveStatus = "unverified-source-field" }
quests[26632] = { id = 26632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geleitschutz", description = "Gut, ich glaube, das funktioniert wieder. Ihr müsst das Katapult nach Nadelfelsbruch, der Stadt der Steintroggs, nördlich der Front bringen.\n\nDer Fahrer wird Euch begleiten. Ich werde mich auf den Rückweg machen und Kies darüber informieren.\n\nDie Steintroggs werden zweifellos versuchen, Euch aufzuhalten. Haltet sie vom Katapult fern. Es hat eine ziemliche Durchschlagskraft.\n\nLasst mich wissen, wenn Ihr bereit seid, {name}.", sourceObjective = "Geleitet das Katapult der Irdenen sicher nach Nadelfelsbruch.", completion = "<Der Katapultkommandant wirft Euch einen anerkennenden Blick zu.>\n\nDie Erzählungen von Eurer Kampfkunst eilen Euch weit voraus, {race}. Wollen wir mal sehen, ob Ihr uns auch dabei helfen könnt, diese Fungusschrecken von der Front fernzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26633] = { id = 26633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putzdienst", description = "Die Decks der Springflut sollten leuchten wie ein Sternrubin, Deckhelfer {name}. Ich führe 'n ordentliches Schiff, dafür sorgen Deckhelfer wie Ihr!\n\nNa, worauf wartet ihr denn noch, Ihr miesmuscheldämliche Schiffsratte? Ans Deck mit Euch! Nehmt den Mopp in die Hand!", sourceObjective = "Nehmt Euch einen Deckhelfermopp vom Deck der Springflut und haltet das Deck 2 Minuten lang sauber.", completion = "Ich habe wilde Putzgeräusche von hier unten gehört, Bursche. Genau DAS will Euer Käpt'n hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[26634] = { id = 26634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fluch vieler Piraten", description = "Zahnfleischerkrankung. Das ist ein großes Problem, {race}.\n\nIch weiß, dass Ihr neu seid und Euch wahrscheinlich noch nie jemand das Zahnfleisch aufgeschnitten hat, aber wir anderen Piraten müssen uns mit etwas herumschlagen, dass sich SKORBUT nennt. Deshalb lagern wir hier so viele Limonen.\n\nNa ja... lagerten hier so viele Limonen. Jemand hat unsere letzte Lieferung geklaut, aber sie können nicht weit gekommen sein - vielleicht bis zu den nahegelegenen Inseln? Schafft sie wieder her, dann überlege ich mir vielleicht, was ich tun kann, um für Eure Beförderung vom Deckhelfer zu sorgen.", sourceObjective = "Besorgt 5 Scheffel Limonen.", progress = "Zu viele gute Männer habe ich an dieser leicht zu verhindernden Krankheit sterben sehen, {race}. Wir brauchen diese Limonen.", completion = "Ich werde sie direkt verteilen, {race}. Und ich werde ein gutes Wort für Euch einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26635] = { id = 26635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwimmen mit Kanonenkugeln", description = "Würdet Ihr 'nem Deckhelferkameraden helfen?\n\nKielhol hat mir befohlen, ein paar Kanonenkugeln vom Meeresboden aufzusammeln. Ich erklär' Euch, wieso ich das nicht kann.\n\nErstens: Ich habe winzige Arme. Seht sie Euch doch an! Glaubt Ihr wirklich, ich könnte damit eine Kanonenkugel aufheben, selbst, wenn sie Unterwasser liegt?\n\nZweitens: Ich habe sehr schwache Atmungsorgane. Mir wird schon schwindlig, wenn ich den Atem länger als zehn Sekunden anhalten muss.\n\nDrittens: Da sind Haie.\n\nIhr müsst mir helfen, {name}! Eine weitere Degradierung würde ich nicht aushalten... Will gar nicht wissen, was als Nächstes käme!", sourceObjective = "Bergt 6 Blutsegelkanonenkugeln aus dem Wasser unter der Springflut.", progress = "Wisst Ihr, ich war nicht immer ein Deckhelfer.", completion = "Danke, {name}. Ich hab' schon Leute 'was von wegen \"dem Schönling\" und irgendeiner \"Buhkiste\" reden hören. Ich glaube nicht, dass ich diese Buhkiste von innen sehen will.", sourceObjectiveStatus = "unverified-source-field" }
quests[26636] = { id = 26636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fernmeldeausrüstung der Bravo-Kompanie: Tarnung", description = "Wir werden einiges an Ausrüstung brauchen, bevor wir die Schwarzfelsarmee ausschalten und das Rotkammgebirge retten können. Dabei könnt Ihr Euch nützlich machen, Grünschnabel.\n\nKeeshan hat mir befohlen, dafür zu sorgen, dass die Fernmeldeausrüstung der Bravo-Kompanie getarnt wird. Ich möchte, dass Ihr nach Süden geht und Euch ein wenig \"gärtnerisch\" betätigt. Bei diesem kleinen Abenteuer gibt es zwei Zutaten, über die Ihr Bescheid wissen solltet: (1) Blätter und (2) Fuchskot. Wir brauchen beides.\n\nHabt Ihr Euch nie gefragt, woraus Tarnung besteht?\n\nGeht nach Süden und findet, worum ich Euch gebeten habe, <Freund/Lady>.", sourceObjective = "Sammelt 5 Blätterhaufen und 5 Portionen Fuchskot.", progress = "Blätter und Kot - das brauche ich.", completion = "Gut gemacht, Grünschnabel. Ich lege die Tarnung direkt in die Kiste. Wir sollten bald bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[26637] = { id = 26637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fernmeldeausrüstung der Bravo-Kompanie: Chloroform", description = "Der erste Teil unserer Mission findet verdeckt statt, {name}. Deshalb müssen wir in der Lage sein, unseren Feind lautlos auszuschalten. Um das zu erreichen, brauchen wir Chloroform.\n\nDie Drüsen der Matschwirbler am Grund des Immerruhsees enthalten Chloroform. Schwimmt hinunter und besorgt mir Matschwirblerdrüsen. Kriegt Ihr das hin?\n\nKehrt zu mir zurück, wenn Ihr genügend Drüsen gefunden habt.\n\nIhr wollt wissen, wo der See ist? Macht die Augen auf, Trottel. Unmittelbar westlich.", sourceObjective = "Sammelt 8 Matschwirblerdrüsen.", progress = "Habt Ihr die Drüsen gefunden?", completion = "Perfekt. Diese Orcs werden uns buchstäblich verschlafen. Ich brauche einige Minuten, um sie zu verarbeiten, dann lege ich sie in die Fernmeldeausrüstung der Bravo-Kompanie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26638] = { id = 26638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf die Jäger", description = "Südlich von hier, entlang des Uferpfads, lauern Schwarzfelsorcs in den Wäldern. Im Schutz der Dunkelheit überfallen sie die Ahnungslosen. Diese Orcs bilden die erste Verteidigungslinie der Schwarzfelsarmee. Es sind Kundschafter, die alles, was sie sehen, ihrem Oberkommando melden. Sie müssen AUSGESCHALTET werden, sonst könnten sie unsere Mission gefährden.\n\nGeht nach Süden und tötet alle Jäger des Schwarzfels, die Ihr seht.", sourceObjective = "Tötet 8 Jäger des Schwarzfels.", completion = "Hervorragende Arbeit, {name}. Wir müssen uns beeilen, bevor sie Verstärkung anfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[26639] = { id = 26639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktpunkt: Brubaker", description = "Wir müssen unser Marschgepäck zusammen bekommen, vorher sind wir verdammt unnütz. Dabei werdet Ihr helfen, {name}. Kundschafter benötigen wir ebenfalls. Zum Glück haben wir Unterstützung aus Sturmwind erhalten. Brubaker, ein alter Kriegskamerad von mir, ist von SI:7 geschickt worden, um uns als Kundschafter zu dienen. Trefft ihn im Kampfgebiet südlich von hier.\n\nTrefft Euch mit Brubaker und findet heraus, was er weiß.", sourceObjective = "Findet Brubaker.", completion = "Brubaker ist tot. Anscheinend versuchen die Orcs durch diesen grausigen Anblick eine Nachricht zu senden. Bei näherem Hinsehen entdeckt Ihr etwas in Brubakers Beutel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26640] = { id = 26640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unaussprechliche Gräuel", description = "<Ihr faltet die Notiz auseinander und beginnt zu lesen.>\n\nKeeshan, wenn Ihr diese Nachricht lest, werde ich tot sein. Wahrscheinlich wurde meine Position kompromittiert.\n\nDie Orcs begehen unaussprechliche Gräuel an ihren Gefangenen. Ja, Gefangene, Keeshan. Sie haben Käfige voll mit Kriegsgefangenen. Bevor Ihr dieses Tal in die Luft sprengt, müsst Ihr die Gefangenen befreien.\n\nSagt meiner Frau, dass ich sie liebe und dass sie den verdammten Müll rausbringen soll.\n\n-Brubaker\n\nPS - Sie haben schwarze Drachen.\n\nBringt Keeshan Brubakers Report.", sourceObjective = "Bringt Brubakers Report zu John J. Keeshan im Immerruhlager im Rotkammgebirge.", progress = "Sie haben Brubaker erwischt?", completion = "<Keeshan liest den Report.>\n\nVERDAMMT! Jetzt wird es kompliziert. Wir müssen die Kriegsgefangenen befreien, bevor wir das Tal sprengen können. Mal ganz abgesehen von den schwarzen Drachen, die den Orcs zur Seite stehen.\n\nSeid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26641] = { id = 26641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiertanz", description = "Die Brutwachen der Blutfratzen im Nordosten bewachen die Eier von Shadras Brut. Auch wenn wir die Blutfratzen töten, werden diese schrecklichen Kreaturen irgendwann aus ihren Eiern schlüpfen und in die Wildnis entkommen.\n\nDas müssen wir verhindern. Reißt alle Eier, die Ihr findet, aus ihren Eiersäcken und bringt sie mir. Versucht nicht, sie selbst zu zerstören; die Kleinen könnten herauskommen.\n\nWenn Ihr wieder hier seid, sorge ich dafür, dass sie vernünftig entsorgt werden!", sourceObjective = "Besorgt 5 Eier der Shadrabrut aus Agol'watha.", progress = "Habt Ihr die Eier?", completion = "Wir werden sie sofort verbrennen und die Asche zur Sicherheit verstreuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26642] = { id = 26642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhaltung des Brachlands", description = "Seit Jahren bildet das Brachland das Herz des Hordengebiets in Kalimdor. Es ist eine wichtige Verbindung zwischen den Orcs von Durotar und den Taurensiedlungen in Mulgore.\n\nIm Chaos des Kataklysmus drohen wir durch Überflutungen, Erdbeben und sogar einer Invasion der Stacheleber von diesem wichtigen Grasland abgeschnitten zu werden.\n\nIhr wirkt, als wärt Ihr bereit für eine Herausforderung. Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht und stellt sicher, dass der Weg ins Brachland frei bleibt! Reist ins nahe gelegene Klingenhügel und von dort aus gen Westen. Überquert den Südstrom, dann werdet Ihr ihn finden.", sourceObjective = "Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland.", completion = "Ein neuer Rekrut aus Orgrimmar, richtig?\n\n<Kargal mustert Euch.>\n\nIch nehme, was ich kriegen kann. Es ist ein Alptraum, die Straßen frei zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26643] = { id = 26643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungerdiät", description = "In den Gruselruinen östlich von hier wimmelt es von ausgewachsenen Spinnen der Shadrabrut. Sie sind so groß, dass sie einen ganzen Zwerg nachts davonschleppen können. Die Beweise dafür werdet Ihr sehen, wenn Ihr dort ankommt... eingesponnene Körper überall in den Ruinen.\n\nSie halten sie nicht lange am Leben, {name}, aber von den Leichen ernähren sie sich tagelang. Den Opfern kann niemand mehr helfen, aber diese Spinnen dürfen nicht noch fetter und kräftiger werden. Sorgt dafür, dass diese Kokons verschwinden.", sourceObjective = "Zerstört 6 eingesponnene Opfer in den Gruselruinen.", completion = "Eine makabere Aufgabe, {name}, doch nun werden sich die überlebenden Spinnen nicht mehr erholen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26644] = { id = 26644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufmerksamkeit erregen", description = "Deckhelfer {name}! Das ist ein trauriger Tag für den alten Käpt'n Kielhol. Heute verliere ich meinen besten Deckhelfer.\n\nIch habe einen Brief von Flottenmeister Firallon erhalten. Anscheinend hat er von Eurer guten Putzleistung gehört. Ihr sollt an Bord der Purpurschleier kommen und als sein Bootsmann und Dritter Maat dienen. Sie liegt direkt neben der Springflut.\n\nDas ist 'n großer Schritt in Eurer Piratenkarriere, Deckhelfer {name}. Ich würde vorschlagen, sein Angebot anzunehmen.\n\nWegtreten!", sourceObjective = "Meldet Euch bei Flottenmeister Firallon im Inneren der Purpurschleier am Schlingendornkap.", completion = "Also Ihr habt den alten Seehorn abgemurkst? Yancey hat so was gesagt, aber ich wollte sicherstellen, dass er nicht wieder Seemannsgarn gesponnen hat.\n\nIch werde es kurz machen. Das mit Kielhols Mannschaft habt Ihr gut gemacht, aber ich erwarte, dass Ihr bei meiner noch besser seid. Ich muss mich um eine ganze Flotte kümmern, also werdet Ihr mir bei der täglichen Routine auf meinem Schiff helfen.\n\nWillkommen an Bord der Purpurschleier, Seemann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26645] = { id = 26645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtwache", description = "Ihr seid leider <der Einzige, der/die Einzige> die; mir hier helfen kann, {name}. Die Streitkräfte Sturmwinds werden von weit größeren Gefahren bedroht. Sie können keinen einzigen Soldaten zum Schutz von Dunkelhain abstellen. Ich und die anderen aus der Nachtwache müssen uns um die Sicherheit unserer Heimat kümmern.\n\nLeider bedrohen uns nicht nur Wölfe. Verrottende Schrecken treiben nahe dem Spukhaus der blinden Mary am südöstlichen Stadtrand ihr Unwesen. Wenn wir sie nicht in Schach halten, werden sie in der Nacht unsere Häuser besuchen.\n\nKümmert Euch um die Untoten und meldet Euch bei mir, um belohnt zu werden.", sourceObjective = "Tötet 8 verrottende Schrecken nahe dem Spukhaus der blinden Mary, südöstlich von Dunkelhain.", completion = "Wunderbar, {name}. Für Euren Dienst an den Einwohnern von Dunkelhain sollt Ihr entlohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26646] = { id = 26646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsgefangene", description = "Die Fernmeldeausrüstung der Bravo-Kompanie ist fertig, {name}. Ich werde Euch damit ausrüsten. Ihr werdet Renders Tal, südöstlich von hier, betreten und unsere Kriegsgefangenen befreien. Ich gebe Euch Jorgensen mit. Er wird Euch den Rücken freihalten.\n\nDie Gefangenen sitzen im Nordosten des Tals in einem großen Käfig, aber der Schlüssel zu diesem Käfig befindet sich in einer Höhle im Süden des Tals. Ihr müsst den Schlüssel stehlen, für Ablenkung sorgen und die Bürger befreien.\n\nViel Glück, {name}! Wir bleiben über den Fernmeldeapparat in Verbindung.", sourceObjective = "Befreit die Kriegsgefangenen, die im Gefängnis von Renders Tal sitzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26647] = { id = 26647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicke Emma", description = "Wir haben viel Arbeit vor uns. Wie viel Erfahrung habt Ihr mit Kanonen? Hmm... wirklich? Und wie sieht es mit uralten, zusammenbrechenden Piratenkanonen aus?\n\nAuf den Decks gibt es noch ein paar Kanonen, die auf die altmodische Weise funktionieren: Man lädt immer nur eine Kanonenkugel, zielt, arretiert und feuert. Funktioniert gut, wenn man die Seite eines Dreimasters treffen will... nicht so gut bei Ruderbooten und ähnlichem.\n\nGeht doch mal nach oben und feuert ein paar Schuss auf Timmy Grinsezweig ab.", sourceObjective = "Übt die Benutzung der Kanone, indem Ihr Timmy Grinsezweig mit 5 Kanonenkugeln von der Dicken Emma trefft.", completion = "Mir gefällt Euer Stil, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26648] = { id = 26648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Todfeinde", description = "Hey, Neuling, seht Euch das mal an.\n\n<Der Zwerg hebt seine Augenklappe und enthüllt einen echten, funktionierenden Augapfel.>\n\nIch trage die Klappe nicht wegen eines verlorenen Auges. Ich trage sie, weil das ANDERE Auge so stark ist, dass es von dem normalen ausgebremst wurde.\n\nMit diesem Auge kann man alles Mögliche sehen, zum Beispiel die maskierten Schlägertypen, die uns folgen. Der Flottenmeister sagt, dass sie auf der Insel Jaguero aufgetaucht sind. Feuert diese Leuchtpistole ab, wenn Ihr dort eintrefft, und ich werde Euch helfen, sie auch zu sehen.", sourceObjective = "Tötet 15 Ninjas auf der Insel Jaguero.", sourceObjectiveStatus = "unverified-source-field" }
quests[26649] = { id = 26649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schießbudenpiraterie", description = "Ihr wisst ja jetzt, wie man mit unseren Kanonen umgeht, also wird es Zeit, dass Ihr echte Ziele trefft!\n\nDie Venture Company hat nördlich von hier Gold gefunden... eine seltene Art, die sie \"schwarzes Gold\" nennen. Sieht für mich eher wie ein schwarzer Fleck aus.\n\nWir werden uns dieses Gold holen, aber zuerst müssen wir die Trottel der Venture Company los werden. Ein Ruderer wird Euch dort hinaus bringen. Verlasst das Schiff über die Laufplanke und sprecht mit ihm am Nordstrand der kleinen Insel.", sourceObjective = "Sprecht mit dem Ruderer der Blutsegelbukaniere außerhalb der Purpurschleier und tötet dann 75 Ölarbeiter der Venture Co. mit der Kanone.", completion = "Ahahaha! Ihr habt sie glatt aus ihrer Takelage gesprengt! Darauf trinke ich!\n\nVor Euch liegt eine große Zukunft, Grünschnabel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26650] = { id = 26650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Maid im Glück\"", description = "Ich weiß ja, dass Ihr erst vor kurzem auf der Purpurschleier angekommen seid, aber ich könnte Euch für 'ne andere Aufgabe gebrauchen. Die Maid im Glück ist das dritte Schiff in meiner Flotte. Sie liegt östlich von hier. Ihr Skipper, Kapitän Stillwasser, weilt nicht mehr unter uns.\n\nVerdammt seien diese maskierten Strolche!\n\nIn jedem Fall hat mir Stahlauge von Euren Heldentaten auf See erzählt, und mir gehen langsam die qualifizierten Briganten aus. Ich denke, dass Ihr mehr als nur in der Lage sein werdet, Eure neuen Pflichten zu erfüllen.\n\nHerzlichen Glückwunsch, <Kumpel/Mädchen>. Ihr seid der neue Kapitän der Maid im Glück.", sourceObjective = "Meldet Euch in Eurer Kapitänskajüte im Inneren der Maid im Glück am Schlingendornkap.", completion = "Ihr seht Pläne ausgerollt auf dem Tisch liegen. Sie erklären alles!\n\nDas sind Einzelheiten des bevorstehenden Angriffs auf Beutebucht. Kampfformationen, Angriffspläne und etwas über eine Gruppe, die \"Mannschaft der Trümmerflut\" heißt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26651] = { id = 26651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um einen Krieg zu gewinnen, müsst Ihr zum Krieg werden", description = "<Das Funkgerät der Kompanie Bravo piept.>\n\nVersteht Ihr es schon, {name}? Wisst Ihr jetzt, was wir tun müssen, um einen Krieg gegen diese Ungeheuer zu gewinnen? IHR MÜSST ZUM KRIEG WERDEN! KEINE GNADE!\n\nDie Kriegsgefangenen sind befreit. Ihr könnt das Zephyrium anbringen. Betretet vorsichtig die Gebäude dort draußen und bringt je einen Sprengsatz an.\n\nBringt je eine Zephyriumladung an der Munitionshütte des Schwarzfels und am Turm des Schwarzfels an. Trefft Euch mit mir und dem Rest der Kompanie Bravo in der Schieferwindschlucht östlich von Renders Tal.", sourceObjective = "Bringt mit der Fernmeldeausrüstung der Bravo-Kompanie je eine Zephyriumladung am Turm des Schwarzfels und an der Munitionshütte des Schwarzfels an.", completion = "Und jetzt jagen wir das ganze verdammte Ding in die Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26652] = { id = 26652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterhaarfaden", description = "Es gibt einen armen, traurigen Geist namens die blinde Mary, die in einem alten Farmhaus in den Hügeln südlich von Dunkelhain herumspukt.\n\nNehmt diesen spektralen Kamm und bittet die blinde Mary, ihr Haar damit zu kämmen. Bringt mir den Kamm. Ich werde das Geisterhaar darin auflesen, das ich für den Faden brauche.\n\nUnd seid vorsichtig, denn dunkle Wesen treiben sich nahe des Hauses herum...", sourceObjective = "Bringt den spektralen Kamm zur blinden Mary.", progress = "<Schluchz> Oh bitte seht mich nicht an! Ich habe diese Augen mit meinen eigenen Händen herausgerissen, aber ich spüre immer noch Euren Blick!\n\nIch sehe entsetzlich aus! Entsetzlich! Bitte seht weg!!", completion = "Was ist das? Ein Kamm? Er ist wunderschön! Und er gleitet durch mein Haar, als wäre es gar nicht so furchtbar verfilzt und widerspenstig wie es ist.\n\nOh, hätte ich doch nur einen Spiegel...", sourceObjectiveStatus = "unverified-source-field" }
quests[26653] = { id = 26653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung aus Dunkelhain", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", sourceObjective = "Sprecht mit Madame Eva in Dunkelhain.", completion = "So, Ihr braucht also Geisterhaarfaden, hm? Ich habe leider keinen mehr auf Lager, aber ich kann Euch welchen herstellen - wenn Ihr mir das Geisterhaar besorgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26654] = { id = 26654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr mit dem Kamm", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", sourceObjective = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", progress = "Ich kann spüren, dass Ihr die blinde Mary getroffen habt. Habt Ihr auch meinen Kamm?", completion = "Damit kann ich eine Rolle Geisterhaarfaden herstellen und es bleiben sogar noch einige Haare übrig. Hier habt Ihr einige Münzen für diese zusätzlichen Haare.", sourceObjectiveStatus = "unverified-source-field" }
quests[26655] = { id = 26655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abliefern des Fadens", description = "Hier ist Euer Faden, {name}. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder leblose Dinge mit Leben erfüllen.", sourceObjective = "Bringt den Geisterhaarfaden zu Calvinius in seinem Turm im Bettlerschlupfwinkel.", progress = "Ich brauche den Geisterhaarfaden, um ihn quer über meine Tür und meine Fenster zu spannen. Das hält unliebsame Geister fern. Habt Ihr ihn für mich besorgt?", completion = "Wunderbar! Das ist gerade richtig...\n\nHier, bitte, mein guter {name}, nehmt dies als Bezahlung für Eure ehrenhafte Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26656] = { id = 26656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer. In. Bewegung. Bleiben.", description = "Als Todesschwinge kam, sind die Steindrachen zu ihm geschwärmt. In seiner Abwesenheit fehlt ihnen jegliche Bestimmung. Sie streifen durch die Gegend und fressen unseresgleichen.\n\nIch habe Dutzende von opalschimmernden Wächtern gebunden, aber ich kann sie nicht aus der sicheren Deckung führen. Ich brauche jemanden, der schneller ist, und ich glaube, Ihr seid genau richtig für diese Aufgabe.\n\nFührt sie am Boden Richtung Therazanes Thron im Osten. Einige werden es sicher nicht schaffen, aber solange Ihr nicht stehenbleibt, solltet Ihr einige von ihnen zu unseren Truppen führen können.", sourceObjective = "Hetzt mindestens 5 opalschimmernde Wächter nach Osten aus dem Bleichen Hort hinaus, zum Steinkreis in der Nähe von Therazanes Thron.", completion = "Gut gemacht. Ich habe viele Stärken, aber Schnelligkeit gehört nicht dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[26657] = { id = 26657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein harter Fall", description = "Steindrachen lassen sich nur von Stärke beeindrucken. Wenn wir sie ausreichend bestraft haben, werden sie sich unserem Willen unterwerfen.\n\nIch habe eine Vielzahl meiner stärksten Riesen auf die Felder im Westen geschickt. Sie werden die Drachen zu Boden befördern. Ihr kümmert Euch dann darum, dass sie sich nach ihrem Fall nicht wieder in die Lüfte schwingen.", sourceObjective = "Tötet 6 Steindrachen.", completion = "Offensichtlich nicht nur schnell. In Euch scheint Einiges zu stecken.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26658] = { id = 26658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrechliche Werte", description = "Jetzt ist es an der Zeit, die Aufmerksamkeit der Brutmutter zu erregen. Dazu benötigen wir einen Hammer, den die Troggs während der Opferzeremonie für sie benutzen.\n\nSucht die Bestienzähmer der Steintroggs, die im südlichen Teil des Bleichen Horts versuchen, Basilisken zu zähmen. Einer von ihnen trägt einen Hammer bei sich.", sourceObjective = "Beschafft einen Mauerhammer.", progress = "Konntet Ihr einen Hammer finden?", completion = "Wunderbar.\n\nJetzt werden wir den Steindrachen einen Schlag verpassen, den sie in den nächsten hundert Jahren nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26659] = { id = 26659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachhallender Schlag", description = "Ihr werdet einen Resonanzkristall am westlichen Rand des Bleichen Horts finden. Schlagt mit dem Hammer darauf, dann wird die Brutmutter kommen.\n\nMacht Euch für einen Kampf bereit. Ich werde dort sein, um Euch zu helfen, aber sie wird sich nicht leicht geschlagen geben.", sourceObjective = "Besiegt Aeosera.", progress = "Diese Brutmutter nimmt die Steindrachen seit fast 300 Jahren unter ihre Fittiche. Sie ist recht stark, sogar für einen Steindrachen.", completion = "Beeindruckend, Fleischling. Ihr seid fähiger, als ich ursprünglich angenommen hatte.\n\nIch werde diese Einschätzung auch der Steinmutter übermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[26660] = { id = 26660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zombiesaft", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne \"Zum Roten Raben\" in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, {name}. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", sourceObjective = "Sprecht mit Schankwart Smitts.", completion = "Ihr braucht etwas Zombiesaft, wie? Hmm, das Zeug ist ziemlich stark - ich werde nicht oft danach gefragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26661] = { id = 26661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sammeln von Faulblüten", description = "Wenn Ihr mir einige Fäulnisblüten bringt, kann ich Zombiesaft für Euch brauen.\n\nFäulnisblüten wachsen an seltsamen Orten. Sie wachsen besonders gut auf Dingen, die tot sind. Im Dämmerwald gibt es jede Menge davon!\n\nIch habe einige im Friedhof \"Stille Gärten\" gesehen. Sucht in der Nähe der Gräber... aber achtet auf die Toten, die dort umherwandern.", sourceObjective = "Sammelt 5 Fäulnisblüten auf dem Friedhof \"Stille Gärten\".", progress = "Hallo, {name}. Habt Ihr mir Fäulnisblüten gebracht?", completion = "Gut, Ihr habt die Fäulnisblüten gefunden.\n\nIch werde etwas Zombiesaft zubereiten... aber Vorsicht, das ist starkes Zeug.", sourceObjectiveStatus = "unverified-source-field" }
quests[26662] = { id = 26662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mannschaft der Trümmerflut", description = "Auf den Karten wird eine Gruppe namens Mannschaft der Trümmerflut erwähnt. Der Name ist Euch nicht bekannt, obwohl Ihr schon von einigen anderen neuen Bukanieren gehört habt.\n\nBesucht sie doch mal und findet heraus, was sie wissen.", sourceObjective = "Sprecht mit Long John Copper auf der Maid im Glück, Shawn Stooker dem Koloss auf der Purpurschleier und der klagenden Mary Smitts auf der Springflut.", progress = "Die Details sind eher spärlich. Wenn Ihr Informationen wollt, müsst Ihr andere Mitglieder der Mannschaft der Trümmerflut finden.", completion = "Die Mannschaft der Trümmerflut besteht nicht nur aus Piraten... sondern aus Piraten der Worgen! Und sie werden sich an dem Angriff beteiligen!\n\nRevilgaz wird das definitiv wissen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26663] = { id = 26663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versenkung aus dem Inneren", description = "Der Angriff auf Beutebucht steht kurz bevor. Kehrt rasch nach Beutebucht zurück und informiert den Baron.\n\nSo lange Ihr bei den Piraten noch angesehen seid, wäre es aber gut, wenn Ihr deren Vorräte sabotieren würdet. Die Piraten bewahren die meisten ihrer Vorräte unter Deck auf. Sie sind auf die ganze Flotte verteilt.", sourceObjective = "Sabotiert das Fass mit Grog, das Fass mit Schießpulver und die Kiste mit Kanonenkugeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[26664] = { id = 26664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meutereimacher", description = "Bevor Ihr nach Beutebucht zurückkehrt, solltet Ihr alles tun, um die Blutsegelbukaniere zu schwächen. Leider ist es Euch selbst als Kapitän verboten, andere Bukaniere kaltblütig zu töten. Das darf nur ein Flottenmeister.\n\nAllerdings dürft Ihr Meuterer zu Tode bringen... und Meuterei lässt sich nur schwer widerlegen.\n\nApropos, diese Blutsegelkorsaren, die auf den untersten Decks der Schiffe herumhängen, benehmen sich in letzter Zeit wirklich sehr verdächtig...", sourceObjective = "Beschuldigt 9 Korsaren der Blutsegel der Meuterei und tötet sie dann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26665] = { id = 26665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Beute", description = "Ihr habt den Eindruck, dass Ihr genug Schaden angerichtet habt. Ihr kennt außerdem die Schlachtpläne der Blutsegelbukaniere. Ihr habt alles getan, um das Euch Baron Revilgaz gebeten hat.\n\nEs ist Zeit, den Piratenhut an den Nagel zu hängen und nach Beutebucht zurückzukehren. Der Moment der Schlacht naht.", sourceObjective = "Meldet Euch bei Baron Revilgaz in Beutebucht am Schlingendornkap.", completion = "Die Trümmerflutler!? Ich dachte, die wären seit JAHREN tot und vergessen!\n\n<Revilgaz hört angestrengt zu, während Ihr ihm die zusammengetragenen Informationen weitergebt.>\n\nDas ergibt einen Sinn. Und es sind keine guten Neuigkeiten. Die Mannschaft der Trümmerflut sind ernstzunehmende Gegner und wenn sie wieder so viele sind, wie damals, als sie verschwanden, steht uns ein schwerer Kampf bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26666] = { id = 26666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Stalvan", description = "Ich bin hier, weil mein Bruder Stalvan, den ich seit Jahren nicht gesehen habe, mir einen Brief geschickt hat. Als ich hier eintraf, sagte man mir, er sei tot...\n\nDie ganze Stadt weigert sich, mir mehr zu erklären. Sie reagieren misstrauisch und ängstlich, wenn ich seinen Namen erwähne. Als ob ich mich nicht selbst schon so fühlen würde!\n\nIch habe Angst vor dem, was passieren könnte, wenn mein Ärger und mein Frust zunehmen. Bitte helft mir, der Sache auf den Grund zu gehen. Fragt Amtmann Daltry nach allen Informationen, die er über meinen Bruder besitzt.", sourceObjective = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", completion = "Kann ich Euch helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26667] = { id = 26667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestohlenen Briefe", description = "Ihr wollt etwas über Stalvan wissen...\n\nIhr seid nicht <der/die> erste, wisst Ihr das? Fremde kommen ab und zu hier durch und fragen nach ihm. Immer nur Fremde. Alle, die hier leben, wissen es besser.\n\nWie dem auch sei, Ihr habt Pech. Die Hälfte meiner Archive ist weg. Wilde Worgen sind vor ein paar Nächten ins Rathaus eingebrochen und haben alles in Stücke gerissen. Die Dokumente, nach denen Ihr sucht, sind mittlerweile wahrscheinlich in ganz Schattenhain verstreut, tief in den Wäldern im Westen. Sind die Suche nicht wert, wenn Ihr mich fragt.", sourceObjective = "Findet das Bündel zerrissener Briefe in Schattenhain.", progress = "Ernsthaft, mein Herr, ich will keinen Ärger...", completion = "Beim Licht... Ihr habt sie tatsächlich geholt?\n\nIch bin schockiert. Ich sollte mich wohl bei Euch dafür bedanken, dass Ihr sie in die Archive zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26668] = { id = 26668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Detonation", description = "Der Sprengstoff, den Ihr angebracht habt, ist hochexplosiv, {name}. Wenn ich diesen Knopf an der Fernmeldeausrüstung der Bravo-Kompanie drücke, wird das ganze Tal in einem gigantischen Feuerball des Todes vergehen.\n\nWisst Ihr was? Ich glaube, die Ehre gebührt Euch. Die ganze harte Arbeit ist schließlich an Euch hängen geblieben.\n\nBereit?", sourceObjective = "Sprengt Renders Tal in die Luft.", completion = "Habt Ihr gesehen, wie die Orcs explodiert sind? SO MACHEN WIR DAS IN DER KOMPANIE BRAVO! Lasst uns mit dem Rest dieser Clowns aufräumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26669] = { id = 26669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In einer dunklen Ecke", description = "Wenn es Euch wirklich ernst ist, helfe ich Euch, {name}. Ich weiß, wo die anderen Dokumente sein müssen. Ich habe zu viel Angst, um etwas zu unternehmen.\n\nEs gibt nur wenige Orte, an denen sich diese furchtbaren Schrecken der Nacht versammeln, wenn sie nicht gerade den Wald durchstreifen. Einer davon ist der Verrottende Obstgarten im Süden. Sie benutzen die Gebäude als Schlupfwinkel. Wenn sie die Dokumente nicht einfach gefressen haben, werdet Ihr sie wahrscheinlich dort finden... aber ich wette, dass Ihr ihre Verstecke gründlich durchsuchen müsst.", sourceObjective = "Durchsucht den Verrottenden Obstgarten nach der zerrissenen Tagebuchseite.", progress = "Ihr seid in einem Stück zurückgekommen, wie ich sehe.", completion = "Mehr habt Ihr nicht gefunden?\n\nDas sind schlechte Nachrichten...", sourceObjectiveStatus = "unverified-source-field" }
quests[26670] = { id = 26670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rolands Verdammnis", description = "Das ist nicht alles...\n\nLasst es sein, {name}. Eure Suche kann Euch nur noch nach Rolands Verdammnis führen. Das ist eine Mine südlich der Stadt und der größte Worgenbau in ganz Dämmerwald. Niemand in Dunkelhain hat diesen Ort je lebend verlassen. Einige der Berichte, die ich hier habe, weisen daraufhin, dass diese Ungeheuer dort ihren Ursprung haben... wer weiß, welches Böse sich darin verbirgt?\n\nBitte gebt auf, {name}. Lasst uns die ganze Sache vergessen und nie wieder davon sprechen.", sourceObjective = "Sucht in Rolands Verdammnis nach den restlichen Seiten von Stalvans Tagebuch.", progress = "Ich sagte Euch doch, {name}, dass sich die Suche nicht lohnt...", completion = "Was, Ihr habt sie geholt?!\n\nIch weiß nicht, ob ihr mutig oder verrückt seid. Im Namen meiner Archive danke ich Euch jedoch erneut.", sourceObjectiveStatus = "unverified-source-field" }
quests[26671] = { id = 26671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Stalvan Dunstmantel", description = "Ihr habt alles gefunden. Alles, bis auf die letzte Seite...\n\n...die ich hier habe. Seht mich nicht so an. Ihr werdet alles verstehen, wenn Ihr sie gelesen habt. Einige behaupten sogar, sie sei verflucht. Um ehrlich zu sein, war ich erleichtert, als die Worgen eingebrochen sind und die Seiten gestohlen haben!\n\nNehmt sie. Ach nein, nehmt alle. Ich danke Euch dafür, dass Ihr meine Archive wiederbeschafft habt, aber ich will nichts mehr mit der Sache zu tun haben. Lasst mich bitte in Ruhe.", sourceObjective = "Bringt die Legende von Stalvan zurück zu Tobias Dunstmantel.", progress = "Ihr seid wieder da! Habt Ihr etwas über meinen Bruder herausgefunden?", completion = "Ich kann Euch gar nicht genug danken... Ich hatte auf ein freudiges Wiedersehen gehofft, aber je mehr ich erfahre, desto sehnlicher wünsche ich mir, ich hätte nie gefragt.\n\nAber ich muss es wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26672] = { id = 26672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wahrheit auf den Grund gehen", description = "Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...\n\n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.>\n\nIch brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.\n\nIch muss wissen, warum...\n\nNehmt meinen Ring, {name}. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.", sourceObjective = "Bringt Madame Eva den Familienring der Dunstmantels.", progress = "Welche dunklen Stimmen haben Euch an meine Tür gebracht, {class}?", completion = "Wie interessant. Es ist lange her, dass ich einen solchen Ring gesehen habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[26673] = { id = 26673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE - BREADCRUMB#", description = "Das kann nicht sein. Mein Bruder hatte einen starken Willen, aber eine solche Boshaftigkeit... so etwas brutales, blutiges, krankes...\n\n<Tobias hebt eine Hand vor sein Gesicht und wendet den Blick ab.> Ich brauche Antworten. Ich muss wissen, wie mich dieser Brief erreicht hat. Ich muss wissen, ob Stalvan das wirklich getan hat.\n\nIch muss wissen, warum...\n\nNehmt meinen Ring, {name}. Bringt ihn zu Madame Eva. Diese Frau ist eine Anhängerin der alten Künste und verbirgt das auch nicht... es ist vielleicht verrückt, aber ich bin soweit, alles zu versuchen.", sourceObjective = "Bringt Madama Eva den Familienring der Dunstmantels.", sourceObjectiveStatus = "unverified-source-field" }
quests[26674] = { id = 26674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunstmantels Rache", description = "Leider kann ich Tobias nicht die Antworten geben, nach denen er sucht. Aber ich kann Euch bei der Suche nach der einzigen Person helfen, die das vermag...\n\nStalvan Dunstmantel.\n\nBringt den Ring zum Anwesen der Dunstmantels in den Wäldern im Osten, wo Stalvans Leiche begraben wurde. Tretet ein und haltet den Ring hoch. Wenn das Licht des abnehmenden Mondes durch den Ring scheint, werden die Geister Euren Ruf erhören.\n\nVergesst eines nicht, {name}. Die Fragen der Lebenden spenden oft mehr Trost als die Antworten der Toten.", sourceObjective = "Benutzt den Familienring der Dunstmantels im Anwesen der Dunstmantels östlich der Stadt.", completion = "Meister Harris hatte vielleicht sogar recht. Es wäre besser gewesen, wenn ich die Vergangenheit hinter mir gelassen hätte.\n\nIch habe jetzt ein neues Leben. Ob es das eines Ungeheuers oder das eines Mannes ist, hängt von mir ab.\n\nEuch kann ich nicht genug für Eure Unterstützung danken, egal, zu welchem Ergebnis sie geführt hat. Bitte nehmt dies zusammen mit meinem Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[26675] = { id = 26675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wert des Vertrauens", description = "Die Probleme dieser Welt scheinen nie zu vergehen. Sie verschieben und verändern sich, bilden sich neu, aber sind doch stets vorhanden.\n\nDer Wind hat uns Gerüchte über einen Verräter in unserer Mitte zugeflüstert. Wir haben eine unserer besten Schildwachen mit den Nachforschungen betraut, doch sie wurde tot aufgefunden. Ich habe das zu verantworten, da ich annahm, der Verräter wisse nichts von unserem Vorgehen... Ich handelte unüberlegt, und sie musste den Preis für meine Dummheit bezahlen.\n\nIch brauche ein fremdes Gesicht, um die Spur wieder aufzunehmen. Jemanden, den die Leute in der Stadt nicht kennen. Das ist eine gefährliche Bitte. Werdet Ihr mir helfen?" }
quests[26676] = { id = 26676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saftlieferung", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", sourceObjective = "Bringt Calvinius den Zombiesaft im Bettlerschlupfwinkel.", progress = "Ich brauche den Zombiesaft, um mich in diesen dunklen, kalten Nächten warm zu halten. Habt Ihr ihn für mich besorgt?", completion = "Seid tausendmal bedankt, {name}! Ihr erwärmt das Herz eines alten Mannes mit Eurer Naiv... ääh... mit Eurer Freundlichkeit!\n\nHier, bitte schön, mein Freund, nehmt dies als ein Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26677] = { id = 26677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ghulbildnis", description = "Es ist ein Wunder, dass die lebenden Toten mich hier draußen am Stadtrand noch nicht gefressen haben! Erst gestern hat eine Horde Ghule beinahe die Wände meines Turms eingeschlagen!\n\nIch möchte ein Abbild herstellen - eine Art \"Vogelscheuche\" für Ghule. Dafür benötige ich einige Ghulrippen. Rund um das Anwesen der Dunstmantels, nördlich von Dunkelhain, wandern stinkende Leichname umher, bei denen ihr jede Menge finden solltet...\n\nBesorgt mir die Rippen, dann werde ich Euch mit einigen Münzen belohnen.", sourceObjective = "Sammelt 7 Ghulrippen von Stinkenden Leichnamen auf dem Anwesen der Dunstmantels.", progress = "Wahrscheinlich würdet Ihr auch zahlreiche Rippen in Rabenflucht finden, aber wer will schon spät nachts so weit laufen...", completion = "Ah, danke! Die sind genau richtig für mein Vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26678] = { id = 26678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelrum", description = "<Baron Revilgaz seufzt.> Ich habe zwar Teile von Firallons Plan erahnt, aber trotzdem sind wir nicht auf die beiden Frontalangriffe der Blutsegel und der Trümmerflut vorbereitet. Wir werden ein kleines Wunder brauchen, um Beutebucht an diesem Tag zu halten.\n\nIch habe ein Fass Doppelrum in meinem Quartier. Steigt die Treppe drei Stockwerke hinunter und nehmt die erste Tür zu Eurer Rechten. Ihr könnt die Warnungen auf dem Fass ignorieren... sie sollten Eure geringste Sorge sein.", sourceObjective = "Findet Baron Revilgaz' Fass mit Doppelrum in Beutebucht.", completion = "Das muss der Doppelrum sein. Ihr schenkt Revilgaz ein Glas ein und überlegt, ob Ihr Euch auch eins gönnen sollt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26679] = { id = 26679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Revilgaz zurück", description = "Draußen geschieht etwas. Sind die Blutsegelbukaniere etwa schon hier?\n\nBringt Revilgaz seinen Doppelrum. Schnell.", sourceObjective = "Bringt Baron Revilgaz in Beutebucht den Doppelrum.", progress = "Ratet mal, wer aufgetaucht ist, während Ihr weg wart?", completion = "<Der Baron leert rasch seinen Kelch.>\n\nAH! Das tut gut, {name}. Aber zurück zum Geschäft. Ich glaube, dass Ihr und ich eine Stadt zu retten haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26680] = { id = 26680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerdiebe", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, {name}, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", sourceObjective = "Bringt Calvinius' Kiste zu Calvinius.", progress = "Habt Ihr meine Kiste? Wenn ja, dann gebt sie mir schnell, ich bitte Euch!", completion = "Dank dem Toten- ähm, ich danke EUCH, {name}! Ihr habt Euch Eure Belohnung mehr als verdient.\n\nAha! Oh Glück! Glückliche Nächte können kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26681] = { id = 26681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief für den Bürgermeister", description = "Bringt diese Nachricht zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", sourceObjective = "Bringt Calvinius' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain.", progress = "Ein Brief? Worum geht es bei dieser Geschichte?", completion = "<Ello sieht sich den Brief an und sein Gesicht verliert augenblicklich alle Farbe.>\n\nIhr Narr! Ihr habt uns alle verdammt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26682] = { id = 26682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine torkelnde Bedrohung", description = "Düstermarschen ist das Gebiet der Horde, {name}. Die Menschen haben ihre kleine Insel und ihre heißgeliebte Sandbank, aber die Sümpfe gehören uns.\n\nIrgendwann werden wir diese Pattsituation mit den Menschen auch noch klären. Doch erst einmal müssen wir unser eigenes Gebiet beherrschen. Die Moderrankenmorastbestien im Norden tauchen aus dem Sumpf auf und greifen jedes Lebewesen an, das sich ihnen nähert. Wenn wir diese Marschen beherrschen wollen, dann darf sich unser Land nicht gegen uns wenden!\n\nTötet die Morastbestien, wenn Ihr der Horde dienen wollt. Man wird Euch belohnen.", sourceObjective = "Tötet 7 Moderrankenkrabbler oder Moderrankenwüteriche im Sumpf nördlich von Brackenwall.", completion = "Gut gemacht, {name}. Nun können wir uns hier auf die größeren Bedrohungen konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26683] = { id = 26683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht zu den Sternen", description = "Mein Gnomenfreund Zinken hat versprochen, mir beim Bau eines Geräts zu helfen, mit dem man zu den Sternen blicken kann. Laut Zinkens Blaupause muss ich zuerst eine Möglichkeit finden, das Licht zu reflektieren.\n\nIch erinnere mich an eine Frau namens Mary, die in dieser Gegend rasch bekannt wurde, weil sie stets einen Handspiegel bei sich trug. Könntet Ihr vielleicht Mary suchen und sie fragen, ob sie uns eine reflektierende Oberfläche für dieses Projekt leihen würde? Ich glaube, sie lebte früher im südlichen Dämmerwald...", sourceObjective = "Findet Mary und überredet sie, eine reflektierende Oberfläche für Viktoris Projekt abzugeben.", completion = "Ja, das stimmt. Ich besaß einmal einen Spiegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[26684] = { id = 26684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der irrsinnige Ghul", description = "Der Handspiegel war einer meiner wertvollsten Schätze, bis... zu dem Zwischenfall. Danach warf ich ihn hinter die Scheune. Dort hinten trieb ein irrsinniger Ghul sein Unwesen. Vielleicht hat er ihn aufgehoben. Angeblich halten sich diese teuflischen Bestien im Friedhof \"Stille Gärten\" auf.", sourceObjective = "Erbeutet Marys Handspiegel von dem irrsinnigen Ghul.", progress = "Ich habe Zinken die Anfänge unserer Sternenguckermaschine gezeigt. Er war beeindruckt. Habt Ihr ein reflektierendes Gerät gefunden?", completion = "Wie wunderbar! Das wird sehr gut funktionieren. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[26685] = { id = 26685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feines Glas", description = "Jetzt brauche ich nur noch einen Gegenstand, dann ist das Gerät komplett. Laut Zinkens Blaupause fehlt eine Art Linse. Die einzige Linse, die ich kenne und die groß genug wäre, wird nur schwer zu beschaffen sein.\n\nEs gibt einen Oger namens Zzarc'Vul, der auf dem Hügel im südlichen Dämmerwald lebt. Wenn es Euch gelingen würde, mir sein Monokel zu bringen, könnte ich das als Linse verwenden!", sourceObjective = "Tötet Zzarc'Vul auf dem südlichen Ogerhügel in Dämmerwald und erbeutet sein Ogermonokel.", progress = "Konntet Ihr Zzarc'Vul davon überzeugen, uns sein Monokel für unser Experiment zu leihen?", completion = "Endlich! Die Sternenguckermaschine ist komplett! Danke, {name}. Jetzt kann ich meine Forschungen fortsetzen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26686] = { id = 26686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnde Knochen", description = "Ihr werdet Euch mit noch fauligeren Untoten herumschlagen müssen, {name}.\n\nDer Friedhof \"Stille Gärten\" etwas weiter südlich der Stadt ist ein Ort, an dem man sich nachts nicht blicken lassen sollte. Die Knochen, die sich dort aus dem Boden erheben, sind klug genug, um sich daran zu erinnern, wie man eine Axt schwingt oder einen Zauber wirkt.\n\nIch muss wohl nicht erklären, wie gefährlich sie das macht. Seid vorsichtig, aber denkt daran, dass das Volk von Dunkelhain leiden wird, wenn Ihr scheitert.", sourceObjective = "Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass ihr 5 Skelettkrieger und 5 Skelettmagier vernichtet.", completion = "Das Volk von Dunkelhain dankt Euch, {name}. Ihr habt Euch als starker Verbündeter der Nachtwache erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26687] = { id = 26687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung aus Theramore", description = "Hawthorne tot... mein eigener Sohn ermordet... die Lage im Brachland ist außer Kontrolle, {name}.\n\nIch werde das Kommando über die Triumphfeste übernehmen und versuchen, für Ruhe zu sorgen. Doch dazu benötige ich Verstärkung. Verstärkung, die man mir in Theramore schon vor Wochen versprochen hat!\n\nReist nach Theramore in den Düstermarschen und blast Hauptmann Garran Mumm den Marsch. Welchen Zweck erfüllt diese verdammte Straße durch den Sumpf, wenn Soldaten und Material trotzdem nicht kommen?", sourceObjective = "Reist zur Insel Theramore in den Düstermarschen und sprecht mit Hauptmann Garran Mumm in der Hauptkaserne.", completion = "Was jetzt, Soldat?\n\nVerstärkung? Für das Brachland? Seit Monaten stecken wir Soldaten und Vorräte dort hinein!\n\nMuss jemand Doppelzopf an den Angriff auf Nordwache erinnern? Unsere Verluste an der Ehrenwacht? Was ist mit den Soldaten geschehen, die ich zur Triumphfeste geschickt habe? Wir können niemanden mehr entbehren!\n\n{name}, wenn Ihr uns wirklich helfen wollt, dann konzentriert Euch auf die Lage hier in den Düstermarschen. Wir schlagen uns mit Deserteuren und den Übergriffen der Horde herum... wir können Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26688] = { id = 26688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Treuwein hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Treuwein an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Worgen der Nachtheuler im Schattenhain. Wir werden sehen, ob Ihr in der Lage seid, es mit diesen Monstern aufzunehmen.", sourceObjective = "Tötet 7 Worgen der Nachtheuler im Schattenhain.", completion = "Ich bin beeindruckt, {name}. Es scheint, als wäret Ihr durchaus fähig, Euch im Kampf zu behaupten. Vielleicht können wir ja eine Aufgabe für Euch finden, die jemanden mit Euren Fähigkeiten etwas mehr herausfordert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26689] = { id = 26689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verrottende Obstgarten", description = "Die Worgenplage erstreckt sich über Schattenhain hinaus. Im Süden, ganz am Rand von Dunkelhain, liegt der Verrottende Obstgarten. Dort findet man noch wildere Bestien.\n\nDie Worgen dort sind listiger, {name}, aber ebenso grausam und böse. Sie beschwören verdorbene Schatten, die ihre Feinde aus der Entfernung in Stücke reißen. Geht zum Verrottenden Obstgarten und tötet die Schattenwirker, um die Stadt zu beschützen!", sourceObjective = "Tötet 10 Schattenwirker der Nachtheuler im Verrottenden Obstgarten.", completion = "Ihr habt Euch gut gegen die Schattenwirker geschlagen, {name}. Doch selbst heutzutage, Jahre nach ihrem ersten Auftauchen, scheint es mehr als genug zu geben, um die von uns Getöteten zu ersetzen.\n\nIch setze all meine Hoffnung auf Meister Carevin. Er wird dem Problem sicherlich auf den Grund gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26690] = { id = 26690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faulig und besudelt", description = "Eure früheren Leistungen haben mich davon überzeugt, dass Ihr Euch den härtesten Worgen stellen solltet, die diese Wälder heimsuchen.\n\nDie Faulreißer und die Besudelten haben sich als die gefährlichsten der Worgen, die hier eine neue Heimat gefunden haben, erwiesen. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nSchon aus der Ferne kann man das Licht ihrer Lagerfeuer sehen...", sourceObjective = "Tötet 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler in Rolands Verdammnis.", completion = "{name}, um ehrlich zu sein, hatte ich nicht damit gerechnet, dass Ihr so weit kommen würdet, aber Ihr seid offensichtlich ein {class}, den man im Auge behalten sollte. Solltet Ihr Euch also auch offiziell Meister Treuweins Kampf anschließen wollen, werde ich Euch gern ein Empfehlungsschreiben aufsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26691] = { id = 26691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in den Wäldern", description = "Bitte sehr, {name}. Bringt diese Nachricht zu Meister Treuwein.\n\n<Er zieht rasch ein Stück verblichenes Pergament hervor und reicht es Euch.>\n\nWenn es nur noch mehr wie Euch gäbe, dann wären wir bald zahlreicher als die Nachtwache! Vielleicht könnten wir dann das Werk vollenden, das wir wenigen begonnen haben.", sourceObjective = "Bringt Calors Notiz zu Jonathan Treuwein.", progress = "Ja, was ist? Beeilt Euch, ich habe dringende Aufgaben.", completion = "Entschuldigt den frostigen Empfang, {name}, aber Euch ist sicher klar, dass ich ein äußerst vielbeschäftigter Mann bin. Wie ich sehe, habt Ihr Calor so sehr beeindruckt - und ich kann Euch versichern, dass das nicht oft vorkommt - dass er Euch empfohlen hat.\n\nEs sind einige abstoßende Gestalten unterwegs, {name}, und ich kann die Hilfe von allen gebrauchen, die sich bewiesen haben. Wir kämpfen gegen Dämonen, die Untoten und alle, die ihnen helfen. Seid wachsam, seid vorsichtig und vertraut niemandem, der unseren Kampf nicht unterstützt.\n\nRuhm unter dem Licht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26692] = { id = 26692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung der Schattenfelle", description = "Da von den Schwarzfelsorcs südlich vom Immerruhsee nichts außer Asche und Kohle übrig geblieben ist, können wir unsere Aufmerksamkeit auf die Armee der Schattenfellgnolle im Galardelltal unmittelbar nördlich von hier richten.\n\nGeht hinaus und bringt sie alle um, {name}! Beginnt mit der Operation: Ausrottung, Soldat. Für die Kompanie Bravo und für die Allianz!", sourceObjective = "Tötet 20 beliebige Gnolle der Schattenfelle.", completion = "<Danforths Stimme erklingt aus dem Marschgepäck der Kompanie Bravo.>\n\nHallo? Ist das Ding an?\n\n<Im Hintergrund könnt Ihr Keeshans Stimme hören und einige gedämpfte Kratzgeräusche, während sie das Signal justieren.>\n\nJetzt haben wir's. Gute Arbeit, {name}. Wir rücken auf das Oberkommando des Schwarzfels vor. Für diese Hunde gibt es keinen Ausweg mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[26693] = { id = 26693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der dunkle Turm", description = "Wir hatten Glück. Die Bewohner dieses Tals haben uns wichtige Informationen gegeben. Die beiden hinter uns, die Ranthals, haben mir berichtet, dass die Gnolle im Galardelltal von einem mächtigen Magus im Turm von Ilgalar kontrolliert werden. Das Problem ist, dass dieser Turm durch ein magisches Kraftfeld versiegelt wird.\n\nAls erstes brauchen wir den Schlüssel, damit Ihr ins Innere vorstoßen könnt. Fangor, der Gnollgeneral, besitzt Eure Fahrkarte ins Innere. Tötet General Fangor und holt Euch den Schlüssel.\n\nIch melde mich.", sourceObjective = "Erbeutet den Schlüssel von Ilgalar.", sourceObjectiveStatus = "unverified-source-field" }
quests[26694] = { id = 26694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Großmagus Doane", description = "<Die Fernmeldeausrüstung der Bravo-Kompanie vibriert.>\n\nGute Arbeit, Grünschnabel. Ich habe wichtige Informationen für Euch. Der Magus in dem Turm ist ein Mensch namens Doane. Der verdammte Verräter arbeitet für die Schwarzfelsorcs. Ich will seinen Tod.\n\nVerschafft Euch mit dem Schlüssel von Ilgalar einen Weg ins Innere des Turms. Arbeitet Euch bis zur Spitze vor und zeigt Doane, was die Kompanie Bravo mit Verrätern macht.\n\nKehrt zum Treffpunkt Schieferwindschlucht zurück, wenn die Tat vollbracht ist.\n\nKeeshan Ende und aus.", sourceObjective = "Tötet Großmagus Doane.", completion = "Er hat sich wegteleportiert? Und Dunkelflamme erwähnt? Was zur Hölle geht hier vor?\n\nLasst uns aufsitzen und diesen Unfug zu Ende bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26695] = { id = 26695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Startvorbereitungen", description = "Ich habe eine Idee, die etwas Laufarbeit von Euch erfordert. Die Schwarzmeerräuber sind ein Kartell der Goblins. Deshalb haben sie Zugang zu jeder Menge Sprengstoff. Ich weiß sogar, dass unser alter Freund Narkk eine ganze Kiste hinten in seinem Laden in der Alten Hafenbehörde aufbewahrt.\n\nHolt sie Euch und bringt sie her, wenn sie noch nicht hochgegangen ist.", sourceObjective = "Besorgt Narkks Handbomben aus der Alten Hafenbehörde in Beutebucht.", progress = "Ihr lebt noch?", completion = "Ihr habt sie dabei! Ich glaube, so langsam dreht sich der Wind zu unserem Vorteil, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26696] = { id = 26696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf von Kalimdor", description = "Sagt mal, Ihr habt nicht zufällig einen etwa so großen Fisch gesehen? Kurze Flossen? Hört auf den Namen Steve?\n\nEgal, ich such' einfach weiter.\n\nAber... es gibt einen anderen Grund, aus dem ich nach Beutebucht gekommen bin. Boss Krog, drüben in den Düstermarschen, sucht neue Arbeiter.\n\nWartet am Ende des Piers auf das nächste Schiff, dann fahrt nach Ratschet. Gazlowe sollte Euch von da aus weiterhelfen können.\n\nSteve? Steve!", sourceObjective = "Nehmt das Schiff von Beutebucht nach Ratschet und sprecht dort mit Gazlowe.", completion = "Ja, Was kann ich für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[26697] = { id = 26697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Reise der Trümmerflutpiraten", description = "Wir werden diesen Angriff nicht überstehen, wenn all diese Worgenpiraten von Norden in den Hafen einfallen. Zum Glück sieht es so aus, als wären sie nicht mit Kanonen bewaffnet. Wenn es uns gelingt, Euch aus dem Hafen zu bringen, könnt Ihr sie aus der Luft angreifen.\n\nIhr findet Kebok, den Assistenten des Windreitermeisters der Horde, gleich um die Ecke. Erklärt ihm, dass Ihr seinen mutigsten Windreiter benötigt.\n\nNehmt all die Handbomben mit, die Ihr tragen könnt. Ihr werdet sie brauchen, um die Landungsboote aufzuhalten!", sourceObjective = "Sprecht mit Kebok in Beutebucht und schwingt Euch auf einen tapferen Windreiter. Tötet dann mit den Handbomben 85 Crewmitglieder der Trümmerflutpiraten und zerstört 6 Landungsboote der Trümmerflutpiraten.", completion = "Ich hoffe, diese räudigen Hunde können schwimmen!\n\nMoment, das nehme ich zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[26698] = { id = 26698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Seehorn", description = "Als die Trümmerflutpiraten ankamen, griff Seehorn nach der ersten Waffe, die er in die Hände bekam und sprang von diesem Vorsprung. Ihr werdet ihn da unten finden. Wahrscheinlich schlägt er ein paar neue Löcher in diese Worgenschädel.\n\nHelft ihm. Um die Motivation kümmere ich mich von hier oben.", sourceObjective = "Meldet Euch bei Flottenmeister Seehorn in Beutebucht.", completion = "Ich hätte wissen sollen, dass die Trümmerflutpiraten noch leben und nichts Gutes im Schilde führen. Ich hatte sie schon vor Jahren abgeschrieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26699] = { id = 26699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abwehr der Trümmerflutpiraten", description = "Die Trümmerflutpiraten sind überall! Die Haudraufs von Beutebucht, die der Baron angeworben hat, haben einer solchen Überzahl nichts entgegen zu setzen.\n\nWährend Ihr dort unten seid, könntet ihr mir helfen, ein paar von ihnen los zu werden?\n\nWenn Ihr fertig seid, macht Euch nicht die Mühe wieder heraufzukommen. Ich werde wahrscheinlich ziemlich beschäftigt sein.", sourceObjective = "Tötet 10 Räuber der Trümmerflutpiraten in Beutebucht.", completion = "Wir dürfen nicht nachlassen, {name}. Wir können Beutebucht nicht viel länger halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26700] = { id = 26700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maid im (Un)Glück", description = "Ich habe gehört, dass dieses Schiff hier Die Maid im Glück heißt. Wart Ihr nicht mal der Kapitän von diesem Kahn? Dann kennt Ihr Euch dort ja aus.\n\nDie Trümmerflutpiraten sind unsere Hauptsorge, aber wir können auch nicht einfach zusehen, während wir mit diesen Kanonen beschossen werden. Ergreift das Seil hinter mir und erledigt ein paar dieser wütend aussehenden Korsaren. Meldet Euch beim Baron, wenn Ihr fertig seid.", sourceObjective = "Tötet 8 Korsaren der Blutsegelbukaniere in Beutebucht.", completion = "Ein Angriff auf Eure ehemalige Besatzung...\n\nIhr seid wirklich ein echter Pirat geworden, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26701] = { id = 26701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Brackenwall", description = "Hört mal, die Horde liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.\n\nEuer Gold ist so gut wie das jedes Anderen.\n\nDieser zweiköpfige Oger und sein Fisch haben etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Krog. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.", sourceObjective = "Sprecht mit Bragok in Ratschet, um nach Brackenwall zu fliegen. Meldet Euch dann bei Krog.", completion = "Lok'tar, {race}. Willkommen in Brackenwall.", sourceObjectiveStatus = "unverified-source-field" }
quests[26702] = { id = 26702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Theramore", description = "Hört mal, die Allianz liegt mir nicht gerade am Herzen... aber andererseits hasse ich Euch auch nicht unbedingt.\n\nEuer Gold ist so gut wie das jedes Anderen. Manchmal besser.\n\nJeyne hat etwas Gold für Eure Reisespesen dagelassen. Ich glaube, die Person, die Ihr dort sucht, heißt Calia Hastings. Und die beste Art, dort hinzugelangen, ist unser Flugmeister Bragok. Er lässt Euch hinfliegen, wenn Ihr wollt. Dank Eures Freundes ist der Flug kostenlos.", sourceObjective = "Sprecht mit Bragok in Ratchet, um nach Theramore zu fliegen. Meldet Euch dann bei Calia Hastings.", completion = "Willkommen in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[26703] = { id = 26703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streicht die Blutsegel", description = "Dass der Sieg zum Greifen nah ist, haben wir fast allein Euch zu verdanken. Es bleibt jedoch noch eine letzte Aufgabe... tötet Flottenmeister Firallon.\n\nEin Großteil von Firallons Mannschaft scheint bereits tot zu sein, aber ich kenne den alten Seebären nur zu gut. Er ist noch nicht erledigt. Nein, er hat sich bestimmt in seiner Kajüte verbarrikadiert, um mit seinem Schiff unterzugehen.\n\nSprecht noch einmal mit Kebok. Er wird Euch einen Windreiter geben. Ich versuche den Kanonenbeschuss zu unterbrechen, während Ihr an Bord seid.", sourceObjective = "Sprecht mit Kebok in Beutebucht, lasst Euch einen Windreiter geben und tötet Flottenmeister Firallon.", completion = "{name}! Ihr seid wach! Wir haben Euch, kurz nachdem die letzten Angreifer den Schwanz eingezogen haben, im Hafen treiben sehen. Ihr habt uns eine Weile lang Sorgen gemacht...\n\nIch wollte mich noch bei Euch bedanken, {name}. Ihr habt uns die Informationen verschafft, die wir brauchten, um uns auf diesen Angriff vorzubereiten und uns geholfen, nicht nur die Blutsegelbukaniere, sondern AUCH die Trümmerflutpiraten abzuwehren. Wir in Beutebucht werden uns stets an Euren Namen erinnern.\n\nWir sind sehr stolz auf unsere Beute. Wollt Ihr die erste Wahl haben?", sourceObjectiveStatus = "unverified-source-field" }
quests[26704] = { id = 26704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26706] = { id = 26706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endspiel", description = "Wir müssen dieses fliegende Kanonenboot loswerden, wenn unser Volk eine Chance auf Flucht haben möchte.\n\nSo lautet der Plan. In Kielwasser trieben sich früher einige sympathisierende Rebellen herum. Ich konnte eine beträchtliche Menge Sprengstoff aus einem unserer Lager besorgen.\n\nWir werden den Feind mit einer Kraft überrumpeln, die so klein ist, dass sie sich unentdeckt durch die Luft bewegen kann. Die Hippogryphen der Nachtelfen eignen sich perfekt dafür.\n\nTobias gibt Euch das Signal, wenn wir bereit sind.", sourceObjective = "Springt auf einen Hippogryphen, wenn Tobias Euch das Zeichen dazu gibt, und zerstört das Kanonenboot der Horde.", progress = "Es lohnt sich nur Risiken einzugehen, die Siege bringen, die es sich zu erringen lohnt.", completion = "Wir haben es geschafft, {name}. Wir haben die Evakuierung in die Wege geleitet. Wenn wir uns bald auf den Weg machen, sieht die Flotte der Verlassenen bald nur noch eine Staubwolke von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[26707] = { id = 26707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tödliche Rebe", description = "Ich brauche jede Menge Leichengras für Meister Harris' Gebräu. Es ist schwer zu kriegen, aber unsere Vorräte dürfen nicht abnehmen. Leichengras ist ziemlich hartes Zeug...\n\nDie Pflanze macht Euch fertig, wenn Ihr nicht aufpasst! Aber wenn Ihr trotzdem helfen wollt, dann werde ich Euch gern für alles bezahlen, das Ihr selbst gesammelt habt.\n\nIhr werdet jede Menge auf Yorgens Bauernhof im Südosten finden.", sourceObjective = "Sammelt 5 Stück Leichengras.", progress = "Habt Ihr das Leichengras?", completion = "Ich danke Euch, {class}... und ich bin sicher, dass die {race}, die durch den Trank, der daraus gebraut wird, vielleicht ihren Verstand zurückbekommen, Euch ebenfalls danken würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26708] = { id = 26708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", description = "Ich bin hier, um Euch und der Kompanie Bravo bei der Beseitigung dieses Schlamassels zu helfen. Steigt in den Belagerungspanzer der Kompanie Bravo und räumt den Weg zu Keeshans Posten auf der anderen Seite des Tals, nördlich von hier, frei.\n\nDie Situation ist hochgradig gefährlich, Soldat. Den Schwarzfelsorcs ist Eure Position mittlerweile bekannt. Sie sind mit einer großen Streitmacht auf dem Weg zu Euch.\n\nEliminiert sie alle ohne Gnade. Wir sehen auf der anderen Seite. Möge das Licht Eurer Seele gnädig sein.", sourceObjective = "Tötet 200 Schwarzfelsorcs mit dem Belagerungspanzer der Kompanie Bravo.", completion = "Wir müssen uns nur noch um die Orcs kümmern, die die Burg Steinwacht besetzt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26709] = { id = 26709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinthron", description = "Ich kehre auf meinen Thron zurück. Ich habe kein Verlangen danach, noch mehr vom Irdenen Ring zu sehen, aber Ihr seid hier stets willkommen, {race}. Wenn Ihr uns beim Wiederaufbau unseres Reichs helfen wollt, dann können wir Euch vielleicht ebenfalls helfen.\n\nAlles zu seiner Zeit.", sourceObjective = "Sucht nach Therazane bei Therazanes Thron.", completion = "Ihr seid zurückgekehrt. Das ist gut. Die Steinlords haben nach Euch gefragt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26710] = { id = 26710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Tiefen verloren", description = "Kieselchen hat es schon wieder geschafft, sich zu verlaufen, irgendwo in den Bruchtiefen.\n\nEr hat Glück, dass er so klein und dadurch für die Schleifwürmer uninteressant ist. Es ist aber nur eine Frage der Zeit, bevor er zu nah an einem von ihnen vorbeikommt und doch aufgefressen wird. Warum auch immer er da unten ist, es kann einfach nicht so wichtig sein.\n\nEr scheint Euch zu mögen. Zieht bitte los, um ihn zu finden, und bringt ihn aus diesen Tunneln zu einem sichereren Spielplatz.", sourceObjective = "Findet Kieselchen in den Bruchtiefen und geleitet ihn sicher aus den Tunneln.", completion = "Das habt Ihr gut gemacht. Nun können diese Felslinge unsere Traditionen erlernen und groß und stark werden.\n\nEines Tages werden wir diese Tunnelgräberplage in unserem Reich auslöschen, damit die Felslinge nicht mehr während ihrer Jugend leiden müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26711] = { id = 26711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab zur Bank", description = "Jo, Schätzchen. Was geht? Schon bereit für die Party?\n\nNein?! Du weißt doch, dass ich dich heiß und innig liebe, also weiß ich nicht ganz, wie ich es sagen soll, aber… Ich glaube, du solltest mal in der Stadt nach einem neuen Outfit für die Party suchen.\n\nGuck mich nicht so an... Du willst doch klasse für mich aussehen, ooooder? Willst du für mich nicht superschick sein?\n\nSchau erst bei der Bank vorbei und hol dir ausreichend Moneten. Du willst ja schließlich keinen Billigkram kaufen!", sourceObjective = "Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.", completion = "Oh, Ihr seid es, Madame! Tut mir leid, bei dem ganzen Pöbel, der hier herumschwirrt, habe ich Euch nicht gleich erkannt.\n\nIhr rumlaufenden Leute! Macht mal langsam hier! {name} ist da!\n\nHier sind Eure Moneten, meine Dame. Kommt jederzeit wieder, wenn Ihr mehr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26712] = { id = 26712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ab zur Bank", description = "Hey, mein Süßer. Schon bereit für die Party?\n\nNein?! Du weißt doch, dass ich dich heiß und innig liebe, hm? Ich finde, du solltest mal in die Stadt gehen und ein neues Outfit für die Party kaufen.\n\nGuck mich nicht so an... Du willst doch sicher gut aussehen? Willst du nicht gut für mich aussehen? Ich bin schließlich deine Freundin!\n\nSchau unbedingt erst bei der Bank vorbei und hol dir ausreichend Moneten. Kauf' nichts von diesem Billigkram!", sourceObjective = "Sprecht mit dem Kassierer der EBvK in der Ersten Bank von Kezan auf Kezan.", completion = "Oh, Ihr seid es, mein Herr! Tut mir leid, bei dem ganzen Pöbel, der hier herumschwirrt, habe ich Euch nicht gleich erkannt.\n\nIhr rumlaufenden Leute! Macht mal langsam hier! {name} ist da!\n\nHier sind Eure Moneten, mein Herr. Kommt jederzeit wieder, wenn Ihr mehr braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26713] = { id = 26713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endkampf in Steinwacht", description = "Es ist nur noch das Oberkommando des Schwarzfels übrig, {name}. Sie haben sich in der Burg Steinwacht verbarrikadiert, unmittelbar südlich unserer Position hier an Keeshans Posten. Begleitet die Kompanie Bravo zur Steinwacht und beendet die Invasion der Schwarzfelsorcs.\n\n{name}, keine Überlebenden.", sourceObjective = "Tötet Tharil'zun und Gath'Ilzogg.", sourceObjectiveStatus = "unverified-source-field" }
quests[26714] = { id = 26714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelflamme, Brut des Weltenbrechers", description = "Als Trottmann verstummt, wird die Welt um Euch herum plötzlich unheimlich still. In einiger Entfernung seht Ihr einen ausgewachsenen schwarzen Drachen!", sourceObjective = "Ruft Dunkelflamme mit dem Horn der Beschwörung. Besiegt Dunkelflamme.", completion = "<Eine einzelne Träne rinnt über Trottmans linke Wange.>\n\nSie starben bei der Verteidigung der Allianz. Bei der Verteidigung unseres Königreichs! Es sind Helden, und so wird man sie auch zur letzten Ruhe betten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26715] = { id = 26715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurion Sturmgrimm", description = "Ich habe Malfurion Euer Kommen angekündigt. Er schien sehr daran interessiert zu sein, Euch persönlich zu treffen.\n\nIhr solltet ihn im Tempel des Mondes aufsuchen. Er steht neben unserer geliebten Tyrande Wisperwind. Seit seiner Rückkehr ist er nicht von ihrer Seite gewichen.\n\nAber ich muss Euch warnen... Malfurion hat seine Zweifel. Es könnte sein, dass Euer Volk Euch eine große Last aufgebürdet hat, als es Euch auswählte, sich mit ihm zu treffen.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm im Tempel des Mondes in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26717] = { id = 26717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen auf Yorgen", description = "Meinesgleichen in Rabenflucht versuchen, die wilden Worgen in diesen Wäldern zu heilen. Der Zustand selbst lässt sich nicht aufheben, doch denjenigen, die sich noch nicht zu sehr verloren haben, kann man den Verstand zurückgeben.\n\nDen meisten kann man zwar nicht mehr helfen, aber wir achten auf die, die noch Überreste ihres Verstandes besitzen... eine Verbindung zu ihrem früheren Leben.\n\nAuf Yorgens Bauernhof habe ich einen einzelnen Worgen gesehen, der in einem Erdhaufen zwischen den Gebäuden grub... könntet Ihr Euch diesen Erdhaufen ansehen? Vielleicht hat er dort etwas zurückgelassen.", sourceObjective = "Untersucht den Haufen lockerer Erde auf Yorgens Bauernhof.", completion = "Scheint ja knapp gewesen zu sein! Aber er lief weg, ohne Euch noch mehr zu verletzen...\n\nVielleicht kämpft er noch dagegen an. Meister Harris muss das erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[26718] = { id = 26718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotkrumen zum Ödland", description = "Etwas schlimmes ist geschehen." }
quests[26719] = { id = 26719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Meister Harris", description = "Meister Harris muss sofort davon erfahren.\n\nHier, bringt dieses Paket mit Leichengras die Straße hinunter zum Lager in Rabenflucht. Erzählt ihm, was wir auf Yorgens Bauernhof gesehen haben.", sourceObjective = "Bringt Oliver Harris in Rabenflucht das Bündel Leichengras.", progress = "Was bringt Euch nach hier draußen, mein Herr?", completion = "Willkommen in unserem bescheidenen Lager. Schön würde ich es nicht nennen, aber es ist zumindest etwas abgeschieden.\n\nWie bitte? Ein {race} auf dem Hof?", sourceObjectiveStatus = "unverified-source-field" }
quests[26720] = { id = 26720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fluch, den wir nicht brechen können", description = "Was wir hier machen, bringt keine Heilung. Die Verwandlung kann nach ihrer Vollendung nicht rückgängig gemacht werden.\n\nDoch der Verstand... Die Alchemie kann den Verstand zurückbringen, wenn noch genug davon übrig ist. Der Worgen, dem Ihr begegnet seid, kämpft anscheinend um seinen, {name}. Wir müssen ihn wiederfinden.\n\nEr ist von Yorgens Hof geflohen, also durchsucht Addles Siedlung im Süden; vielleicht lauert er in einem der Gebäude.\n\nInjiziert ihm den Inhalt dieser Ampulle, er wird ihn betäuben. Ihr müsst ziemlich nah herankommen.", sourceObjective = "Durchsucht Addles Siedlung nach dem lauernden Worgen und betäubt ihn mit Harris' Ampulle.", progress = "Habt Ihr Addles Siedlung gründlich durchsucht?\n\nIch würde an Eurer Stelle noch einmal ganz hinten in der Scheune nachsehen. Vieles kann in einem solchen Gebäude lauern.", completion = "Ihr habt ihn!\n\nWir haben keine Zeit zu verlieren. Wir werden die Verabreichung des Serums sofort vorbereiten.\n\nBIBBERS! Bereitmachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26721] = { id = 26721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bibbers Spinnen", description = "M-Meister Harris benötigt viele Reagenzien für seine Seren. Ich muss sie für ihn sammeln.\n\nDie meisten sind nicht so schlimm... Leichengras ist natürlich schlimm, aber nicht halb so schlimm wie Witwengift. Habt Ihr Euch die Witwen hier in der Gegend mal angesehen? Schon die Jungen sind mannsgroß. Selbst mit einem Gewehr halte ich die Jagd auf sie nicht aus!\n\nSie jagen mir zu viel Angst ein. Wenn Ihr sie für mich jagt, werde ich Euch gern dafür bezahlen! Bringt nur etwas Witwengift mit! Ihr findet sie in den Wäldern im Osten, direkt nördlich der Straße.", sourceObjective = "Erbeutet 8 Witwengiftbeutel von schwarzen Witwen.", progress = "Habt Ihr sie? Bitte sagt mir, dass Ihr sie habt...", completion = "Oh danke, vielen Dank! Ihr habt mich vor den Wäldern mit all diesen furchtbaren Kreaturen bewahrt!\n\nZumindest für einen Tag...", sourceObjectiveStatus = "unverified-source-field" }
quests[26722] = { id = 26722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief vergraben", description = "<Ihr befestigt den Bogen am Stab. Das Artefakt ist fast komplett. Doch es gibt eine große Lücke mitten im Kopf des heiligen Symbols.>\n\n<Erneut scheint es an Eurem Arm zu ziehen und Euch zu einem Loch in der Wand und den verschlungenen Tunneln dahinter zu führen. Dort muss sich das letzte Teil befinden.>", sourceObjective = "Sucht im Tunnel unter den Katakomben des Morgenrotwaldes nach dem lichtgeschmiedeten Wappen.", completion = "<In den dunkelsten Tiefen dieses Lehmtunnels entdeckt ihr ein schwaches Leuchten. Das letzte Teil ist gefunden!>", sourceObjectiveStatus = "unverified-source-field" }
quests[26723] = { id = 26723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Morbent Teufel", description = "Der letzte, an den ich mich erinnere, bevor ich mich in den Wäldern verlor, ist Morbent Teufel. Er war ein abscheulicher Totenbeschwörer und der Grund dafür, dass so viele widerwärtige Untote dieses Land heimsuchen.\n\nIch habe einen Abenteurer gebeten, ihm ein Ende zu machen. Ich hatte angenommen, dass das auch geschehen sei! Aber Schwester Elsington hat mir gesagt, das Land sei immer noch voller Ghule und Schreckgespenster, die aus dem Grab gerissen wurden.\n\nMorbent Teufel hätte seinen letzten Atemzug in dem Haus auf dem Verlassenen Gut, nördlich des Friedhofs von Rabenflucht tun sollen. Seht nach, was aus ihm geworden ist...", sourceObjective = "Sucht auf dem Verlassenen Gut nach Hinweisen auf Morbent Teufel.", completion = "Seine Kleidung und Blutflecken? Wenn das keine Tricks sind, dann etwas noch schlimmeres...", sourceObjectiveStatus = "unverified-source-field" }
quests[26724] = { id = 26724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der lauernde Lich", description = "Die anderen teilen meinen Verdacht. Morbent Teufel lebt im Untod weiter... und ist vielleicht noch mächtiger als zuvor. Ein Totenbeschwörer wurde getötet, doch an seine Stelle könnte ein Lich getreten sein. Und er wird dieses Land weiter zerstören.\n\nIch erinnere mich daran, wie der Dämmerwald vor all dem war, {name}. Ich erinnere mich an einen hellen Himmel und friedliche Wälder. Das kann nicht so weitergehen! Morbent Teufel muss endlich gestoppt werden.\n\nSprecht mit Schwester Elsington. Ihre Vision verrät Euch vielleicht, wo sich Morbent Teufel aufhält und wie man ihn besiegen kann.", sourceObjective = "Sprecht mit Schwester Elsington.", completion = "Es ist ermutigend, dass jemand, der sich erst kürzlich erholt hat, von den Nöten anderer berührt wird. Sven erspart sich Leid, weil er nicht über sein eigenes Unglück grübelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26725] = { id = 26725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Lichte geführt", description = "Sven hat Recht. Ich fühle etwas Mächtiges und Böses tief unter dem Friedhof von Rabenflucht. Das Böse verbirgt sich in seinen Katakomben. Morbent Teufel könnte die Ursache dafür sein.\n\nIhr werdet die Macht des Lichts brauchen, um ihn zu besiegen, {name}. Sven sagte mir, dass die Helden, die Morbent Teufel ursprünglich töteten, ein Artefakt aus lichtgeschmiedetem Eisen benutzten, das von heiliger Macht erfüllt war. Das Artefakt ist immer noch hier!\n\nIch fühle es ebenfalls. Es ist ein schimmerndes Licht in der Dunkelheit. Sucht in Rabenflucht danach und lasst Euch vom Licht führen.", sourceObjective = "Findet die lichtgeschmiedete Rute auf dem Friedhof von Rabenflucht.", completion = "<Ihr findet einen leuchtenden Metallstab, der in der kalten Erde vergraben wurde. Doch es gibt Löcher darin. Anscheinend fehlen Teile des Artefakts.>", sourceObjectiveStatus = "unverified-source-field" }
quests[26726] = { id = 26726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Triumphale Rückkehr", description = "Kehrt nach Seenhain zurück und meldet Solomon, dass die Invasion des Schwarzfels vereitelt wurde. Sorgt dafür, dass er den Preis für unsere Freiheit begreift - dass wir fünf unserer größten Helden verloren haben, um das Rotkammgebirge und letzten Endes auch Sturmwind zu retten.\n\nIhr seid der letzte Überlebende der Kompanie Bravo, {name}. Sorgt dafür, dass ihr Vermächtnis weiterlebt.\n\nWegtreten.", sourceObjective = "Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.", completion = "Man wird sie niemals vergessen, {name}. Die Geschichte von dem, was Ihr und der Rest der Kompanie Bravo geopfert habt, um das Rotkammgebirge zu retten, werden noch viele Generationen hören.\n\nDen Verlust Eurer Freunde kann ich nicht wettmachen, trotzdem möchte ich Euch für eine solch heroische Tat belohnen. Hier sind Keeshans Habseligkeiten - mehr haben wir nicht gefunden, als wir den See nach seiner Leiche absuchten. Trottmann hat mir erklärt, Keeshan hätte sicherlich gewollt, dass der einzige Überlebende der Kompanie Bravo etwas davon nimmt. Vergesst sie nicht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26727] = { id = 26727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Einbalsamierers", description = "Ihr seid nicht der erste Narr, der von Calvinius manipuliert wurde! Wir nennen diesen tüdeligen alten Mann den Einbalsamierer. Er ist ein abscheulicher Totenbeschwörer und der Fluch dieser Stadt.\n\nUnd nun nähert sich uns seine schreckliche Schöpfung, die mit den Materialien, die Ihr ihm gebracht habt, zusammengenäht und ins Leben gerufen wurde!\n\nDiese schreckliche Kreatur wird in wenigen Momenten über uns kommen! Wenn Ihr ein Herz habt, {name}, dann werdet Ihr der Nachtwache helfen, diese Monstrosität zu vertreiben und unsere Stadt zu retten!", sourceObjective = "Tötet Kleiner in Dunkelhain.", completion = "Dem Lichte sei Dank, er ist weg...\n\nIhr habt durch Eure Hilfe bei der Rettung der Einwohner Wiedergutmachung geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26728] = { id = 26728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenaufruf: Dämmerwald!", description = "{name}, die Bürger von Dämmerwald benötigen dringend Eure Unterstützung! Ich habe hier einen Brief von Kommandantin Althea Schwarzhaupt, der Anführerin der Nachtwache. Sie bittet um Hilfe.\n\nUm nach Dunkelhain zu kommen, solltet Ihr die Brücke benutzen, die sich in der südwestlichen Ecke des Rotkammgebirges befindet. Auf der anderen Seite der Brücke beginnt Dämmerwald. Dann müsst Ihr nur noch der Straße nach Dunkelhain folgen. Hütet Euch vor den wilden Bestien, die außerhalb der Ortschaften lauern!", sourceObjective = "Reist nach Dämmerwald und meldet Euch bei Kommandantin Althea Schwarzhaupt in Dunkelhain.", completion = "Ihr seid die Hilfe, die wir angefordert haben?\n\n<Althea seufzt.>\n\nDann müsst Ihr uns wohl genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26729] = { id = 26729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserelementare", description = "Ich kam ins Schlingendorntal, um etwas zu untersuchen, das Altar von Naias genannt wird, doch dummerweise widersetzte ich mich Colonel Kurzens Annährungsversuchen, was mir einige Jahre in diesem Käfig dort einbrachte. Jetzt bin ich wieder draußen, also spricht nichts dagegen, meine ursprünglichen Studien fortzusetzen .\n\nDer Altar steht auf einer Insel im Westen, südlich von Zul'Kunda. Besorgt mir einige Armschienen von den Wasserelementaren der Insel.\n\nOh, und Ihr könnt dieses Gerät benutzen, wenn Ihr fertig seid. Dann müsst Ihr den ganzen Weg hierher zurück nicht laufen.", sourceObjective = "Holt 6 Armschienen eines Wasserelementars.", progress = "Ja, {name}?", completion = "Die reichen für meine Zwecke. Allerdings können wir den Altar nicht nur mit Armschienen aktivieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[26730] = { id = 26730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man kann den Murloc aus dem Ozean holen...", description = "Ich brauche etwas, um an die reine, elementare Kraft dieser Armschienen zu kommen... etwas starkes und abschleifendes, was aber dennoch zum Meer gehört.\n\nDie Murlocs der Düsterkiemen sind vom Meer ins Landesinnere gezogen, tragen aber immer noch Phiolen mit Meersalz bei sich. Ich weiß nicht, wofür sie das Salz benötigen, aber es eignet sich gut für unsere Studien. Ihr findet die Düsterkiemen im Tal südlich des Rebellenlagers und östlich der Ruinen von Bal'lal.", sourceObjective = "Holt 6 Phiolen mit Meersalz von den Murlocs der Düsterkiemen im Nördlichen Schlingendorntal.", progress = "Das Salz?", completion = "Wir haben, was wir brauchen. Seid Ihr bereit dazu, den Altar von Naias zu aktivieren, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[26731] = { id = 26731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar von Naias", description = "Das Salz, das Ihr gebracht habt, reichte aus, um die Verzauberungen im Inneren der Armschienen zu aktivieren. Ich habe diese Verzauberungen gesammelt und zu einem Beschwörungsstein zusammengefügt... eine Gabe, könntet Ihr sagen.\n\nKehrt zur Insel Naias zurück und legt die Gabe auf Naias' Altar. Ruft mich, wenn Ihr Naias' Herz habt.", sourceObjective = "Beschwört Naias mit Naias' Gabe und holt das Herz von Naias.", progress = "Ich warte gespannt auf das Ergebnis.", completion = "Meine Kollegen von den Kirin Tor werden sich freuen, dass das Herz nun uns gehört.\n\nDanke für Eure Unterstützung, {name}. Ohne Euch hätte ich das nicht geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[26732] = { id = 26732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Medizin", description = "Ich habe den Verdacht, dass Kurzens Medizinmänner nicht nur Medizin verteilen. Kurzen benötigt etwas, um aufkeimenden Ungehorsam zu ersticken. Ein Elixier getarnt als \"Medizin\", wäre dafür sehr gut geeignet.\n\nWir brauchen diese Arzneien für unsere Studien. Durchsucht Kurzens Truppenlager im Südosten - seine Medizinmänner und Dschungelkämpfer sollten die Heilmittel bei sich tragen.", sourceObjective = "Besorgt 7 Dschungelarzneien aus Kurzens Truppenlager.", progress = "In meiner Freizeit beschäftige ich mich ein wenig mit Alchemie.", completion = "Gut gemacht, {name}. Dann wollen wir mal sehen, was in diesem Elixier steckt...", sourceObjectiveStatus = "unverified-source-field" }
quests[26733] = { id = 26733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrollprobe", description = "<Bruder Nimetz analysiert die Proben, die Ihr ihm gegeben habt.>\n\nDas... das ist nur Basiliskenblut!\n\nNein, es besteht größtenteils aus Basiliskenblut. Sie haben jedoch etwas hinzugefügt. Für einen vernünftigen Vergleich brauche ich eine Kontrollprobe.\n\nWahrscheinlich stammt das Blut von Kristallrückenbasilisken, die östlich des Truppenlagers vorkommen. Bringt mir einige reine Proben, dann kriege ich schon heraus, was in dem Elixier ist.", sourceObjective = "Besorgt 7 Proben Kristallrückenbasiliskenblut.", progress = "Etwas in diesem Elixier ist nicht gerade gesundheitsförderlich, {name}. Ich habe meine Analyse zwar noch nicht beendet, aber ich kann es spüren.", completion = "Das reicht. Wartet bitte einen Moment, während ich es teste.", sourceObjectiveStatus = "unverified-source-field" }
quests[26734] = { id = 26734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle des Wahnsinns", description = "Ich habe das Basiliskenblut aus dem Elixier reduziert. Dabei habe ich einen ungewöhnlichen Bestandteil gefunden. Es scheint sich um eine Art blauen Kristall zu handeln...\n\n<Bruder Nimetz betrachtet seine Notizen.>\n\nEs ist kein singender blauer Kristall... und auch kein pulsierender blauer Splitter...\n\n<Er blättert einige Seiten vor.>\n\n... kein Stück des Gedankenauges. Nein, so etwas haben wir in Schlingendorntal noch nie gesehen. Jemand muss doch noch etwas von dieser Substanz besitzen. Ich will sie haben. Seht bei Kurzens hochrangigen Truppen hinten in ihrer Höhle nach.", sourceObjective = "Erbeutet einen flüsternden blauen Stein von Kurzens Truppen im Vorratslager.", progress = "Geht bitte vorsichtig damit um, {name}. Wir wissen nicht, was es ist.", completion = "<Bruder Nimetz öffnet einen Beutel. Ihr legt den Kristall hinein.>\n\nIch wusste, dass jemand noch etwas von dieser Substanz haben würde. Ich werde dies meinen Kontakten in Fort Livingston südlich von hier schicken. Hoffentlich haben sie etwas mehr Glück damit.\n\nDanke für alles, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26735] = { id = 26735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurzens Schicksal", description = "Hallo, {class}.\n\nWir sind Soldaten aus Sturmwind und haben in Kurzens Truppenlager rebelliert. Der große Außenposten liegt südöstlich von hier. Wir standen unter dem Kommando von Colonel Kurzen, bis er und seine Vertrauten begannen, den Verstand zu verlieren...\n\nWir lehnten uns auf, errichteten hier unser Lager und wehrten uns gegen Kurzen. Nun habe ich von meinen Kontakten erfahren, dass Kurzen verschwunden ist. Ich traue dieser Quelle, aber ich möchte das noch einmal von einem Außenstehenden hören. Bitte begebt Euch in das Lager und sucht nach Belegen für sein Schicksal.", sourceObjective = "Findet das Gefängnisregister von Kurzens Truppenlager und die Offiziersakten von Kurzens Truppenlager.", progress = "Habt Ihr etwas entdeckt, {name}?", completion = "Sie haben ihn UMGEBRACHT? Dabei dachte ich die ganze Zeit, er würde mit eiserner Hand über sie herrschen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26736] = { id = 26736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Wahnsinn verschont", description = "Kurzens Tod ist eine Erleichterung, aber interessanter und momentan wesentlicher ist, dass dies ein Zeichen dafür sein könnte, dass es potentielle Verbündete im Lager gibt.\n\nMich interessiert nicht, was in dem Gefängnisregister steht. Ich weiß GENAU, weshalb die 3 eingesperrt wurden: weil sie sich weigerten, Befehle zu befolgen. Der Wahnsinn muss sie verschont haben, so wie meine Rebellenkameraden hier. Sie wurden eingesperrt, weil sie aufbegehrten.\n\nFindet sie, {name}. Findet sie und schickt sie hierher.", sourceObjective = "Rettet Berrin Brennfeder, Emerine Junis und Osborn Widrikus aus Kurzens Truppenlager.", completion = "Danke, {name}. Ich lag mit meiner Vermutung anscheinend richtig... die drei Gefangenen scheinen der Krankheit, die Kurzen und den Rest seiner Männer ergriffen hat, entkommen zu sein.\n\nVor Eurer Ankunft teleportierte Emerine sich und die anderen nach Sturmwind, um sich nach all den Entbehrungen zu säubern. Sie haben versprochen, bald zurückzukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26737] = { id = 26737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beendet Kurzens Vermächtnis", description = "Unsere Verbündeten wurden aus Kurzens Truppenlager evakuiert, nun müssen wir es ein letztes Mal angreifen. Sie werden nie wieder so schwach sein wie gerade und mit Eurer Hilfe können wir sie vielleicht so weit schwächen, dass sie sich nicht mehr davon erholen.\n\nDiese vier Namen, die in den Offiziersakten erwähnt werden - Anders, Gaulus, Miranda und Esquivel - sind die höchstrangigen übrig gebliebenen Soldaten. Sucht nach ihnen in der Höhle im hinteren Teil des Truppenlagers. Sollten diese vier verschwinden, werden die Konsequenzen für Kurzens Streitkräfte verheerend sein.\n\nGehet mit Ehre, {name}.", sourceObjective = "Tötet Oberstabschef Anders, Oberstabschef Gaulus, Oberstabschef Miranda und Oberstabschef Esquivel im Vorratslager.", completion = "Hervorragend gelöst, {name}. Meine Männer und ich kümmern uns um den Rest.\n\nOhne Kurzen können wir vielleicht die Expedition, die wir im Schlingendorntal geplant hatten, fortsetzen und... ahh...\n\nSpielt keine Rolle. Bitte seht Euch in unseren Rüstungslagern um. Vielleicht findet Ihr etwas passendes.", sourceObjectiveStatus = "unverified-source-field" }
quests[26738] = { id = 26738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisch geschlüpft", description = "Als Ihr die Sachen des Soldaten durchsucht, bemerkt Ihr ein frisch geborenes, weibliches Raptorjunges, das zu Euch aufsieht. Ist es Kurzens Milizsoldaten die ganze Zeit über gefolgt?\n\nIhr seht, wie es Euch mustert, sich Euer Gesicht einprägt und Eure Bewegungen beobachtet.\n\nDas Schmetterschwanzjunge geht eine Bindung mit Euch ein.\n\nVielleicht weiß jemand im Rebellenlager etwas mit einem Raptorjungen anzufangen.", sourceObjective = "Bringt das Schmetterschwanzjunge zu Korporal Sethmann im Rebellenlager im Nördlichen Schlingendorntal.\n\nBereitgestellter Gegenstand:", completion = "Ja, die Kleine scheint Euch zu mögen. Ihr habt Glück... in diesem Alter sind Raptoren ruhig, friedlich und leicht auszubilden. Behaltet sie, {name}... sie könnte Euch noch von Nutzen sein.\n\nUm genau zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[26739] = { id = 26739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich glaube, sie hat Hunger", description = "Euer junges Raptorweibchen scheint hungrig zu sein. Wenn Ihr sie behalten wollt, solltet Ihr vielleicht etwas zu fressen für sie finden. Die Schmetterschwänze greifen häufig die Basilisken des Schlingendorntals an. Man findet sie im Osten hinter Kurzens Truppenlager.\n\nWahrscheinlich ist sie noch nicht stark genug, um allein auf die Jagd zu gehen, aber ich bin mir sicher, dass sie frisches Basiliskenfleisch fressen wird.", sourceObjective = "Tötet Kristallrückenbasilisken im Nördlichen Schlingendorntal und lasst Euren Schmetterschwanz 40 Bissen ihres Fleisches fressen.", completion = "Sie wirkt schon größer! Wie Ihr seht, wachsen diese Raptoren schnell. Ihr könnt von Glück sagen, dass Ihr eine so starke Begleiterin gefunden habt.\n\nBehaltet sie bei Euch, solange es geht, {name}. Sie wird sich bestimmt irgendwann als Gewinn für Euch erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26740] = { id = 26740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochen mit Krazek", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblinhändler in Beutebucht einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart – bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek. Das Letzte, was ich gehört habe, war, dass er bei Nesingwary Unterschlupf gefunden hat, im Jägerlager im Süden.", sourceObjective = "Bringt Krazeks Spezialtopf zu Krazek.", progress = "Hallo! Ihr habt etwas für mich?", completion = "Ah ja, das ist einer von Krazeks Spezialtöpfen! Eine geniale Erfindung, aber bisweilen bricht eine Feder oder das Getriebe gerät aus dem Tritt oder so was in der Art. Lasst mich mal sehen, was mit dem hier los ist...\n\nAha! Die Dampfbeschickungsvorrichtung ist völlig verrostet, die Gelenkdichtung ist rissig und dem Fobulator fehlen Zähne. Es wundert mich, dass der Topf in diesem Zustand überhaupt irgendetwas kochen konnte!\n\nOb ich ihn reparieren kann? Natürlich kann ich ihn reparieren!\n\nAber das kostet. So etwas kostet immer, oh ja...", sourceObjectiveStatus = "unverified-source-field" }
quests[26741] = { id = 26741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[26742] = { id = 26742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkenntnisse über die Blutskalpe", description = "Ich habe mich nie richtig bei Euch für meine Rettung bedankt.\n\nDanke, {name}.\n\nIch bin immer noch etwas erschöpft von meiner Gefangenschaft, deshalb dachte ich, Ihr könntet mir vielleicht bei meinen Studien helfen. Als ein Schamane des Wildhammerklans interessiere ich mich natürlich sehr für die schamanistischen Methoden des Blutskalpklans.\n\nIhre Magie scheint sich in eine interessante Richtung entwickelt zu haben. Hätte ich eines der Totems, die ihre Schamanen benutzen, könnte ich mit meinen Studien beginnen. Ihr findet sie in den Ruinen von Bal'lal, an der Küste im Südwesten.", sourceObjective = "Besorgt ein Totem der Blutskalpe von einem Schamanen der Blutskalpe.", progress = "Seid vorsichtig. Sie werden sich wahrscheinlich wehren.", completion = "<Berrin betrachtet die Inschriften auf dem Totem.>\n\nIch glaube, ich kann die Worte lesen... Faszinierend!\n\nTsul'kalu, Mahamba, Pogeyan... was sind das für Namen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26743] = { id = 26743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Blutskalpen heilig", description = "Ahh... das müssen die Namen ihrer Totemwesen sein - der Tiere, die sie den Geistern zuordnen. Mal sehen... Mahamba als Wasser, Tsul'Kalu als Erde, Pogeyan als... Luft? Feuer? Diesen Teil kann ich nicht entziffern.\n\nIch würde gern mehr über ihre Geister erfahren. Hier in der Nähe, in den Ruinen von Tkashi, haben die Blutskalpe ein Lager errichtet. Vielleicht könnt Ihr dort Einzelheiten herausfinden.", sourceObjective = "Besorgt eine Ikone von Tsul'kalu, eine Ikone von Mahamba und eine Ikone von Pogeyan aus dem Lager der Blutskalptrolle in den Ruinen von Tkashi.", progress = "Wahrscheinlich basieren die Totemwesen auf einigen der fantastischen Kreaturen, die durch diesen Dschungel streifen.", completion = "Erst rettet Ihr mich aus der Zelle des Wahnsinnigen und nun bringt Ihr mir einige der Schlüssel zum Verständnis des Trollschamanismus.\n\nDiese Woche kann sich sehen lassen!\n\nNoch einmal vielen Dank, {name}. Ich werde dafür sorgen, dass der Wildhammerklan Euch unterstützt, wenn Ihr Eure Reise fortsetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26744] = { id = 26744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefe Wurzeln", description = "Doch nun zu etwas anderem: Ich stelle gerade eine Sammlung von Trollgeschichten und -legenden für ein... persönliches Projekt zusammen. Vielleicht könntet Ihr mir helfen, einige davon zu finden.\n\nDie Blutskalpe in den Ruinen von Bal'lal, an der Küste im Südwesten, besitzen eine große Schrifttafel, auf der einige ihrer Geschichten festgehalten sind. Ich würde Euch natürlich für die Geschichten, die Ihr mir bringt, entschädigen.", sourceObjective = "Holt die Schrifttafel der Blutskalpe aus den Ruinen von Bal'lal im Nördlichen Schlingendorntal.", progress = "Seid Ihr schon in den Ruinen von Bal'lal gewesen? Habt Ihr die Tafel gefunden?", completion = "Um ehrlich zu sein, schicke ich diese Informationen zu meiner Frau und meinem Sohn zuhause in Sturmwind. Sie möchten wissen, was ich hier draußen im Dschungel mache, aber ich kann sie nur selten besuchen. Jede Kleinigkeit hilft.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26745] = { id = 26745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieblingsschädel", description = "Euer zahmes Raptorweibchen scheint ein neues Spielzeug gefunden zu haben: Einen Schädel von einem nahegelegenen Trollschädelhaufen.\n\nIhr wisst nicht, was diesen Schädel von den anderen unterscheidet, aber aus irgendeinem Grund lässt sie ihn nicht wieder fallen.\n\nOsborn Widrikus, der Gnom, den Ihr aus Kurzens Truppenlager gerettet habt, ist ein Experte für Trollgeschichte und Trollphysiologie. Vielleicht weiß er, warum dieser Schädel etwas besonderes ist.", sourceObjective = "Meldet Euch bei Osborn Widrikus im Rebellenlager und zeigt ihm den neuen Schädel Eures Schmetterschwanzjungen.\n\nBereitgestellter Gegenstand:", completion = "Was haben wir denn da? Ein junger Raptor mit seinem Haustier: seinem Hausmensch. Hah!\n\nAber kommen wir zu Wichtigerem: Was für einen Schädel habt Ihr da? Das war kein gewöhnlicher Troll. Er war groß...\n\n<Osborn klopft auf den Schädel.>\n\n... und stark. Wisst Ihr, ich wollte immer schon mal Trollmagie ausprobieren. Kann doch nicht so schwer sein, oder? Wollen wir diesen starken Mann als Versuchskaninchen nehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26746] = { id = 26746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für solche Dinge", description = "<Osborn wirft noch einen Blick auf den Schädel.>\n\nAls er noch lebte, war er stark und mächtig, ein Fürst der Trolle. Mit unserer Hilfe kann er wieder ein Fürst werden.\n\nDie Strauchdiebe der Blutskalpe, die durch die Ruinen im Südwesten ziehen, sammeln magische Fetische, die wir gebrauchen könnten. Sie vergraben diese Artefakte, um sie zu verstecken. Findet diese Artefakte mit Hilfe Eures Jungen, {name}... und bringt sie dann her.", sourceObjective = "Lasst Euer Schmetterschwanzjunges 8 Tkashifetische erschnüffeln.", progress = "Wie viele Fetische habt Ihr gefunden?", completion = "Die verschaffen uns ein wenig... wie heißt noch gleich dieses Trollwort? Voodoo? Juju? Tiklabang?\n\nIst egal. Wenn wir einen Troll neu erbauen wollen, brauchen wir Trollmagie und diese Fetische sind voll davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[26747] = { id = 26747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Exemplar aus Fleisch und Blut", description = "Die Seele ist bereit, der Körper jedoch nicht. Für einen Schädel, der so wohlgeformt, so wunderbar und so schön wie dieser ist, brauchen wir einen passenden Körper.\n\nGan'zulah, der Häuptling der Blutskalpe, ist durch brutale Gewalt auf den Thron gekommen. Sollte er noch leben, werdet Ihr ihn in Zul'Kunda im Westen finden.\n\nSeinen Körper zu rauben, wird nicht leicht sein, aber <ein kräftiger/eine kräftige:c> {class} wie Ihr wird das schon schaffen. Bringt ihn hierher, wenn Ihr fertig seid.", sourceObjective = "Holt Gan'zulahs Leiche aus Zul'Kunda.", progress = "Gan'zulah war ein Schläger und Tyrann. Ich spüre, dass dieser Troll anders sein wird. Diese Trollmagie ist leichter als ich dachte!", completion = "Das habt Ihr gut gemacht, {race}. Wir haben einen Kopf, einen Körper und etwas Juju-Voodoo-Mojo-Unsinn. Jetzt noch ein kleiner Elektroschock, um alles in Gang zu bringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26748] = { id = 26748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfürst Mandokir", description = "{race}. Ihr habt gerade euren schlimmsten Alptraum erweckt. Dachtet Ihr etwa, ich wäre ein Freund, {race}? Ah, ha ha haaaa!\n\nIhr habt Euren Zweck erfüllt. Dank Euch bin ich wieder ins Reich der Lebenden zurückgekehrt. Deshalb werde ich Euch nicht töten, sondern Euch einen Handel anbieten.\n\nGebt mir den Raptor.\n\nEuch dürfte bereits klar sein, dass dies kein gewöhnlicher Raptor ist. Ich brauche einen Ersatz für Ohgan. Tut es, sonst werdet Ihr und der Gnom meine Rache zu spüren bekommen.", sourceObjective = "Bringt Blutfürst Mandokir im Rebellenlager das Schmetterschwanzeifragment.", progress = "Ich verlange nur den Raptor, {race}. Gebt ihn mir, dann lebt der Gnom weiter.", completion = "Freut mich, dass Ihr zur Besinnung gekommen seid.\n\nIhr müsst uns mal in Zul'Gurub besuchen, {race}. Ich werde Euch beobachten...", sourceObjectiveStatus = "unverified-source-field" }
quests[26749] = { id = 26749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priesterin Thaalia", description = "Danke, {name}. Ich weiß, dass Ihr mein Leben nicht hättet retten müssen.\n\nEs ist schlimm, dass Blutfürst Mandokir zurückgekehrt ist. Er wurde vor einigen Jahren in Zul'Gurub getötet. Wir dachten, wir würden ihn und sein Volk nie wiedersehen. Die Trolle von Zul'Gurub versuchten sich an einem schrecklichen, widerwärtigen Ritual. Wenn Mandokir lebt, dann ist es nur logisch anzunehmen, dass er nicht der einzige ist.\n\nDie Forscher in Fort Livingston, weit im Süden, wissen vielleicht mehr. Sprecht mit ihrer Priesterin.", sourceObjective = "Sprecht mit Priesterin Thaalia in Fort Livingston im Nördlichen Schlingendorntal.", completion = "Mandokir lebt, ja.\n\nIhr tragt die Verantwortung, ja.\n\nVielleicht könnt Ihr ihn noch aufhalten, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26750] = { id = 26750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Geheiß der Steinmutter", description = "Es ist Zeit. Die Steinmutter wird mit Euch sprechen. Ihr findet ihren Thron im Norden Tiefenheims, über dem Geschliffenen Schlund.", sourceObjective = "Sprecht mit Therazane der Steinmutter.", completion = "Ihr seid also gekommen.\n\nFleischlinge wie Ihr haben meine Tochter getötet... meine einzige Tochter - ohne, dass sie etwas getan hätte.\n\nUnd als ob es nicht schon genug wäre, mich meiner Familie zu berauben, haben sich mehr von Euch um Todesschwinge geschart, um ihm dabei zu helfen, mein Heim zu verwüsten.\n\nWie vermessen von Euch, vor mir zu erscheinen und um MEINE Hilfe zu bitten. Ich bin dazu verleitet, Euch an Ort und Stelle zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26751] = { id = 26751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bevölkerungskon-Trolle", description = "Ich habe vernommen, dass Ihr bald nach Zul'Kunda aufbrechen werdet. Ich habe eine kleine Aufgabe, die Ihr dort erfüllen könntet.\n\nDie Trolle werden zu zahlreich für das Schlingendorntal. Die Blutskalpe im Westen, die Schädelspalter im Osten... sie ergießen sich aus ihren Ruinen in den Dschungel und zerstören das natürliche Gleichgewicht der Region. Es wird Zeit, dass wir dieses Gleichgewicht wiederherstellen.\n\nZul'Kunda ist die Hauptstadt der Blutskalpe. Dort werdet Ihr die höchstrangigen Blutskalpe finden. Reduziert ihre Anzahl und kehrt zu mir zurück.", sourceObjective = "Tötet 7 Mystiker der Blutskalpe, 7 Jäger der Blutskalpe, 7 Späher der Blutskalpe und 1 Bestienmeister der Blutskalpe.", progress = "Wir sind Euch dankbar für Eure Hilfe hier im Schlingendorntal, {name}.", completion = "Das Gleichgewicht ist wiederhergestellt - erst einmal. Vielleicht werden wir Euch in Zukunft noch einmal rufen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26752] = { id = 26752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Audienz bei der Steinmutter", description = "Bleibt wo Ihr seid, Champion. Ich habe noch nicht entschieden, was ich mit Euch und Eurem Irdenen Ring anstelle.", sourceObjective = "Nehmt an der Audienz bei der Steinmutter teil.", completion = "Gut gemacht, Bruder. Die Steinmutter hört zu, und die Weltensäule ist fast zum Greifen nah.", sourceObjectiveStatus = "unverified-source-field" }
quests[26753] = { id = 26753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen der Toten", description = "<Vor Euch neigt sich die nackte Erde dem dunklen Eingang zu den Grüften entgegen.>\n\n<Ihr spürt, wie das lichtgeschmiedete Artefakt Euch darauf zuzieht. Ist das andere Teil vielleicht dort unten?>", sourceObjective = "Findet den lichtgeschmiedeten Bogen in den Katakomben des Morgenrotwaldes.", completion = "<Im Dreck dieser Nische funkelt helles Metall. Ihr habt einen weiteren Teil des Artefakts gefunden!>", sourceObjectiveStatus = "unverified-source-field" }
quests[26754] = { id = 26754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morbents Bann", description = "<Die Teile passen. Ihr habt das geheiligte Artefakt zusammengesetzt. Es strahlt ein heiliges Licht aus. Damit solltet Ihr in der Lage sein, Morbent Teufels dunkle Magie zu besiegen.>\n\n<Tiefer im Tunnel, entgegengesetzt der Richtung, aus der Ihr gekommen seid, ertönt ein verstörendes Kichern. Es ist das rasselnde Lachen eines Lich. Morbent Teufel ist direkt vor Euch!>", sourceObjective = "Schwächt Morbent Teufel mit Morbents Bann und besiegt ihn.", completion = "Möge das widerliche Ungeheuer dieses Mal tot bleiben!\n\nIch werde nach unten gehen und seine Asche in die Winde verstreuen, {name}. Ihr habt Großes vollbracht. Vielleicht wird in Dämmerwald mit der Zeit wieder Frieden einkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26755] = { id = 26755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg von der Front", description = "Oh, gut! Ihr habt noch ein Katapult mitgebracht! Klei mag älter als Staub sein, aber er weiß, wie man eine schreckliche Kriegsmaschine baut.\n\nNun, Ihr habt es sicher nicht den weiten Weg bis hierher gebracht, weil Ihr ein wenig Bewegung wolltet, Fleischsack. Schwingt Euch in eines dieser Dinger und bombardiert die Fungusschrecken und ihre Verstärkung, die aus Nadelfelsbruch herausströmen.\n\nWir müssen sie von der Front fernhalten!", sourceObjective = "Bombardiert 30 Fungusschrecken und/oder Mitglieder der Verstärkung der Steintroggs.", completion = "Das ist ein guter Anfang, {name}, aber Ihr müsst in die Stadt fliegen und dort ein wenig Aufruhr verursachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26760] = { id = 26760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Unmögliche möglich machen", description = "Ich bin optimistisch, aber wir sollten professionell bleiben. Wir behandeln ihn wie alle anderen.\n\nAb in die Guillotine mit ihm... und wenn die Alchemie nicht wirkt, kommt er nicht wieder heraus.\n\nBibbers und ich kümmern uns darum. Bitte bleibt zurück und seht aus sicherer Entfernung zu.", sourceObjective = "Seht zu, wie Oliver Harris und Bibbers versuchen, den lauernden Worgen zu heilen.", completion = "Geschafft... Endlich! Ich kann Euch gar nicht genug für die Gelegenheit danken, die Heilung selbst auszuprobieren.\n\nUnser neuer Freund könnte wahrscheinlich ebenfalls Hilfe gebrauchen. Wieso sprecht Ihr nicht mal mit ihm?", sourceObjectiveStatus = "unverified-source-field" }
quests[26761] = { id = 26761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bedrohung für das Königreich", description = "Es besteht kein Zweifel, dass die Defias eine ernsthafte Bedrohung für das Königreich darstellen, aber wir können nicht einfach so deren Versteck betreten und hoffen, dass sich alles zum Guten wendet. Nein, ein Angriff auf die Defias erfordert Zeit und Planung. Überlasst die Logistik mir. Unser Königreich hat auch noch andere Sorgen, gegen die umgehend etwas unternommen werden muss!\n\nReist nach Osten, über Elwynn ins Rotkammgebirge und meldet Euch bei Magistrat Solomon in Seenhain. Ich lasse nach Euch schicken, wenn wir bereit sind, die Defias anzugreifen.", sourceObjective = "Meldet Euch bei Magistrat Solomon in Seenhain im Rotkammgebirge.", completion = "Ich habe schon gehört, dass die Defias wieder auf den Plan getreten sind. Schreckliche Neuigkeiten. Ich wünschte nur, ich hätte bessere zu berichten, aber so wie es aussieht, wird Seenhain angegriffen! Wir verlieren an allen Ecken und Enden Leute. Unsere eigenen Wachen sind viel zu weit verstreut, um mit der Situation fertigzuwerden. Wir brauchen einen Helden, der sich der Sache annimmt!", sourceObjectiveStatus = "unverified-source-field" }
quests[26762] = { id = 26762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reaktiviert die Konstrukte", description = "Wir haben eine ganze Reihe unserer Kriegskonstrukte gen Norden nach Nadelfelsbruch geschickt, aber keines ist je zurückgekehrt. Wir wissen, dass die Mystiker der Steintroggs dafür verantwortlich sind.\n\nWir befürchten nun, dass die Mystiker die Kontrolle übernehmen und unsere Konstrukte gegen uns verwenden werden, so wie sie es mit den Fungusgiganten getan haben.\n\n{name}, betretet die Stadt der Steintroggs und reaktiviert die Konstrukte.", sourceObjective = "Reaktiviert 5 deaktivierte Kriegskonstrukte.", completion = "Das war wirklich gute Arbeit, {name}.\n\nUnsere Konstrukte funktionieren wieder und stehen hinter den feindlichen Linien. Es ist nur noch eine Frage der Zeit, bis uns der Durchbruch und damit die Rettung des Steinvaters gelingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26763] = { id = 26763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venture Company-Bergbau", description = "Um diesen Topf zu reparieren, werde ich Reagenzien brauchen. Und um die zu bekommen, werdet Ihr ein ganz klein bisschen töten müssen. Ich hoffe, das stört Euch nicht.\n\nDiese lästigen Geologen der Venture Company haben einige gerommelte Kristalle gesammelt, die für meine Zwecke genügen würden. Ihr findet sie rund um ihr Basislager im Osten, auf der anderen Seite des Nazferitisees.\n\nIst mir egal, was Ihr tun müsst, um sie zu bekommen.", sourceObjective = "Besorgt 5 gerommelte Kristalle von Angehörigen der Venture Co. beim Nazferitisee.", progress = "Habt Ihr die Kristalle?", completion = "Die sind genau richtig. Einen Moment bitte.\n\n<Krazek wirft die Steine in den Kochtopf und schüttelt sie ein wenig.>\n\nAlles repariert!", sourceObjectiveStatus = "unverified-source-field" }
quests[26764] = { id = 26764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moralischer Bankrott", description = "Euch ist vielleicht aufgefallen, dass die Venture Company den Wald rund um ihr Basislager im Osten komplett gerodet hat. Ihr Vorarbeiter wittert Profit, deshalb hat er Druiden versklavt, die er zwingt, den Wald neu wachsen zu lassen, damit er ihn wieder abholzen kann!\n\nIch persönlich finde das abscheulich, nicht nur, weil ich nicht als erster auf die Idee gekommen bin.\n\nBefreit einige dieser Druiden aus ihrer Gefangenschaft. Sie werden Euch bestimmt dankbar sein.", sourceObjective = "Befreit 3 versklavte Druiden aus dem Basislager der Venture Co.", sourceObjectiveStatus = "unverified-source-field" }
quests[26765] = { id = 26765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Korporal Kaleb zurück", description = "So, dieser Kessel ist repariert. Ich habe sogar eine zweite Dampfpfeife eingebaut. Und seht! Am Boden gibt es einen neuen Zerhacker, der sogar durch Beinknochen schneidet!\n\nJa, ja, Krazeks Spezialtopf stellt Köche zu 100% zufrieden! Ich bin sicher, dass er dem Besitzer gefallen wird.", sourceObjective = "Bringt Krazeks reparierten Topf zu Korporal Kaleb im Rebellenlager im Nördlichen Schlingendorntal.", progress = "Hallo, {name}. Hat der Goblin Krazek meinen Topf repariert??", completion = "Er funktioniert wieder! Das ist toll! Jetzt kann ich mit dem Abendessen anfangen! Vielen Dank, {name}.\n\nIch hoffe, dass Krazek Euch nicht zu viele Unannehmlichkeiten bereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[26766] = { id = 26766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großes Ziel, großer Köder", description = "Wir haben nur eine Chance, Abyssion zu fangen, {name}. Wir müssen sie gut nutzen.\n\nWir testen die Falle am größten Steindrachen am Alabasterschelf.\n\nUm die Steinmatriarchin anzulocken, benötigen wir ausreichende Köder.\n\nNehmt dieses Messer und besorgt Euch 5 Basiliskenfleischstücke. Das sollte sogar für ihren Appetit genügen.", sourceObjective = "Benutzt Mylras Messer, um 5 Basiliskenfleischstücke aus toten Kristallrückenbasilisken zu schneiden.", progress = "Habt Ihr das Fleisch besorgt?", completion = "Das sollte ausreichen, um die Bestie anzulocken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26767] = { id = 26767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Questerstellung", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als nächstes zu tun ist.", sourceObjective = "Erstellt eine Schnitzeljagdquest.", sourceObjectiveStatus = "unverified-source-field" }
quests[26768] = { id = 26768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenfangen leicht gemacht", description = "Das Fragment von einem Drachen bewachen zu lassen, war ein cleverer Schachzug. Sie können es immer an einen anderen Ort bringen, wenn wir uns ihm nähern.\n\nAbyssion zu fangen wird sehr schwer, aber ich habe einen guten Plan.\n\nDer Schattenhammer benutzt magische Fallen, um die Steindrachen an den Boden zu fesseln, während sie ihnen ihre Energie rauben.\n\nWenn wir an eine solche Falle kämen, könnten wir den Zwielichtdrachen vielleicht lange genug festhalten.\n\nGeht nach Osten zum Alabasterschelf und besorgt Euch eine Falle.", sourceObjective = "Besorgt Euch eine Drachenschlinge von den Zwielichtdrachenjägern.", progress = "Wenn die Schlingen gut genug für Steindrachen sind, funktionieren sie vielleicht auch bei Abyssion.", completion = "Lasst uns schauen, ob die Schlinge auch etwas Größeres als einen Drachen festhalten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[26769] = { id = 26769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Flussfahrt", description = "Genießt Euren Anteil an der Beute, {name}!\n\nIch teile nicht gern, aber Geschäft ist Geschäft. Und diesem Betrüger Düsentopf stehen 10% dieses Schatzes zu. Könntet Ihr das zu ihm in seinem Außenposten nördlich von hier bringen?\n\nEr leitet eine kleine Forschungsstation stromaufwärts am Fluss. Verlasst die Stadt in Richtung Nordosten und sucht Horton Hornbläser auf. Er wird Euch kostenlos auf einem seiner Flussschiffe mitnehmen. Sagt ihm, ich hätte Euch geschickt!", sourceObjective = "Geht an Bord von Horton Hornbläsers Flussschiff nordöstlich von Ratschet und macht eine Flussfahrt zu Düsentopfs Außenposten.", progress = "Willkommen, {class}. Seid Ihr gerade mit dem Schiff aus Ratschet gekommen? Gibt es Neuigkeiten?", completion = "<Düsentopf entreißt Euch den Beutel mit Edelsteinen.>\n\nGazlowe nennt das 10%? Sagt ihm, dass ich sie wiegen werde!\n\nWill er etwa, dass ich Euch ein Lieferhonorar zahle? Schon gut. Nehmt Euch was von der Beute!", sourceObjectiveStatus = "unverified-source-field" }
quests[26770] = { id = 26770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystische Meister", description = "Die Mystiker der Nadelfelsen haben die Kontrolle über die Fungusgiganten, die tief unten in ihrer Schlucht entstanden sind, übernommen. Jetzt wollen sie auch noch unsere Kriegskonstrukte übernehmen.\n\nGeht Richtung Norden nach Nadelfelsbruch und unternehmt etwas dagegen. Deswegen seid Ihr doch hier, oder?", sourceObjective = "Tötet 5 Mystiker der Nadelfelsen.", completion = "Ein paar Steintroggs weniger ist nie schlecht. Ich freue mich, dass Ihr doch ein anständiger {class} seid.\n\nSchon bald werden wir erfahren, wo genau mein Vater gefangen gehalten wird. Hoffentlich überlebt Ihr so lange.", sourceObjectiveStatus = "unverified-source-field" }
quests[26771] = { id = 26771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallenprobe", description = "Legt nun die Falle für die Matriarchin aus.\n\nGeht zum westlichen Ende des Alabasterschelfs und platziert die Falle mit dem Basiliskenfleisch in die Mitte des Futterplatzes.", sourceObjective = "Legt die Falle mit dem Fleisch am westlichen Ende des Alabasterschelfs aus.", completion = "Gut gemacht, {name}. Ich hoffe, dass die Falle bei Abyssion ebenso gut funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[26772] = { id = 26772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankensicht", description = "Um Mandokir zu erkennen, müsst Ihr Mandokir sehen.\n\nUm Mandokir zu sehen, müsst Ihr Augen von Raptor nutzen.\n\nIhr habt Euch angefreundet mit Raptor: Ohgan'aka: Tochter von Ohgan.\n\nUm Freundschaft zu stärken, brauchen wir Federn.\n\nGeht nach Nordosten und Ihr werdet Federn finden, ja.", sourceObjective = "Erbeutet 5 Dschungelpirscherfedern von Dschungelpirschern im Nördlichen Schlingendorntal.", progress = "Raptor namens Ohgan'aka, immer noch Eure Freundin.", completion = "Ihr bringt Federn, ja.\n\nIhr könnt Anweisungen befolgen, ja.", sourceObjectiveStatus = "unverified-source-field" }
quests[26773] = { id = 26773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seht Raptor", description = "Wir haben Federn, ja.\n\nWir haben <den/die:c> {class}, ja.\n\nSprecht mit Priesterin, wenn bereit.", sourceObjective = "Sprecht mit Priesterin Thaalia in Fort Livingston, um am Ritual der Gedankensicht teilzunehmen.", progress = "Eure Sicht nicht Ohgan'akas, nein.\n\nIhr seid nicht bereit.", completion = "Was hat Priesterin Euch gesagt?\n\nDer Raptor ist Tochter von Ohgan, Erbe von Mandokirs Thron.\n\nHah!", sourceObjectiveStatus = "unverified-source-field" }
quests[26774] = { id = 26774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedankenkontrolle", description = "Gedankensicht nicht genug, nein.\n\nGedankenkontrolle viel mächtigere Magie, ja.\n\nMächtige Magie braucht mächtige Reagenzien und Trollgehirn ist mächtige Reagenz.\n\nBraddok in Zul'Mamwe, sehr klug, ja.\n\nGeht nach Süden und seht Euch an großes Gehirn von Braddok.", sourceObjective = "Erbeutet Braddoks Riesengehirn von Braddok in Zul'Mamwe.", progress = "Riesengroße Zauber brauchen riesengroße Gehirne, ja.", completion = "Wartet, nächster Teil ist schwierig, ja.\n\nViele Möglichkeiten für Fehlschlag, ja.\n\nAber {name} und {name}'aka werden wieder zusammenkommen... ja, werden sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[26775] = { id = 26775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid Raptor", description = "Gedankenkontrolle sehr mächtig, ja.\n\nMit Glück könnt Ihr Ohgan'aka helfen, aus Zul'Gurub zu fliehen.\n\nDann wird Ohgan'aka wieder {name}'aka werden!\n\nSprecht mit Priesterin, ja, und helft {name}'aka bei Flucht.", sourceObjective = "Sprecht mit Priesterin Thaalia und helft dem gefangenen Schmetterschwanzjungen aus Zul'Gurub zu fliehen.", completion = "Sehr schade, ja.\n\nDies ist der Wille der Geister, ja.\n\nWenn Ihr stärker seid, werdet Ihr vielleicht nach Zul'Gurub gehen und deine {name}'aka von Mandokir zurückholen, ja.\n\nDoch erst einmal gibt Euch Priesterin dies.", sourceObjectiveStatus = "unverified-source-field" }
quests[26776] = { id = 26776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghaliri", description = "Priesterin spricht Gemeinsprache nicht gut, nein.\n\nVielleicht redet besser mit Ghaliri, vor diesem Zelt.\n\nSagt ihm, was Ihr in Zul'Gurub gesehen, ja.", sourceObjective = "Kehrt zu Ghaliri in Fort Livingston im Nördlichen Schlingendorntal zurück.", completion = "<Ihr erklärt Ghaliri, was bisher geschehen ist.>\n\nAnscheinend hat Jin'do überlebt und ruft seine Brüder zusammen, um Hakkar noch einmal in diese Welt zu holen. Es war gut, dass Ihr zu mir gekommen seid.\n\nIm Moment können wir nur abwarten und beobachten. Jin'do ist schwach. Wir sollten ihn niederstrecken, aber ich muss Rastakhans Entscheidung abwarten, bevor ich den Befehl dazu geben kann. Bis dahin müsst Ihr und Euer Raptor ausharren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26777] = { id = 26777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beruhigt die Geister", description = "Dies ist ein tragisches Land mit einer Geschichte voller Gewalt und Verzweiflung. Viele Tote streifen in ihren Körpern durch das Land, aber manche sind nur verlorene Seelen, die verwirrt umherirren.\n\nSie verdienen Trost.\n\nViele dieser Seelen versammeln sich im Süden in Addles Siedlung und erscheinen Reisenden. Nehmt diesen Schwenker mit heiligem Weihrauch. Schwenkt ihn vor den verlorenen Seelen. Sein sanfter Duft wird ihnen Frieden bringen.", sourceObjective = "Beruhigt 5 verlorene Geister in Addles Siedlung.", completion = "Ihr habt denen Frieden gebracht, die nur Leid kannten, {name}. Seid stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26778] = { id = 26778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreie der Toten", description = "Könnt Ihr sie hören, {name}? Es sind so viele. Sie wandern an ihren Gräbern entlang, stolpern auf verwesenden Gliedmaßen über den kalten Boden.\n\nDie Toten schreien in der Stille. Sie leiden in ihrem eigenen Fleisch und wurden aus ihrem Schlaf gerissen! Jede Nacht gehe ich auf den Friedhof, um mehr von ihnen Frieden zu bringen, aber es sind nie genug.\n\nHelft mir, {name}. Erlöst die Ghule, die über den Friedhof von Rabenflucht ziehen, von ihrem Leid. Tötet so viele Ihr könnt.", sourceObjective = "Tötet 20 beliebige Ghule auf dem Friedhof von Rabenflucht.", completion = "Doch die Schreie sind nicht mehr so laut. Möge das Licht Euch segnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26779] = { id = 26779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mambo in Zul'Mamwe", description = "Das ganze Trollreich schämt sich für die Schädelspalter. Ihr lächerliches Gezanke mit den Blutskalpen hat das Nördliche Schlingendorntal entzweit. Während Stämme wie die Dunkelspeere und die Zandalari ein gutes Leben führen, kämpfen die Schädelspalter um Ruinen.\n\nMan hat mir erlaubt, Söldner zu belohnen, die gewillt sind, die Schädelspalter zu bestrafen. Ich fordere Euch und jeden, den Ihr kennt, auf, nach Zul'Mamwe im Osten zu reisen und diesen abtrünnigen Stamm zu vernichten.", sourceObjective = "Tötet 16 Schädelspaltertrolle im Inneren von Zul'Mamwe.", completion = "Hier ist, wie versprochen, Eure Belohnung.. Ihr erfüllt die Trollnation mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[26780] = { id = 26780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn es Nacht wird im Dschungel", description = "Die Nächte sind im Schlingendorntal besonders schön. Der Himmel ist voller Sterne und das Mondlicht dringt durch diese Blätter hier. Die ganze Nacht könnte ich den Himmel betrachten.\n\nLeider stören die Trolle in den Ruinen von Zul'Mamwe meine astronomischen Studien. Tag und Nacht brennen ihre Kohlenpfannen. Sie berauben mich der Dunkelheit, die ich brauche.\n\nBitte geht nach Zul'Mamwe östlich von hier, {name} und löscht sie.", sourceObjective = "Löscht 8 Kohlenpfannen von Zul'Mamwe in Zul'Mamwe im Nördlichen Schlingendorntal.", completion = "Ich sehe den Unterschied bereits deutlich. Ich kann die Nacht kaum erwarten. Dann kann ich endlich wieder meine Beobachtungen aufnehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26781] = { id = 26781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gedankenauge", description = "Einer der zahlreichen Schätze dieses Tals befindet sich ganz in der Nähe, auf UNSERER Seite des riesigen Wirbelstroms. Ein Ogermagier auf dem Ogerhügel der Mosh'Ogg, nordöstlich von hier, besitzt es. Sein Name ist Mai'Zoth. Ich habe gehört, er sei boshaft und seine Magie stark.\n\nWenn er das Gedankenauge besitzen sollte, wird seine Magie noch stärker sein.\n\nBisher ist es mir nicht gelungen, nahe genug an ihn heranzukommen, um es ihm abzunehmen. Würdet Ihr es versuchen?", sourceObjective = "Nehmt Mai'Zoth das Gedankenauge ab.", progress = "Habt Ihr das Auge?", completion = "Ihr habt das Auge geholt! Eure Macht ist der Stoff, aus dem Legenden sind, {name}!\n\nDabei dachten mein Bruder und meine Schwester, wir würden nichts wertvolles in diesem Tal finden. Hah! Und ich fange erst an!", sourceObjectiveStatus = "unverified-source-field" }
quests[26782] = { id = 26782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass <ein/eine:c> {class} dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?\n\nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh'Ogg im Nordosten entdeckt habe.\n\nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?", sourceObjective = "Erbeutet die Schatzkiste der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wieso finden ausgerechnet OGER immer wertvolle Artefakte?", completion = "<Wulfred wirft einen Blick in den Kasten.>\n\nDamit... damit hatte ich nicht gerechnet. Ich dachte, es wäre ein... ein... \n\n<Seine Augen werden glasig.>\n\nÄhem! Entschuldigt. Ich weiß nicht, was über mich gekommen ist. Ich schicke das nach Süden, zur Grabungsstätte der Forscherliga am Kap. Vielleicht wissen sie etwas damit anzufangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26783] = { id = 26783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatzkiste der Mosh'Ogg", description = "Es gibt Neuigkeiten aus dem Rebellenlager im Norden. Ich habe gerade von einem Soldaten namens Nimetz erfahren, dass <ein/eine:c> {class} dort oben entschlüsselt hat, was die anderen in den Wahnsinn getrieben hat. Das wart nicht zufällig Ihr, oder?\n\nWie dem auch sei, er hat mir eine Probe dieser Steine geschickt und sie sehen genauso aus wie die, die ich auf dem Ogerhügel der Mosh'Ogg im Nordosten entdeckt habe.\n\nSo wie ich gehört habe, bewachen die Oger eine Truhe in irgendwelchen Ruinen hinter ihrem Hügel. Ich vermute einen Zusammenhang. Würdet Ihr sie für mich holen?", sourceObjective = "Erbeutet die Schatzkiste der Mosh'Ogg aus den Ruinen hinter dem Ogerhügel der Mosh'Ogg.", progress = "Wieso finden ausgerechnet OGER immer wertvolle Artefakte?", completion = "<Wulfred wirft einen Blick in den Kasten.>\n\nDamit... damit hatte ich nicht gerechnet. Ich dachte, es wäre ein... ein... \n\n<Seine Augen werden glasig.>\n\nÄhem! Entschuldigt. Ich weiß nicht, was über mich gekommen ist. Ich schicke das nach Süden, zur Grabungsstäte der Forscherliga am Kap. Vielleicht wissen sie etwas damit anzufangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26784] = { id = 26784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammiges Wasser", description = "Die Elementarkräfte sind stark hier im Hochland, {name}. Deshalb hat der Schattenhammer hier seine Festung errichtet.\n\nIn den richtigen Händen kann diese Energie für etwas Produktives genutzt werden... zum Beispiel für ein Portal nach Orgrimmar.\n\nNordwestlich von hier, an der Mündung des Verralls sind Wasserelementare durch die Taten unserer Feinde flussaufwärts aufgeschreckt worden. Zerstört sie und sammelt 5 Strudelkerne. Ihr werdet nicht nur den Fluss beruhigen, sondern auch unser Portal mit Energie versorgen.", sourceObjective = "Tötet schlammige Wasserelementare und sammelt 5 Strudelkerne.", progress = "Ich hoffe, die Kämpfe im Fluss waren nicht allzu gefährlich.", completion = "Die sind genau richtig! Die unruhigen Wasser dieses aufgewühlten Flusses werden jetzt so viel mehr tun, als nur Schlick oder Stein zu bewegen ... Sie werden Euch von einem Kontinent zum anderen bewegen.\n\nErledigt Eure restlichen Geschäfte hier in Drachenmal. Dann sollten wir fortfahren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[26785] = { id = 26785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitglied der Meute", description = "Ich habe immer versucht, mein wahres Ich vor den Einwohnern Dunkelhains zu verbergen... Sie scheinen Worgen nicht zu mögen. Es gibt allerdings außerhalb der Stadt noch mehr von uns.\n\nMeine Begleiter, mit denen ich zuerst hier angereist bin, durchsuchen die Wälder nach wilden Worgen. Sie glauben, dass einige von ihnen - die mit den verräterischen Zeichen - wieder zur Vernunft gebracht werden können.\n\nIch bin noch nicht soweit, mich ihnen wieder anzuschließen. Bitte lasst Lehrling Fess an der Kreuzung westlich der Stadt wissen, dass ich noch eine Weile länger in Dunkelhain verweilen werde.", sourceObjective = "Sprecht mit Lehrling Fess an der Kreuzung westlich von Dunkelhain im Dämmerwald.", completion = "Tobias hält sich immer noch in der Stadt auf?\n\nMeister Harris hat ihn davor gewarnt, dem Schicksal seines Bruders weiter nachzugehen. Wir haben schließlich alle ein neues Leben angefangen. Aber es ist schwer, die Vergangenheit hinter sich zu lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[26786] = { id = 26786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Landungspunkt sichern", description = "Etwas bereitet mir Kopfzerbrechen, {name}. Die Zwielichtdrachen wussten genau, wo und wann sie unsere Luftflotte angreifen mussten. Man könnte glauben, dass sie unsere Pläne kennen.\n\nZwielichtspione verstecken sich mitten unter uns!\n\nIch werde mit einem der verbliebenen Schiffe nach Orgrimmar zurückkehren und dann werden Köpfe rollen. Ihr müsst hier bleiben. Ich brauche Euch hier, um diese Frontlinie zu sichern. Die Schamanen des Drachenmals sind mächtig. Ich habe sie darum gebeten, ein Portal nach Orgrimmar zu öffnen. Und ich brauche Eure Hilfe.\n\nAlso. Fangt an, zu helfen!", sourceObjective = "Sprecht mit Artesh im Hafen des Drachenmals im Schattenhochland.", completion = "Euer Kriegshäuptling ist entschlussfreudig, {name}. Er setzt Dinge in die Tat um. Ich mag ihn.\n\nLasst uns über das Portal sprechen, das er möchte!", sourceObjectiveStatus = "unverified-source-field" }
quests[26787] = { id = 26787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärendienst", description = "Ich habe Angst, dass ... nun ja, ich habe einfach nur Angst. Außerdem tut es mir leid, dass ich um einen weiteren Gefallen bitten muss.\n\nMeister Harris benötigt Gehirne. Bärengehirne. Offenbar sind sie Teil des Serums - oder ein gleichwertiger Ersatz.\n\nEs gibt viele Schwarzbären in den Wäldern im Westen und entlang des Flussufers, aber... Ich kann das nicht! Ich habe sogar mit einem Gewehr viel zu viel Angst, um dort hinauszugehen und diesen riesigen Ungeheuern gegenüberzutreten. Bitte, lasst mich Euch bezahlen, damit Ihr mir einige bringt!", sourceObjective = "Sammelt 8 Gehirne von Schwarzbären", progress = "Habt Ihr sie bekommen? Habt Ihr sie?", completion = "Danke! Oh, danke. Ich hätte nie gedacht, dass ich einmal so glücklich sein werde, diese Gehirne zu riechen. Jetzt, da ich sie nicht selber holen musste, bin ich es!\n\nHier ist Eure Belohnung, wie versprochen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26788] = { id = 26788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unseren Sieg untermauern", description = "Unsere Allianz mit dem Drachenmalklan ist unter Dach und Fach, aber dieser Hafen ist für Kämpfe immer noch ungeeignet. Diese hauchdünnen Holzwände sind des Kriegshäuptlings unwürdig.\n\nWenn Wasserelementare sich ihren Weg durch Gestein bahnen, wie sie es im Verrall getan haben, entsteht ein seltsamer Schlamm. Er lässt sich problemlos verstreichen und wenn er trocknet, ist er härter als der härteste Stein. Er ist der perfekte Mörtel für große Bauvorhaben.\n\nGeht zur Flussmündung nordwestlich von hier und sammelt Verrallschlamm ein. Selbst eine kleine Menge wird lange reichen.", sourceObjective = "Sammelt 10 Haufen Verrallschlamm.", progress = "Habt Ihr den Schlamm? Der Bau der neuen Wände hat bereits begonnen!", completion = "<Ornak lässt den Schlamm von seinen Fingerspitzen tropfen.>\n\nDas ist genau das richtige Zeug! Ich werde es sofort mit Kies und Wasser vermischen und verdünnen. Nur einige Handvoll hiervon können den Zement für einen ganzen Steinturm aufbessern.\n\nWir haben große Pläne für diesen Hafen, {name}, Ihr werdet schon sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26789] = { id = 26789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt im Walde", description = "{name}, wir haben ein Problem! Ich habe den Dämonenhund Magmadar auf dieser Lichtung aufgespürt, aber als wir uns ausruhten, hat eine Koboldbande unsere Kampfäxte gestohlen! Ihr müsst sie zurückholen, damit Magmadar uns nicht unvorbereitet erwischt! Beeilt Euch, er kann jeden Moment aufwachen!", sourceObjective = "Tötet 5 Test-Kobolde", sourceObjectiveStatus = "unverified-source-field" }
quests[26791] = { id = 26791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Pilze aus dem Boden", description = "Die Mystiker der Steintroggs erschaffen diese Fungusmissgeburten aus den Riesenpilzen im Norden.\n\nIch möchte, dass Ihr einen Kriegswächter mitnehmt, damit er Euch bei den Riesen und den Steintroggs hilft. Macht Euch auf den Weg zu den Riesenpilzen und zielt auf sie. Ich und meine Geomanten werden sie in Grund und Boden stampfen, noch bevor die Mystiker ihr Ritual vollenden.", sourceObjective = "Interagiert mit einem Kriegswächter und benutzt ihn, um 5 Riesenpilze zu vernichten.", completion = "Jetzt haben sie keine dieser Pilzriesen mehr, die sie gegen uns einsetzen könnten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26792] = { id = 26792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungusmissgeburten", description = "Schnappt Euch einen Kriegswächter und vernichtet die Fungusmissgeburten, während Ihr da draußen seid.", sourceObjective = "Tötet 5 Fungusmissgeburten.", completion = "Ich danke Euch, {name}. Vor der Zerstörung der Weltensäule kannten wir derartige Probleme in Tiefenheim nicht.\n\nEuer Irdener Ring muss den Schaden beseitigen, bevor es zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[26793] = { id = 26793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verwitterte Grab", description = "Auf dem Schild an dem verwitterten Grab steht nur:\n\nMORGAN LADIMORE\n\n<Bei genauerer Untersuchung bemerkt Ihr, dass die Erde auf dem Grab vor Kurzem aufgewühlt wurde. Ein großer Teil der Erde scheint verlagert worden zu sein...>", sourceObjective = "Sprecht mit Sirra Von'Indi in Dunkelhain.", completion = "Morgan Ladimore?\n\nAh, ja, natürlich. Das ist eine lange und traurige Geschichte. Ich kannte ihn, nun ja, bevor er in den Krieg zog. Damals sah ich ihn zum letzten Mal. Er war ein nobler und guter Mann, aber es nahm ein schlimmes Ende für ihn.\n\nMoment, ich müsste hier etwas haben, das Euch die Geschichte näher bringen kann als meine lückenhaften Erinnerungen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26794] = { id = 26794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgan Ladimore", description = "<Er durchsucht die Regale und zieht ein ledergebundenes Buch hervor.>\n\nWenn Ihr mehr wissen möchtet, solltet Ihr Althea fragen. Sie hat sich in letzter Zeit mit den... Ärgernissen, die ihn betreffen, beschäftigt.", sourceObjective = "Sprecht mit Kommandantin Althea Schwarzhaupt in Dunkelhain.", completion = "Morgan Ladimore? Nie gehört...\n\nOh, Ihr meint Mor'Ladim! Dann kennt Ihr die Geschichte wohl noch nicht.\n\nIch erzähle Euch die Kurzfassung. Ein mächtiges untotes Wesen, das sich Mor'Ladim nennt, ist im Dämmerwald gesehen worden. Soweit wir wissen, handelt es sich dabei um den untoten Körper von Morgan Ladimore, von dem Ihr anscheinend gehört habt. Er bereitet uns jede Menge Probleme, greift Wachen auf Patrouille an und bringt Leute um.\n\n<Sie mustert Euch.>\n\nIhr wirkt recht fähig, vielleicht könnt Ihr ihm ja Frieden bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26795] = { id = 26795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'Ladim", description = "Wie ich von meinen Spähern höre, irrt Mor'Ladim auf merkwürdig verschlungenen Pfaden durch den Dämmerwald. Sein Weg führt ihn dabei über den Friedhof. Wir haben ihn hinter dem Haus auf dem Hügel begraben. Wisst Ihr, wo das ist?\n\nIch kann leider nichts tun, um Euch zu helfen, aber ich wünsche Euch viel Glück.", sourceObjective = "Tötet Mor'Ladim und bringt seinen Schädel zu Kommandantin Althea Schwarzhaupt in Dunkelhain.", progress = "Ich mache Euch keinen Vorwurf, wenn Ihr Schwierigkeiten mit ihm habt, {name}. Einige unserer stärksten Behüter sind Mor'Ladim zum Opfer gefallen.", completion = "Ihr habt ihn getötet? Das ist eine großartige Leistung, {name}! Im Namen der Einwohner Dunkelhains und der Nachtwache, danke ich Euch.\n\nAh... da wäre allerdings noch eine Kleinigkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[26796] = { id = 26796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die überlebende Tochter", description = "Ich hätte Euch dies schon früher mitteilen müssen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", sourceObjective = "Sprecht mit Behüterin Sarah Ladimore in Dunkelhain.", completion = "Ja? Mein Vater...\n\n<Sie senkt den Blick.>\n\nIch wünschte... ich hätte etwas für ihn tun können... Hätte ich nur mit ihm gesprochen, bevor er...", sourceObjectiveStatus = "unverified-source-field" }
quests[26797] = { id = 26797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Liebe einer Tochter", description = "Hier, nehmt das und legt es auf sein Grab. Vielleicht... weiß er irgendwie, dass es mir gut geht und dass keiner von uns ihn dafür verantwortlich macht, was geschehen ist.\n\n<In ihren Augen stehen Tränen. Sie streift einen Ring von einem Finger der rechten Hand ab und drückt ihn Euch in die Hand.>\n\nUnd... danke, {name}.", sourceObjective = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", progress = "Lasst mich in Ruhe...", completion = "<Eine geisterhafte Stimme erklingt im Wind...>\n\nIst das...? Sarah? Kann es sein, dass sie noch lebt? Mir fällt ein Stein vom Herzen...\n\n{name}. Nehmt mein Schwert Archeus. Jetzt, da meine Seele sich zur Ruhe begibt, benötige ich es nicht länger. Es wurde geschmiedet, um Gutes zu tun. Ich habe mich unwürdig erwiesen, es zu führen. Doch vielleicht könnt Ihr das Licht damit weitertragen.\n\nLys, meine Geliebte...", sourceObjectiveStatus = "unverified-source-field" }
quests[26798] = { id = 26798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegshäuptling wird zufrieden sein", description = "Das Portal ist fertig!\n\nEs ist noch nicht stark genug, um eine ganze Armee zu transportieren, aber wir können die Verbindung lange genug aufrechterhalten, um wichtige Personen in beide Richtungen hindurchschreiten zu lassen.\n\nDer Kriegshäuptling will bestimmt über Eure Fortschritte hier informiert werden. Geht durch das Portal nach Orgrimmar und überbringt die Neuigkeiten Garrosh Höllschrei.", sourceObjective = "Benutzt das Portal im Hafen des Drachenmals, um nach Orgrimmar zu gelangen. Meldet Euch dort bei Garrosh Höllschrei.", completion = "{class}, Ihr seid von den Drachenmalorcs zurückgekehrt. Ich nehme also an, dass das Portal funktioniert? Gut.\n\nBevor Ihr wieder an Eure Arbeit dorthin zurückkehrt, gilt es, hier in Orgrimmar noch ein schmutziges Geschäft zu bereinigen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26799] = { id = 26799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nicht gerettet werden konnten", description = "Die Val'kyr erwecken jeden Tag hunderte von Leichen. Agatha hat Euch vor nur wenigen Momenten erweckt. Aber nicht alle haben Euer Glück.\n\nEinige behalten ihren freien Willen, leben aber in ewiger Angst und Verwirrung. Sie laufen normalerweise in die Wälder und schrecken vor ihrem eigenen Anblick zurück.\n\nAndere werden völlig wahnsinnig und ziehen ziellos umher. Sie werden oft gewalttätig und müssen zerstört werden.\n\nDas ist Eure Aufgabe, {name}. Zerstört sie, auch wenn sie einst unsere Brüder und Schwestern waren.", sourceObjective = "Tötet 6 hirnlose Zombies.", completion = "Nicht einmal die Macht der Val'kyr reichte aus, um diese Kreaturen zu retten. Sie waren von Anfang an verdammt.\n\nIch habe Euch etwas Ausrüstung besorgt, {name}. Es ist nicht viel, aber es wird helfen. Bitte, sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[26800] = { id = 26800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung", description = "Wir haben Leichen aus dem Silberwald, aus dem Hügelland... ach, von überall herbringen lassen, wo wir sie bekommen konnten. Wir können es uns jedoch nicht leisten, die Leichen zu ignorieren, die direkt vor unserer Tür liegen.\n\nDie letzten Überbleibsel des Scharlachroten Kreuzzuges treiben sich hier in Tirisfal herum. Wir haben sie zwar aus Todesend vertreiben können, aber mehrere ihrer Leichen liegen um die Gebäude im Norden und Osten herum.\n\nGeht und findet sie... und nehmt diesen Darnell mit. Er sieht stark genug aus, um ein paar Leichen tragen zu können.", sourceObjective = "Durchsucht Todesend und die Umgebung nach 6 Leichnamen der Scharlachroten, dann zeigt auf sie, damit Darnell sie einsammelt.", completion = "Gute Arbeit, {name}, ich wusste, dass Ihr nicht völlig nutzlos seid. Hier, nehmt Euch etwas hiervon. Wir Todeswachen haben solches Zeug stapelweise herumliegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26801] = { id = 26801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel an unseren Grenzen", description = "Wenn Ihr den Verlassenen nützlich sein wollt, müsst Ihr lernen, wie man kämpft. Und es gibt keine besseren Ziele als die Geißeldiener, die uns immer noch belästigen.\n\nDie elenden Ghule und klappernden Skelette, die im Norden und Osten herumlaufen, sind ehemalige Kämpfer der gefallenen Geißel. <Ein neuer/Eine neue:c> {class} wie Ihr sollte dieser Herausforderung gewachsen sein.\n\nTrödelt nicht herum – sprecht erneut mit mir, wenn Ihr fertig seid.", sourceObjective = "Tötet 8 Untote außerhalb von Todesend. Ihr könnt sowohl elende Ghule als auch klappernde Skelette töten.", completion = "Eure Stärke wächst, {name}. Ich habe solche wie Euch schon gesehen. Ihr werdet Todesend verlassen und Größeres in Angriff nehmen, ehe Ihr Euch verseht. Vergesst nur nicht, wo Ihr einmal angefangen habt.\n \nEs liegt noch viel Arbeit vor Euch, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26802] = { id = 26802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verdammten", description = "Zuerst... schaut mal Eure Rüstung an. Ihr seht ganz zerlumpt aus, {class}.\n\nWenn Ihr in einem Stück bleiben wollt - und das wollt Ihr ganz sicher - kann ich vielleicht helfen. Wenn Ihr mir Pfoten und Flügel von den Wölfen und Fledermäusen in der Nähe bringt, finde ich Euch vielleicht etwas Rüstung. Ihr findet diese Kreaturen nördlich und westlich von hier.", sourceObjective = "Besorgt 4 Aasfressertatzen und 4 Nachtsaugerflügel.", progress = "Bemüht Euch, unverletzt zu bleiben, bis ich Euch irgendeine Rüstung besorgt habe.", completion = "Danke, {name}. Diese Rüstung sollte Euch etwas helfen.\n\nHoffentlich hilft sie Euch mehr als ihrem letzten Träger...", sourceObjectiveStatus = "unverified-source-field" }
quests[26803] = { id = 26803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Berichte", description = "Garrosh ist ungehobelt und spricht kaum ein Wort, aber er meint es gut. Bald wird er erkennen, welch wertvoller Verbündeter Euer Volk ist.\n\nIch warte auf Berichte zu den letzten Regungen der Allianz in Durotar, aber sie sind noch nicht eingetroffen. Würdet Ihr für mich nach Klingenhügel reisen und persönlich darum bitten? Am einfachsten gelangt Ihr mit einem Windreiter dorthin. Für eine kleine Gebühr leiht Doras, der Windreitermeister in Orgrimmar, Euch einen seiner Windreiter. Ihr findet ihn auf der Anhöhe nördlich des Tals der Stärke.", sourceObjective = "Sprecht mit Windreitermeister Doras in Orgrimmar.", completion = "Ihr müsst also schnell nach Klingenhügel? Kein Problem. Einer meiner Windreiter kann Euch im Handumdrehen dorthin bringen. Die Leihgebühr beträgt nur ein paar Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26804] = { id = 26804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Klingenhügel", description = "Wenn Ihr bereit seid, einen Windreiter nach Klingenhügel zu nehmen, sprecht mich einfach erneut an. Verschwendet keine Zeit, wenn Ihr angekommen seid, und meldet Euch sofort bei Gar'Thok. Er ist für die Berichte zu den aktuellen Aktivitäten der Allianz in Durotar verantwortlich.", sourceObjective = "Sprecht mit Doras, um einen Windreiterflug nach Klingenhügel zu erwerben. Sobald Ihr angekommen seid, sprecht mit Gar'Thok.", completion = "Etrigg hat Euch geschickt? Der Kriegshäuptling muss ja auf meine Berichte brennen! Ich hätte sie ihm schon lange geschickt, aber wir decken jeden Tag neue Einmarschpläne der Allianz in Durotar auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[26805] = { id = 26805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Kap!", description = "Die Forscherliga entwickelt sich ständig weiter, {name}. Sie haben nicht nur Worgen wie mich aufgenommen, sondern sie haben auch ihre Suche nach Artefakten ausgeweitet. Einer unserer Besten, Bronwyn Hackschlag, hat im Süden ein Lager aufgeschlagen. Er glaubt, dass dort ein Gegenstand verborgen liegt, der von den Titanen stammt.\n\nBronwyn hat mich darum gebeten, einige Aufgaben hier im Norden zu übernehmen. Eine dieser Aufgaben ist es, mögliche Rekruten zu finden. Ihr scheint aus dem richtigen Holz geschnitzt zu sein. Sprecht mit Robert Rhodes, dem Flugmeister. Er wird dafür sorgen, dass Ihr dorthin gelangt. Auf Bronwyns Kosten.", sourceObjective = "Sprecht mit Robert Rhodes, um einen Flug zu der Grabungsstätte der Forscherliga am Schlingendornkap zu bekommen.", completion = "Wulfred hat einen guten Blick. Ihr werdet hier in meinem Lager schon zurechtkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26806] = { id = 26806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichte für Orgrimmar", description = "Etrigg muss sich mit dem Teil des Berichts zufriedengeben, den ich schon fertig habe. Sagt ihm, dass ich bald noch mehr schicke.\n\n<Gar'Thok reicht Euch einen Stapel unordentlich gefalteter Papiere.>\n\nDie hier sollten eigentlich die wichtigsten Details zum Anstieg der Allianztruppen in Nordwacht enthalten. Bitte sagt Etrigg, dass es mir leid tut und lasst ihn wissen, dass wir hier alle Hände voll zu tun hatten. Schließlich mussten wir Klingenhügel sichern. Wenn Ihr bereit seid, nach Orgrimmar zurückzukehren, sprecht einfach mit Burok und leiht Euch einen Windreiter.", sourceObjective = "Bringt Gar'Thoks Berichte zu Burok in Klingenhügel.", progress = "Seid Ihr bereit, nach Orgrimmar zurückzukehren?", completion = "Seid Ihr bereit, mit diesen Berichten nach Orgrimmar zurückzukehren? Ich kann sofort einen Flug für Euch arrangieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[26807] = { id = 26807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Etrigg", description = "Da Ihr bereits mit Doras gesprochen habt, könnt Ihr einen Windreiter für den Rückflug nach Orgrimmar mieten. Jedes Mal, wenn Ihr in einer neuen Stadt ankommt, solltet Ihr Euch mit dem ansässigen Flugmeister unterhalten. Danach könnt Ihr seine Dienste in Anspruch nehmen, um weite Strecken schnell zurückzulegen.\n\nSprecht erneut mit mir, wenn Ihr bereit seid, einen Rückflug nach Orgrimmar zu erwerben. Bringt diese Berichte zu Etrigg im Tal der Stärke, sobald Ihr gelandet seid.", sourceObjective = "Sprecht mit Burok und erwerbt einen Flug zurück nach Orgrimmar. Sobald Ihr gelandet seid, bringt Gar'thoks Berichte zu Etrigg im Tal der Stärke.", progress = "Habt Ihr diese Berichte schon abgeliefert?", completion = "<Etrigg betrachtet die Berichte aufmerksam.>\n\nDie Allianz ist anmaßender, als wir dachten! Ich spreche sofort mit dem Kriegshäuptling wegen Verstärkung. Vielen Dank, dass Ihr mir diese Berichte so schnell gebracht habt. Ich hoffe, dass dieser Betrag ausreicht, um Eure Reiskosten zu decken.", sourceObjectiveStatus = "unverified-source-field" }
quests[26808] = { id = 26808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maywiki", description = "<Linzi sieht besorgt aus.>\n\nWisst Ihr, hinter dem Kistenstapel verbirgt sich ein Troll. Sie muss furchtbar traurig sein, wenn sie nicht herauskommen und mit niemand reden will.\n\n<Linzi legt einige Akirisschilfrohre in ein Halstuch und bindet sie zusammen.>\n\nHier, gebt sie ihr. Sie sind sehr weich. Vielleicht ist es damit dort hinten ein wenig gemütlicher für sie.", sourceObjective = "Bringt Linzis Geschenk zu Maywiki von Zuldazar, die sich an der Grabungsstätte der Forscherliga befindet.", progress = "Was soll das, {class}?", completion = "<Die Trollfrau schaut in das Paket.>\n\nIch danke Euch. Ihr könnt Eurem Zwergenfreund sagen, dass ich nicht traurig bin. Ich warte. Auf Euch.\n\nIch habe festgestellt, dass Ihr der vielversprechendste {race} in dieser seltsamen Stadt seid. Ich habe eine Aufgabe für Euch, falls Ihr sie annehmen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[26809] = { id = 26809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Hintertür", description = "Ich verfolge einen Vertriebenen der Gurubashi. Er heißt Zanzil der Ausgestoßene. Vor Kurzem berichteten meine Brüder aus dem Norden mir, dass er plant, sich wieder in die Gesellschaft einzugliedern. Sein erster Schritt war, einen Abgesandten zu den Schädelspaltern zu schicken. Das sind keine guten Nachrichten.\n\nIch möchte, dass Ihr versucht, Einblick in Zanzils neueste Pläne zu erhalten. Nehmt diesen Weihrauch und stellt ihn vor das Fledermaustotem in den Ruinen von Jubuwal, die sich nördlich von hier befinden. Dann wird Hir'eek Euch führen.", sourceObjective = "Legt den Weihrauch der Gurubashi vor das Totem von Hir'eek und lauscht dann Zanzils Verschwörung.", completion = "Das hatte ich vermutet. Zanzil ist zu überheblich, um sich in die Streitigkeiten zwischen den Blutskalpen und den Schädelspaltern einzumischen. Nein, er ist Teil eines größeren Komplotts ... Jin'do der Verhexer benutzt ihn, um mit seiner Hilfe Hakkar zurück nach Zul'Gurub zu holen.\n\nGut, dass wir das jetzt herausgefunden haben, denn noch gibt es dafür eine einfache Lösung ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26810] = { id = 26810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beseitigt den Ausgestoßenen", description = "Ihr müsst Zanzil töten. Ihr seid auf Hir'eeks Schwingen geritten und habt durch Hir'eeks Augen gesehen; Ihr wisst, wo Zanzil sich in den Ruinen von Aboraz versteckt hält. Begebt Euch dorthin und tötet ihn.\n\nOh, und {race} ... Falls wir getrennt werden, solltet Ihr diesen Fetisch benutzen. Er funktioniert nur innerhalb von Schlingendorn, aber er wird Euch schnell zu mir zurückbringen, falls es notwendig sein sollte.\n\nViel Glück, {race}. Zanzil ist kein gewöhnlicher Gegner.", sourceObjective = "Begebt Euch zu den Ruinen von Aboraz am Schlingendornkap und nehmt Euch Zanzil den Ausgestoßenen vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[26811] = { id = 26811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Trollloch", description = "Es sieht so aus, als ob Zanzils Portal nach Zul'Gurub immer noch offen ist. Zul'Gurub ist ein gefährlicher Ort, aber Maywiki hat Euch mit dieser Aufgabe betraut.\n\nDas Portal liegt einladend vor Euch und wartet.", sourceObjective = "Benutzt Zanzils Portal und betretet Zul'Gurub.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26812] = { id = 26812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriesterin Jeklik", description = "Vor Euch ragt eine Rampe auf, die zu einer der vielen Terrassen der Stadt führt. Vor Euch befinden sich Totems, die wie Fledermäuse aussehen. Sie deuten an, dass Ihr Euch in der Hochburg der Hohepriesterin Jeklik befindet, einer Anhängerin von Hir'eek.\n\nJeklik betete Hakkar an und ist eine der Priesterinnen, die Zanzil wiederbeleben will. Wenn Ihr Euch beeilt, könnt Ihr die Wiederbelebung vielleicht verhindern.", sourceObjective = "Zerstört den Leib von Hohepriesterin Jeklik, bevor Zanzil sie wiederbeleben kann.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26813] = { id = 26813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hals über Kopf nach Zul'Gurub", description = "Zanzil der Ausgestoßene ist erneut durch eines seiner Portale geflohen. Folgt ihm!", sourceObjective = "Benutzt Zanzils Portal.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", sourceObjectiveStatus = "unverified-source-field" }
quests[26814] = { id = 26814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hohepriester Venoxis", description = "Venoxis war der Zweite der beiden Priester, die Zanzil von den Toten erwecken wollte. Es ist Euch bereits gelungen, Hohepriesterin Jekliks Leiche zu vernichten... Venoxis muss der Nächste sein.", sourceObjective = "Kümmert Euch um Zanzil den Ausgestoßenen und Hohepriester Venoxis.\n\nWenn Ihr Euch verirrt oder nach Zul'Gurub zurückkehren müsst, sprecht mit Maywiki an der Grabungsstätte der Forscherliga.", completion = "Ich bitte Euch, Zanzil den Ausgestoßenen zu töten, einen kleinen, isolierten Vertriebenen der Gurubashi - und was tut Ihr? Stürzt Euch Hals über Kopf in die Hauptstadt der Gurubashi und eliminiert einen ihrer Hohepriester! Beinahe sogar zwei! Es gibt nur ein Wort, um ein derartig tollkühnes und verwegenes Unterfangen zu beschreiben:\n\nHeldentum.\n\nJin'do der Verhexer wandelt immer noch in den Mauern von Zul'Gurub, aber er hat ein Bein verloren, als Ihr Jeklik zerschmettert habt. Den heutigen Kampf haben wir für uns entschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[26815] = { id = 26815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zanzils Geheimnis", description = "Vor vielen Jahren haben die Gurubashi einen der Ihren aus Zul'Gurub verbannt: einen Troll namens Zanzil. Die Gründe dafür sind nicht ganz klar. Ich vermute aber, es hatte etwas damit zu tun, dass er gerne jedem, der ihm über den Weg lief, starke, verhaltensändernde Mittel verabreichte. Die Gurubashi Priester und ihr Blutgott wurden vernichtet, aber Zanzil der Ausgestoßene existiert immer noch...\n\n... ebenso wie sein starkes, verhaltensänderndes Mittel.\n\nIch benötige diese Mixtur für meinen nächsten Test. Sucht bei den Zombies im Norden.", sourceObjective = "Beschafft 5 Phiolen mit Zanzils Mixtur.", progress = "Ausgezeichnet ... Ihr seid noch kein Zombie. Das ist gut.\n\nOh, ääh ... nichts. Es ist nur ... das war ein mögliches Risiko. Habe ich vergessen, Euch zu warnen?", completion = "<Dask analysiert sorgfältig die seltsame, chemische Verbindung.>\n\nDiese Mixtur ist... PERFEKT! Wollen wir doch mal sehen, was sie mit Eurem Artefakt, das möglicherweise titanischen Ursprungs ist, anstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26816] = { id = 26816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zutaten für eine Katastrophe", description = "Habt Ihr die Explosion gesehen, die ich verursacht habe? Ich muss 10 Zoll in die Höhe geflogen sein!\n\nJetzt muss ich nur noch an Zanzils Rezept kommen, damit ich herausfinden kann, warum das passiert ist. Einer von Zanzils Lakaien in den Ruinen von Aboraz muss es bei sich haben. Begebt Euch nach Osten, zu der Küste des Kaps, und ergattert es für mich!", sourceObjective = "Beschafft Zanzils Rezeptur von einem seiner Anhänger in den Ruinen von Aboraz.", progress = "Hat er Schimmerkraut verwendet? Ich schätze, er hat Schimmerkraut verwendet.\n\nNein, wartet ...Bernsteinsamen! Es muss sich um Bernsteinsamen handeln.", completion = "Das ist faszinierend! Denkt doch nur an all die Anwendungsmöglichkeiten!\n\nNochmals, vielen Dank, {name}. Denkt daran, wenn Ihr jemals etwas zusammengemischt haben möchtet ... GANZ GLEICH worum es sich handelt ... Dem Kolben vertraut - mit Eurem Kraut!", sourceObjectiveStatus = "unverified-source-field" }
quests[26817] = { id = 26817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reinheitsgebot", description = "Diese Körperflüssigkeit allein wird nicht reichen. Sie ist zu dickflüssig. VIEL zu dickflüssig.\n\nDie Naga im Westen behüten einen Schrein, aus dem das einzig klare Wasser diesseits vom Dämmerwald fließt. Für die meisten Tränke verwende ich Flusswasser, aber Bronwyn verlangt Präzision!\n\nBeschafft Wasser aus dem Nek'maniquellbrunnen, der sich an dem höchsten Punkt des Nagalagers befindet. Viel Glück.", sourceObjective = "Beschafft das heilige Wasser der Klarheit aus dem Nek'maniquellbrunnen am Schlingendornkap.", progress = "<Dask betrachtet gespannt Euer Bündel, als Ihr Euch nähert.>", completion = "Wisst Ihr, wie schwer es ist, hier am Schlingendornkap frisches Wasser zu bekommen? Kein Wunder, dass die Naga ihren Schrein so erbittert verteidigen.\n\nNun gut, lasst uns mit der Mixtur beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[26818] = { id = 26818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plüschpelze", description = "Hallo, ich bin die Händlerin der Stadt! Und Bronwyn ist mein Vater!\n\nTut mir leid, ich sollte nicht so aufgeregt sein. Mein Vater sagt, das ist nicht professionell.\n\nWie auch immer ... Die Leute kommen immer zu mir und fragen mich nach schwerem Leder oder rauem Balg. Doch ich glaube, es würde ihnen gefallen, wenn ich auch einige weiche Materialien hätte ... wie Tigerfell! Glaubt Ihr, Ihr könntet mir welches besorgen?\n\nIhr findet einige Panther hier in der Nähe, aber wenn Ihr die großen Tiger sucht, müsst Ihr Richtung Nordwesten gehen. Sie sind nördlich des großen Trollgebiets.", sourceObjective = "Beschafft 4 geschmeidige Tigerinnenfelle und 4 samtige Pantherfelle.", progress = "Oooh... Ich hoffe, sie sind weich!", completion = "<Linzi prüft die Felle und lächelt.>\n\nDie sind so schön und angenehm! Ich glaube, meine Kunden werden sie LIEBEN!", sourceObjectiveStatus = "unverified-source-field" }
quests[26819] = { id = 26819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bündelweise Akiris", description = "Die Forscher der Naga, die sich westlich von hier befinden, haben ein wertvolles Ozeanschilf bei sich: Akirisschilfrohr. Händler stellen daraus Arzneien und Verpackungen her; Handwerker füttern Rüstungen oder umwickeln Zigarren damit.\n\nWenn wir mit dem Graben fertig waren, hat mein Vater mir abends gezeigt, wie man es verwendet. Leider haben wir keins mehr. Würde es Euch etwas ausmachen, uns noch mehr davon zu holen?", sourceObjective = "Beschafft 6 Bündel Akirisschilfrohr von den Forschern der Naga.", progress = "Willkommen zurück!", completion = "Hurra! Es ist schon viele Tage her, dass wir Akirisschilfrohr hatten!", sourceObjectiveStatus = "unverified-source-field" }
quests[26820] = { id = 26820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn sie sie einfach herumliegen lassen ...", description = "Vater sagt, dass ein verantwortungsvoller Händler immer nach lohnenden Geschäften Ausschau hält. Ich versuche, auf Schritt und Tritt nach guten Geschäften Ausschau zu halten, und ich glaube, jetzt habe ich eins gefunden!\n\nDie Naga, die sich westlich von hier befinden, haben Dutzende Statuen, die sie dort, wo sie leben, überall auf den Boden stellen. Sie können unmöglich alle gebrauchen - also dachte ich, dass wir ein paar für uns nehmen!\n\nStatuen, ganz umsonst! Das ist doch ein gutes Geschäft, oder nicht?", sourceObjective = "Beschafft 6 Nagaikonen von der Südlichen Ungezähmten Küste am Schlingendornkap.", progress = "Lasst mal sehen!", completion = "Diese Statuen sind wunderschön...\n\nWow, ich wusste gar nicht, dass die Naga so talentiert sind. Danke, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26821] = { id = 26821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airwyn Bantamflax", description = "Nun, wir haben keine Ahnung, was dieses Artefakt ist. Es ist alt, älter als der Staub ... aber nicht titanischen Ursprungs. Ich bin absolut sprachlos.\n\nAirwyn Bantamflax in Beutebucht ist meine direkte Vorgesetzte. Als nächstes sollten wir sie über diesen Fund informieren. Würdet Ihr ihn bitte zu ihr bringen?", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Airwyn Bantamflax in Beutebucht am Schlingendornkap.", progress = "Ja, {race}? Ich bin sehr beschäftigt.", completion = "Faszinierend!\n\nIch brauche etwas Zeit, um mir das genauer anzusehen. Warum seht Ihr Euch nicht ein wenig in Beutebucht um und kommt später wieder?", sourceObjectiveStatus = "unverified-source-field" }
quests[26822] = { id = 26822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichtsnutzige, züngelnde Kriecher", description = "Ahem! Hrm, hrm ...\n\n<Der Zwerg räuspert sich einige Sekunden lang.>\n\nIhr sucht nach einer Beschäftigung? Und da kommt Ihr zu MIR? Dem kleinen, alten Goris?!\n\nNun, äh ... das ist das erste Mal. Ah, ich hab's!\n\nDas Tal im Norden ist voll nutzloser Basilisken, die nur ihre Wampe auf dem Boden schleifen. Sie sind zu rein gar nichts nutze und man sagt, sie hätten einmal jemand in Stein verwandelt.\n\nWenn Ihr sie tötet, gebe ich Euch etwas von meinem Zeug.", sourceObjective = "Tötet 12 Donnerschwanz- oder Eisenkieferbasilisken.", completion = "Ahem! Aaah... richtig... \n\nGut gemacht! Meinen Glückwunsch, dass Ihr sie getötet habt, meine ich.\n\nHier, bitte, für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[26823] = { id = 26823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Mund zu voll genommen", description = "Was immer Ihr tun wollt: Ich habe genau das richtige Rezept dafür. Ihr wollt einen Sprengstofftrank? BUMM!! Ihr wollt einen Blitztrank? BRITZEL!! Ihr wollt einen Schrumpftrank? Flupp!\n\nAlso Bronwyn sagt, er will einen Kohlenstoffdatierungstrank? Nichts leichter als das. Den könnte ich im Schlaf machen. Das Problem ist... wenn wir wollen, dass er präzise funktioniert, dann brauche ich einige hochwertige Zutaten.\n\nFangen wir mit ein wenig Körperflüssigkeit von einem Basilisken im Norden an. Es muss ein ziemlich großer Basilisk sein...", sourceObjective = "Beschafft eine Phiole mit Eisenkieferkörperflüssigkeit vom Eisenkieferungetüm in der Kristalladermine.", progress = "Soll ich's mischen... wird es zischen.", completion = "Also gut! Schritt eins - Zutaten besorgen - erledigt. Zeit für den nächsten Schritt: noch mehr Zutaten besorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26824] = { id = 26824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ergebnisse: Nicht eindeutig", description = "Ich habe getan, was ich konnte, {name}. Ich hatte die richtigen Tränke... Ich hatte die richtigen Rezepte... Aber der Ursprung dieser Probe entzieht sich meiner Kenntnis. Sie ist zehntausende Jahre alt, aber wir haben bewiesen, dass sie nicht titanischen Ursprungs ist. Und ein Blick genügt, um festzustellen, dass es nicht Saronit ist. Also... um was in Branns Namen handelt es sich?\n\nSagt Bronwyn, dass ich mein Bestes gegeben habe. Tut mir leid.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Bronwyn im Lager der Forscherliga am Schlingendornkap zurück.", progress = "Ich habe Rauch gesehen. Ist alles in Ordnung?", completion = "Ich wusste, dass dieser Alchemist nur eine große Klappe hat. Nun, danke für Eure Hilfe, {name}. Ich weiß, dass Ihr es versucht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26825] = { id = 26825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"Der Kolben\" Fusselmaul", description = "Hey, Ihr müsst <der Bursche/das Mädchen> sein, von dem Wulfred gesprochen hat. Ihr habt das Ogerartefakt gefunden und ihm geholfen, diese merkwürdigen Steine aus dem Norden zu testen. Willkommen an der Grabungsstätte, {name}!\n\nWir waren gerade dabei, diese Proben zu bestimmen, als Ihr hier angekommen seid. Würde es Euch etwas ausmachen, eine Probe zu Dask zu bringen? Er muss mir helfen, herauszufinden, wie alt sie ist.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Dask \"Der Kolben\" Fusselmaul in der Grabungsstätte der Forscherliga am Schlingendornkap.", progress = "Ihr habt etwas, das ich zusammenmischen soll?", completion = "Also bleibt es wieder einmal an dem kleinen Dask hängen, die Arbeit der Forscherliga zu erledigen! Also gut... Schauen wir einmal, was Ihr da habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26826] = { id = 26826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dask \"Der Kolben\" Fusselmaul", description = "Hey, Ihr müsst <der Bursche/das Mädchen> sein, von dem Wulfred gesprochen hat. Willkommen an der Grabungsstätte, {name}.\n\nWir wollten gerade ein neues Projekt beginnen, als Ihr eingetroffen seid. Würde es Euch etwas ausmachen, diese Probe zu Dask zu bringen? Er muss mir helfen, herauszufinden, wie alt sie ist.", sourceObjective = "Bringt die geöffnete Schatzkiste der Mosh'Ogg zu Dask \"Der Kolben\" Fusselmaul in der Grabungsstätte der Forscherliga am Schlingendornkap.", progress = "Ihr habt etwas, das ich zusammenmischen soll?", completion = "Also bleibt es wieder einmal an dem kleinen Dask hängen, die Arbeit der Forscherliga zu erledigen! Also gut... Schauen wir einmal, was Ihr da habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26827] = { id = 26827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Irdenen Ring zusammenrufen", description = "Wir müssen den Irdenen Ring für diesen Kampf zusammenrufen. Unsere zahlenmäßige Unterlegenheit gleichen wir durch unsere Stärke aus.\n\nGeht zum Tempel und versammelt die ruhenden Schamanen aus den hinteren Räumen. Norsala, Lorvarius und ich treffen uns mit ihnen an Lorthunas Tor.", sourceObjective = "Versammelt 5 Schamanen im hinteren Teil des Tempels der Erde und sprecht dann mit Maruut Steinbinder.", completion = "Was Ihr getan habt, hätte ich nicht für möglich gehalten. Ziemlich beeindruckend, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26828] = { id = 26828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Teil der Vereinbarung", description = "Leider muss ich hierbleiben und auf den Riss aufpassen, also müsst Ihr ohne mich kämpfen. Geht jetzt zu Therazane und schließt Euch wie versprochen dem Kampf an. Ihr solltet Sie am Halcyonaufstieg nördlich von Lorthunas Tor und östlich des Geschliffenen Schlunds vorfinden.\n\nWenn unser Teil der Abmachung erfüllt ist, bringt das letzte Stück der Weltensäule so schnell wie möglich hierher.", sourceObjective = "Sprecht mit Therazane auf dem Halcyonaufstieg.", completion = "Ihr seid also gekommen, Fleischling. Wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26829] = { id = 26829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinmarsch", description = "Meine Streitkräfte haben den Angriff bereits begonnen. Schließt Euch ihnen an. Vergießt das Blut dieser Kultisten, damit ich spüren kann, wie sie leiden.", sourceObjective = "Tötet 15 Kultisten des Zwielichthangs.", completion = "Ihr Blut auf dem Boden ist berauschend. Ich werde jeden Augenblick genießen und die Nachzügler langsam in meinem Reich auslöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26830] = { id = 26830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köder für den Verräter", description = "Ich habe meine Suche nach den Agenten des Schattenhammers, die hier in Orgrimmar herumlungern, noch nicht aufgegeben. Ich brauche jemanden, dem ich vertrauen kann, um den letzten Beweis für den Verrat zu finden.\n\n<Höllschrei nimmt Euch zur Seite.>\n\nSauranok der Mystiker - mein Vertrauter und Berater! - steht unter Verdacht. Deckt die Wahrheit auf, {name}, und Ihr werdet belohnt werden.\n\nWie ich höre, hat der Schattenhammer die Arbeiter an den Luftschiffdocks unterwandert, um seine Lügen über den gesamten Kontinent zu verbreiten. Befragt sie. Solltet Ihr herausfinden, dass Sauranok schuldig ist... Tötet ihn!", sourceObjective = "Befragt Peons des Himmelpfads von Orgrimmar in der Nähe des Zeppelinturms. Haltet Ausschau nach verdächtigen Peons. Versucht, Sauranok den Mystiker aufzuscheuchen und tötet ihn.", progress = "Schön, dass Ihr noch am Leben seid, {class}. Wie steht's mit Euren Nachforschungen?", completion = "Sauranok, Sauranok! Seine eigenen Visionen haben gegen ihn gearbeitet. Der Schattenhammer hat ihn wahrscheinlich aus der Ferne bestochen. Bah! Schwächling! Wir werden seinen Namen nie wieder aussprechen.\n\nIch sagte ihm, dass Ihr an den Luftschiffdocks Nachforschungen anstellt, {name}, um ihn aus der Reserve zu locken. Ja, ich habe Euch als Köder benutzt. Ihr habt Eurer Horde gut gedient und verdient eine Belohnung, weil Ihr diese Schlange in unserer Mitte enttarnt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[26831] = { id = 26831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug ins Zwielicht", description = "Terrath braucht Euch auf der anderen Seite des Abgrunds, um Zoltrik Drachenbann zu bekämpfen. Er ist ebenfalls unterwegs, aber er fürchtet, Zoltrik wird sich in die Luft erheben.\n\nWie es scheint, habt Ihr ziemlichen Eindruck hinterlassen, Kleinling. Ist Euch jemals der Gedanke gekommen, dass all dies nie geschehen wäre, wenn ich bei unserem ersten Zusammentreffen auf Euch getreten wäre? Das Schicksal geht seltsame Wege.", sourceObjective = "Besiegt Zoltrik Drachenbann.", progress = "Es ist gut, Euch wieder auf dem Schlachtfeld zu sehen.", completion = "Es war gut, dass Ihr zur Stelle wart. Merkwürdigerweise ist meine Größe durchaus hinderlich, wenn es darum geht, einen Drachen zu reiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26832] = { id = 26832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therazanes Gnade", description = "Der Schattenhammer hat zwei Führungspersönlichkeiten, die getötet werden müssen.\n\nDie eine ist ein Mensch namens Boldrich. Er ist klein, so wie Ihr. Aber dennoch gefährlich, ebenfalls so wie Ihr.\n\nDie andere ist eine Priesterin namens Lorthuna. Sie ist gerissen und nur schwer in die Enge zu treiben. Schlagt schnell zu und lasst sie nicht entkommen, sonst werdet Ihr es später bereuen - das verspreche ich Euch.", sourceObjective = "Besiegt Boldrich Steinreißer und Hohepriesterin Lorthuna.", completion = "Ihr habt Lorthuna entwischen lassen? Ich habe Euch davor gewarnt.\n\nDennoch, ihre Streitkräfte sind zerschlagen und ihr Nachschub ist abgeschnitten. Sie können mir oder meinen Verbündeten nicht mehr viel Schaden zufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26833] = { id = 26833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Stein gemeißelt", description = "Ihr habt getan, worum ich Euch gebeten habe, {race}. Ich werde zu meinem Wort stehen. Gorsik wird Euch mit unserem Stück der Weltensäule am Tempel treffen.\n\nBeendet Euer Ritual und schließt den Riss. Wenn Ihr das getan habt, sagt Eurem Irdenen Ring, er möge diesen Ort verlassen. \n\nIhr allerdings... Ihr dürft noch eine Weile bleiben, wenn Ihr möchtet. Das habt Ihr Euch verdient.", sourceObjective = "Sprecht mit Maruut Steinbinder am Tempel der Erde.", completion = "Gorsik ist eingetroffen. Dank Euch sind nun alle Teile der Weltensäule hier.\n\nWas Ihr für uns getan habt, ist von unermesslichem Wert. Diese letzten Momente werden entscheidend sein. Es fällt mir schwer, noch mehr von Euch zu verlangen, aber ich möchte, dass Ihr es bis zum Ende gemeinsam mit uns durchsteht.\n\nEure Angriffe haben den Schattenhammer zwar niedergeworfen, aber nicht vernichtet. Wir gehen davon aus, dass sie versuchen werden, uns von der Vollendung des Rituals abzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[26834] = { id = 26834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in den Abgrund", description = "Tief in der Nadelfelsschlucht lassen die Mystiker all diese Fungusmissgeburten sprießen. Ich habe Schiefer Treibsand und eine kleine Truppe hingeschickt, damit sie sich darum kümmern, aber sie sind auf Schwierigkeiten gestoßen.\n\nErinnert Ihr Euch noch an den Erzgeomanten? Würdet Ihr im Nordosten hinunterfliegen und ihm behilflich sein?", sourceObjective = "Sprecht mit Schiefer Treibsand in der Nadelfelsschlucht in Tiefenheim.", completion = "Schön, Euch wiederzusehen, {name}. Jetzt werden wir weiterkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26835] = { id = 26835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleines Problem", description = "Während Ihr dort draußen wart, hat sich Pyrium Leitstein mit mir in Verbindung gesetzt. Er meinte, dass es eine Angelegenheit höchster Dringlichkeit gäbe und dass man umgehend Eure Unterstützung bräuchte. Kehrt zum Eingang am Nadelfelsbruch im Südwesten zurück.\n\nIch wünsche Euch viel Glück bei der Rettung des Steinvaters und der Bergung des zweiten Fragments.", sourceObjective = "Kehrt zu Pyrium Leitstein im Nadelfelsbruch in Tiefenheim zurück.", completion = "{name}, wir haben gute Nachrichten und ein kleines Problem…", sourceObjectiveStatus = "unverified-source-field" }
quests[26836] = { id = 26836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet den Steinvater... und Flint", description = "Wir haben herausgefunden, wo der Steinvater gefangen gehalten wird, und prompt ist der junge Flint losgerannt, um ihn zu befreien!\n\nIch muss Euch nicht sagen, dass das gar nicht gut ist. Flint könnte ebenfalls gefangen genommen werden - oder noch Schlimmeres!\n\nDer Häuptling der Steintroggs, Felsmagen, befindet sich am äußersten Ende der Felssimse über der Nadelfelsschlucht im Norden. Bitte, {name}, Ihr müsst Flint folgen und den Steinvater befreien, bevor wir sie beide verlieren!", sourceObjective = "Befreit Steinvater Erzmantel.", progress = "Ihr müsst Steinvater Erzmantel befreien. Ihr dürft keine Zeit verschwenden, {name}!", completion = "{name}! Ihr habt es geschafft! Wie können wir das jemals wieder gutmachen?", sourceObjectiveStatus = "unverified-source-field" }
quests[26837] = { id = 26837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grabungsstätte der Forscherliga", description = "Hört einmal, {name}... Ihr scheint genau richtig zu sein.\n\nBronwyn Hackschlag von der Forscherliga sucht neue Rekruten für seine Grabungsstätte am Schlingendornkap. Ich persönlich verstehe ja nicht, warum er nicht einfach nach Beutebucht geht und dort seine Rekruten sucht... Piraten kann man leicht mit ein paar Goldstücken überreden.\n\nWie auch immer - gerüchteweise hört man, dass er endlich etwas dort im Dschungel gefunden hat. Ich frage mich, was das sein könnte?", sourceObjective = "Sprecht mit Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.", sourceObjectiveStatus = "unverified-source-field" }
quests[26838] = { id = 26838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man keine Ahnung hat ...", description = "Vor einigen Jahren hat Captain Kurzen aus Sturmwind eine Brigade ins Schlingendorntal gebracht. Die Einzelheiten seiner Mission sind immer noch unklar. Kurzen fiel schnell dem Wahnsinn anheim, genau wie seine Männer ... außer einigen Rebellen, die es sich zur Aufgabe gemacht haben, das Böse, das Kurzen angerichtet hat, ungeschehen zu machen.\n\nWie ich bereits sagte, das war vor vielen Jahren. Jetzt ist mir zu Ohren gekommen, dass Kurzen tot ist. Doch diese Rebellen bestehen immer noch auf ihrer Rebellion. Wenn Ihr Ermittlungen anstellen wollt, findet Ihr sie in einem Lager an der nördlichen Grenze von Schlingendorntal.", sourceObjective = "Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.", completion = "Willkommen in unserem Lager, {class}. Ihr seid genau zum richtigen Zeitpunkt eingetroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[26839] = { id = 26839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Auszeit nehmen!", description = "Sagt einmal, {class}, Ihr seht erschöpft aus. Diese schwere Geldbörse ... äh, ich meine ... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.\n\nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht ... es ist alles vorhanden.\n\nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.", sourceObjective = "Sucht Sassy Hartzang in Hartzangs Versteck am Schlingendornkap auf.Sagt einmal, {class}, Ihr seht erschöpft aus. Diese schwere Geldbörse... äh, ich meine... schwere Ausrüstung mit sich herumzuschleppen muss doch eine große Belastung für Euren armen Rücken sein.\n\nSassy Hartzang hat vor Kurzem ein erstklassiges Fünf-Sterne Erholungszentrum am Schlingendornkap eröffnet. Ballonfahrten, Ruderboottouren, Tagesausflüge nach Beutebucht... es ist alles vorhanden.\n\nIhr solltet dem Zentrum wirklich einen Besuch abstatten. Ich muss Euch nur anschauen und weiß, dass Ihr nach so vielen schwierigen, lukrativen Abenteuern eine Erholung braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26840] = { id = 26840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr ins Hochland", description = "Jetzt, da Orgrimmar sicher ist und wir unsere Verbündeten des Drachenmalklans hinter uns wissen, können wir unsere Aufmerksamkeit dem Schattenhochland und der Vernichtung der Truppen von Todesschwinge zuwenden.\n\nIch brauche die Besten der Horde an der Front. Damit meine ich Euch. Und all Eure Freunde.\n\nDas Hochland wird UNS gehören!\n\nBenutzt das neue Portal, das Ihr erschaffen habt, um in den Hafen des Drachenmals zurückzukehren. Meldet Euch bei Zaela, um zu sehen, wo sie Euch am meisten braucht.", sourceObjective = "Benutzt das Portal des Drachenmals in Orgrimmar, um in den Hafen des Drachenmals im Schattenhochland zurückzukehren und sprecht mit Zaela.", completion = "{name}! Ist in Orgrimmar alles in Ordnung?\n\nWie Ihr seht, läuft der Bau des Hafens des Drachenmals auf Hochtouren. Sollte mein Volk an der Macht der Horde bisher gezweifelt haben, wird dieses beeindruckende Gebäude und die Geschwindigkeit, mit der es errichtet wurde, sie eines besseren belehren.\n\nEs beginnt eine neue Zeit für das Drachenmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[26841] = { id = 26841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verbotene Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten überbracht und stammt von unserer Magierlehrerin Rhyanda. Wie es aussieht, möchte Rhyanda mit Euch sprechen, wenn Ihr einen Moment erübrigen könnt. Lest es und bringt es ihr danach bitte.", sourceObjective = "Sprecht mit Rhyanda in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[26842] = { id = 26842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ein Gnoll, dort ein Gnoll", description = "Seid gegrüßt, {class}. Wir haben ein Problem und ich würde Euch bitten, uns zu helfen.\n\nEs handelt sich um Gnolle. Westlich der Stadt streift ein ganzer Haufen dieser Viecher durch die Hügel. Eigentlich ist das kein Grund, beunruhigt zu sein, aber normalerweise haben wir hier keine Gnolle in Loch Modan.\n\nMich interessiert, wo sie herkamen, allerdings bin ich nicht neugierig genug, um diese räudigen Dinger zu fragen. Ich bin der Meinung, wir sollten sie loswerden. Bringt mir Beweise, dass Ihr sie getötet habt und ich werde Euch ein beachtliches Kopfgeld zahlen.", sourceObjective = "Sammelt 12 Gnollohren von Spähern und Schlägern der Moosfelle.", progress = "Nun, habt Ihr einige Ohren für mich?", completion = "Gut gemacht, mein Freund. Ein {class} wie Ihr wäre mir hier ganz nützlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[26843] = { id = 26843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein winziger, cleverer Kommandant", description = "Wir schlagen uns in diesem Land schon seit Jahren mit Kobolden herum. Bisher waren sie kaum mehr als ein Ärgernis. Aber sie werden bei ihren Diebstählen immer geschickter.\n\nIch glaube, einer von ihnen ist irgendwie klüger als üblich. Aber das wird nicht mehr lange der Fall sein!\n\nIch möchte, dass Ihr zu ihrem Lager im Süden geht und sicherstellt, dass sich dort kein \"Obermotz\" Kobold befindet, der die anderen aufwiegelt. Achtet darauf, auch die Höhle zu untersuchen. Das wäre mit ziemlicher Sicherheit ein guter Ort.\n\nAch ja, und übt keine Zurückhaltung, wenn es darum geht, die Kobolde, die Euch unterwegs begegnen, zu beseitigen.", sourceObjective = "Tötet \"Kommandant\" Nazrim.", completion = "Also hatte ich recht! Die Frage ist, was diese kleinen Nervensägen geplant haben ...", sourceObjectiveStatus = "unverified-source-field" }
quests[26844] = { id = 26844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Regen in die Traufe", description = "Jetzt, da wir diese kleinen Quälgeister erledigt haben, müssen wir uns um weitere Dinge kümmern.\n\nDie Tunnelratten schwärmen durch die ganze Silberbachmine. Sie schlagen Lager auf und schnüffeln überall herum. Dabei ziehen sie immer weitere Kreise. Die gierigen kleinen Viecher suchen bestimmt nach Beute.\n\nVermessen und nach Futter wühlen ist ja schön und gut, solange es nicht auf Zwergenland stattfindet! Kümmert Euch um diese Tunnelratten und meldet Euch dann wieder bei mir.", sourceObjective = "Tötet 5 Feldmesser der Tunnelratten und 5 Futterwühler der Tunnelratten.", completion = "Gut, gut! Jetzt ist mir klar, was in der Mine vor sich geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26845] = { id = 26845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer hat hier das Sagen?", description = "Dorli hat mir von diesem verrückten Troggsklaven-Vorhaben erzählt, das bei den Kobolden im Gange ist. Wenn Ihr bisher noch nicht mit ihr gesprochen habt, schlage ich vor, dass Ihr das nachholt. Ich möchte dieser Sache auf den Grund gehen.\n\nIm wahrsten Sinne des Wortes! Wer immer hier die Fäden zieht, sitzt garantiert ganz unten in der Mine und gibt von dort die Befehle. Ich will, dass er zur Strecke gebracht wird.\n\nFindet den gerissenen Schlauberger, der die Geomanten und Gräber dirigiert und bringt mir seinen Kopf.", sourceObjective = "Bringt mir den Kopf von Vorarbeiter Scharfspott.", progress = "War Moira vielleicht dort unten? Wunder gibt es ja immer wieder.", completion = "Das ist der Kopf eines Gnolls. Versucht Ihr, mich hier hinter's Licht zu führen, {name}?\n\nWenn nicht, habe ich nicht den Hauch einer Ahnung, was hier vor sich geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[26846] = { id = 26846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fieser Plan", description = "Ich habe herausgefunden, was diese Ratten im Schilde führen. Der Grund, warum so viele von ihnen draußen herumlaufen, ist, dass sie Troggs dazu gebracht haben, für sie in der Mine zu schürfen!\n\nDie Geomanten der Tunnelratten haben irgendeinen Taschenspielertrick ersonnen, mit dem sie die Troggs kontrollieren können. Irgendwas mit Kreaturen der Erde oder so ähnlich.\n\nFaszinierend, aber wir können ihnen das nicht durchgehen lassen. Beseitigt diese Geomanten so schnell wie möglich.", sourceObjective = "Tötet 5 Geomanten der Tunnelratten.", completion = "Ich bin sicher, dass das nur funktioniert hat, weil die Troggs ohnehin nicht die hellsten sind. Aber wir Zwerge waren auch einmal Kreaturen der Erde.\n\nVon einem Kobold herumkommandiert zu werden ist so entwürdigend ... Ich bin froh, dass wir nicht herausgefunden haben, ob sie dazu auch in der Lage gewesen wären.", sourceObjectiveStatus = "unverified-source-field" }
quests[26854] = { id = 26854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Pilot", description = "Mein Freund Mori Hangflug, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe des Nachts nördlich des Helmsbettsees und westlich des Tunnels das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, {name}. Sucht ihn.", sourceObjective = "Findet Pilot Hanglug nördlich des Helmsbettsees.", completion = "Hier liegt die Leiche eines Zwergs - zerfetzt, gefroren und von Aasfressern blankgefressen. Seine Hand umklammert ein Buch, das die grob hingekritzelten Aufzeichnungen von Mori Hangflug enthält. Um ihn gehüllt, nach wie vor in sehr gutem Zustand, ist eine Brigadiersweste.\n\nAn diesem grausigen Ort muss der Pilot der Belagerungsmaschinen sein Ende gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26855] = { id = 26855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilotenrache", description = "Hangflug schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hangflugs Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hangflug in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", sourceObjective = "Tötet Marterklaue.\n\nBringt Pilot Hammerfuß am Südtoraußenposten die räudige Klaue des Bären und Hangflugs Tagebuch.", progress = "Hallo, {name}. Wisst Ihr etwas über den Verbleib meines Freundes Hangflug?", completion = "Das sind traurige Neuigkeiten, denn Hangflug war ein guter Freund. Ich wünschte, ich hätte dort mit Euch sein können, als Ihr die Bestie Marterklaue gefunden habt!\n\nDanke, {name}. Eure Tat wird den Piloten der Belagerungsbrigade von Eisenschmiede in Erinnerung bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[26856] = { id = 26856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werft die Invasion zurück", description = "Diese Höhle war einst ein Ort großer Ehre. Man brachte junge Krieger hierher, damit sie zum ersten Mal in ihrem Leben einen Erdbohrerwurm erlegen. Daran erinnern wir Orcs uns das ganze Leben lang.\n\nDie Agenten der Brennenden Klinge haben die Einwohner der Höhle versklavt und wollen nun Orgrimmar mit ihren Troggverbündeten angreifen.\n\nWenn Ihr ihre Leutnants zur Strecke bringt, könntet Ihr sie unvorbereitet erwischen und diese Invasion verhindern, bevor sie überhaupt beginnt.", sourceObjective = "Tötet Flintauge, Bazzalan und Jergosh den Herbeirufer.", completion = "Ihr habt es geschafft, {name}! Ihr habt die Invasion der Brennenden Klinge verhindert, bevor sie begann! Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[26857] = { id = 26857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssions Diener", description = "Wenn der Drache das Fragment hat, müssen wir seine Aufmerksamkeit auf seinen Hort lenken.\n\nGeht zu Abyssions Hort gleich östlich von hier und besiegt seine Untergebenen. Das wird ihn früher oder später dazu veranlassen, mit dem Weltensäulenfragment aufzutauchen.", sourceObjective = "Besiegt 8 Zwielicht- oder Drachkineinheiten in Abyssions Hort.", completion = "Das sollte genügen, um die Aufmerksamkeit des Drachen zu erregen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[26858] = { id = 26858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taragaman der Hungerleider", description = "Der Sengenden Klinge ist es gelungen, einen widerlichen Dämonen zu beschwören, den sie Taragaman den Hungerleider nennen. Er soll bei der Übernahme von Orgrimmar den ersten Angriff leiten.\n\nBeeilt Euch und tötet Taragaman im Namen des Kriegshäuptlings! Lok'tar ogar!", sourceObjective = "Holt das Herz von Taragaman dem Hungerleider.", progress = "Zeigt mir das Herz von Taragaman, wenn er tot ist.", completion = "Meine Kinder werden noch Loblieder auf Euch singen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[26860] = { id = 26860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutwurst aus Thelsamar", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr <ein toller/eine tolle:c> {class} seid.\n\nBringt mir frische Bärenrücken und überlasst das Kochen nur mir!", sourceObjective = "Sammelt 8 Bärenrücken von Schwarzbären in Loch Modan.", progress = "Ich bin so weit, dass ich mit dem Kochen anfangen könnte; habt Ihr die Bärenrücken?", completion = "Vielen Dank! Die Rückenstücke sind meine eigene geheime Erweiterung des Rezepts... aber hier habt Ihr die Anleitung, wie man es mit jeder beliebigen Sorte Bärenfleisch herstellen kann.\n\nObendrein gibt's noch eine frische Portion, die ich selbst gekocht habe. Frisch schmecken sie am besten!", sourceObjectiveStatus = "unverified-source-field" }
